import * as THREE from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { CSS3DRenderer, CSS3DObject } from 'three/addons/renderers/CSS3DRenderer.js';

let camera, scene, rendererCSS3D, rendererWebGL;
let controls;

init();

function init() {

	const controlsDomElement = document.createElement( 'div' );
	controlsDomElement.style.position = 'absolute';
	controlsDomElement.style.top = '0';
	controlsDomElement.style.width = '100%';
	controlsDomElement.style.height = '100%';
	document.body.appendChild( controlsDomElement );

	rendererCSS3D = new CSS3DRenderer();
	rendererCSS3D.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( rendererCSS3D.domElement );

	rendererWebGL = new THREE.WebGLRenderer( { antialias: true, alpha: true } );
	rendererWebGL.domElement.style.position = 'absolute';
	rendererWebGL.domElement.style.top = '0';
	rendererWebGL.domElement.style.pointerEvents = 'none';
	rendererWebGL.setPixelRatio( window.devicePixelRatio );
	rendererWebGL.setSize( window.innerWidth, window.innerHeight );
	rendererWebGL.toneMapping = THREE.NeutralToneMapping;
	rendererWebGL.setAnimationLoop( animate );
	document.body.appendChild( rendererWebGL.domElement );

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 1, 10000 );
	camera.position.set( - 1000, 500, 1500 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xf0f0f0 );

	// Add room
	const roomGeometry = new THREE.EdgesGeometry( new THREE.BoxGeometry( 4000, 2000, 4000, 10, 5, 10 ) );
	const roomMaterial = new THREE.LineBasicMaterial( { color: 0x000000, opacity: 0.2, transparent: true } );
	const room = new THREE.LineSegments( roomGeometry, roomMaterial );
	scene.add( room );

	// Add light
	const hemisphereLight = new THREE.HemisphereLight( 0xffffff, 0x444444, 4 );
	hemisphereLight.position.set( - 25, 100, 50 );
	scene.add( hemisphereLight );

	// Add cutout mesh
	const geometry = new THREE.PlaneGeometry( 1024, 768 );
	const material = new THREE.MeshBasicMaterial( {
		color: 0xff0000,
		blending: THREE.NoBlending,
		opacity: 0,
		premultipliedAlpha: true
	} );
	const mesh = new THREE.Mesh( geometry, material );
	scene.add( mesh );

	// Add frame
	const frame = buildFrame( 1024, 768, 50 );
	scene.add( frame );

	// Add CSS3D element
	const iframe = document.createElement( 'iframe' );
	iframe.style.width = '1028px';
	iframe.style.height = '768px';
	iframe.style.border = '0px';
	iframe.style.backfaceVisibility = 'hidden';
	iframe.src = './#webgl_animation_keyframes';
	scene.add( new CSS3DObject( iframe ) );

	// Add controls
	controls = new OrbitControls( camera );
	controls.connect( controlsDomElement );
	controls.addEventListener( 'start', () => iframe.style.pointerEvents = 'none' );
	controls.addEventListener( 'end', () => iframe.style.pointerEvents = 'auto' );
	controls.enableDamping = true;

	window.addEventListener( 'resize', onWindowResize );

}

function buildFrame( width, height, thickness ) {

	const group = new THREE.Group();
	const material = new THREE.MeshStandardMaterial( { color: 0x2200ff } );

	// Create the frame border
	const outerShape = new THREE.Shape();
	outerShape.moveTo( - ( width / 2 + thickness ), - ( height / 2 + thickness ) );
	outerShape.lineTo( width / 2 + thickness, - ( height / 2 + thickness ) );
	outerShape.lineTo( width / 2 + thickness, height / 2 + thickness );
	outerShape.lineTo( - ( width / 2 + thickness ), height / 2 + thickness );
	outerShape.lineTo( - ( width / 2 + thickness ), - ( height / 2 + thickness ) );

	// Create inner rectangle (hole)
	const innerHole = new THREE.Path();
	innerHole.moveTo( - width / 2, - height / 2 );
	innerHole.lineTo( width / 2, - height / 2 );
	innerHole.lineTo( width / 2, height / 2 );
	innerHole.lineTo( - width / 2, height / 2 );
	innerHole.lineTo( - width / 2, - height / 2 );

	outerShape.holes.push( innerHole );

	const frameGeometry = new THREE.ExtrudeGeometry( outerShape, {
		depth: thickness,
		bevelEnabled: false
	} );

	const frameMesh = new THREE.Mesh( frameGeometry, material );
	frameMesh.position.z = - thickness / 2;
	group.add( frameMesh );

	// Add back plane
	const backGeometry = new THREE.PlaneGeometry( width + ( thickness * 2 ), height + ( thickness * 2 ) );
	const backMesh = new THREE.Mesh( backGeometry, material );
	backMesh.position.set( 0, 0, - thickness / 2 );
	backMesh.rotation.y = Math.PI;
	group.add( backMesh );

	return group;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	rendererWebGL.setSize( window.innerWidth, window.innerHeight );
	rendererCSS3D.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	controls.update();

	rendererWebGL.render( scene, camera );
	rendererCSS3D.render( scene, camera );

}

import * as THREE from 'three';

import { TrackballControls } from 'three/addons/controls/TrackballControls.js';
import { PDBLoader } from 'three/addons/loaders/PDBLoader.js';
import { CSS3DRenderer, CSS3DObject, CSS3DSprite } from 'three/addons/renderers/CSS3DRenderer.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let camera, scene, renderer;
let controls;
let root;

const objects = [];
const tmpVec1 = new THREE.Vector3();
const tmpVec2 = new THREE.Vector3();
const tmpVec3 = new THREE.Vector3();
const tmpVec4 = new THREE.Vector3();
const offset = new THREE.Vector3();

const VIZ_TYPE = {
	'Atoms': 0,
	'Bonds': 1,
	'Atoms + Bonds': 2
};

const MOLECULES = {
	'Ethanol': 'ethanol.pdb',
	'Aspirin': 'aspirin.pdb',
	'Caffeine': 'caffeine.pdb',
	'Nicotine': 'nicotine.pdb',
	'LSD': 'lsd.pdb',
	'Cocaine': 'cocaine.pdb',
	'Cholesterol': 'cholesterol.pdb',
	'Lycopene': 'lycopene.pdb',
	'Glucose': 'glucose.pdb',
	'Aluminium oxide': 'Al2O3.pdb',
	'Cubane': 'cubane.pdb',
	'Copper': 'cu.pdb',
	'Fluorite': 'caf2.pdb',
	'Salt': 'nacl.pdb',
	'YBCO superconductor': 'ybco.pdb',
	'Buckyball': 'buckyball.pdb',
	// 'Diamond': 'diamond.pdb',
	'Graphite': 'graphite.pdb'
};

const params = {
	vizType: 2,
	molecule: 'caffeine.pdb'
};

const loader = new PDBLoader();
const colorSpriteMap = {};
const baseSprite = document.createElement( 'img' );

init();
animate();

function init() {

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 1, 5000 );
	camera.position.z = 1000;

	scene = new THREE.Scene();

	root = new THREE.Object3D();
	scene.add( root );

	//

	renderer = new CSS3DRenderer();
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.getElementById( 'container' ).appendChild( renderer.domElement );

	//

	controls = new TrackballControls( camera, renderer.domElement );
	controls.rotateSpeed = 0.5;

	//

	baseSprite.onload = function () {

		loadMolecule( params.molecule );

	};

	baseSprite.src = 'textures/sprites/ball.png';

	//

	window.addEventListener( 'resize', onWindowResize );

	//

	const gui = new GUI();

	gui.add( params, 'vizType', VIZ_TYPE ).onChange( changeVizType );
	gui.add( params, 'molecule', MOLECULES ).onChange( loadMolecule );
	gui.open();

}

function changeVizType( value ) {

	if ( value === 0 ) showAtoms();
	else if ( value === 1 ) showBonds();
	else showAtomsBonds();

}

//

function showAtoms() {

	for ( let i = 0; i < objects.length; i ++ ) {

		const object = objects[ i ];

		if ( object instanceof CSS3DSprite ) {

			object.element.style.display = '';
			object.visible = true;

		} else {

			object.element.style.display = 'none';
			object.visible = false;

		}

	}

}

function showBonds() {

	for ( let i = 0; i < objects.length; i ++ ) {

		const object = objects[ i ];

		if ( object instanceof CSS3DSprite ) {

			object.element.style.display = 'none';
			object.visible = false;

		} else {

			object.element.style.display = '';
			object.element.style.height = object.userData.bondLengthFull;
			object.visible = true;

		}

	}

}

function showAtomsBonds() {

	for ( let i = 0; i < objects.length; i ++ ) {

		const object = objects[ i ];

		object.element.style.display = '';
		object.visible = true;

		if ( ! ( object instanceof CSS3DSprite ) ) {

			object.element.style.height = object.userData.bondLengthShort;

		}

	}

}

//

function colorify( ctx, width, height, color ) {

	const r = color.r, g = color.g, b = color.b;

	const imageData = ctx.getImageData( 0, 0, width, height );
	const data = imageData.data;

	for ( let i = 0, l = data.length; i < l; i += 4 ) {

		data[ i + 0 ] *= r;
		data[ i + 1 ] *= g;
		data[ i + 2 ] *= b;

	}

	ctx.putImageData( imageData, 0, 0 );

}

function imageToCanvas( image ) {

	const width = image.width;
	const height = image.height;

	const canvas = document.createElement( 'canvas' );

	canvas.width = width;
	canvas.height = height;

	const context = canvas.getContext( '2d' );
	context.drawImage( image, 0, 0, width, height );

	return canvas;

}

//

function loadMolecule( model ) {

	const url = 'models/pdb/' + model;

	for ( let i = 0; i < objects.length; i ++ ) {

		const object = objects[ i ];
		object.parent.remove( object );

	}

	objects.length = 0;

	loader.load( url, function ( pdb ) {

		const geometryAtoms = pdb.geometryAtoms;
		const geometryBonds = pdb.geometryBonds;
		const json = pdb.json;

		geometryAtoms.computeBoundingBox();
		geometryAtoms.boundingBox.getCenter( offset ).negate();

		geometryAtoms.translate( offset.x, offset.y, offset.z );
		geometryBonds.translate( offset.x, offset.y, offset.z );

		const positionAtoms = geometryAtoms.getAttribute( 'position' );
		const colorAtoms = geometryAtoms.getAttribute( 'color' );

		const position = new THREE.Vector3();
		const color = new THREE.Color();

		for ( let i = 0; i < positionAtoms.count; i ++ ) {

			position.fromBufferAttribute( positionAtoms, i );
			color.fromBufferAttribute( colorAtoms, i );

			const atomJSON = json.atoms[ i ];
			const element = atomJSON[ 4 ];

			if ( ! colorSpriteMap[ element ] ) {

				const canvas = imageToCanvas( baseSprite );
				const context = canvas.getContext( '2d' );

				colorify( context, canvas.width, canvas.height, color );

				const dataUrl = canvas.toDataURL();

				colorSpriteMap[ element ] = dataUrl;

			}

			const colorSprite = colorSpriteMap[ element ];

			const atom = document.createElement( 'img' );
			atom.src = colorSprite;

			const object = new CSS3DSprite( atom );
			object.position.copy( position );
			object.position.multiplyScalar( 75 );

			object.matrixAutoUpdate = false;
			object.updateMatrix();

			root.add( object );

			objects.push( object );

		}

		const positionBonds = geometryBonds.getAttribute( 'position' );

		const start = new THREE.Vector3();
		const end = new THREE.Vector3();

		for ( let i = 0; i < positionBonds.count; i += 2 ) {

			start.fromBufferAttribute( positionBonds, i );
			end.fromBufferAttribute( positionBonds, i + 1 );

			start.multiplyScalar( 75 );
			end.multiplyScalar( 75 );

			tmpVec1.subVectors( end, start );
			const bondLength = tmpVec1.length() - 50;

			//

			let bond = document.createElement( 'div' );
			bond.className = 'bond';
			bond.style.height = bondLength + 'px';

			let object = new CSS3DObject( bond );
			object.position.copy( start );
			object.position.lerp( end, 0.5 );

			object.userData.bondLengthShort = bondLength + 'px';
			object.userData.bondLengthFull = ( bondLength + 55 ) + 'px';

			//

			const axis = tmpVec2.set( 0, 1, 0 ).cross( tmpVec1 );
			const radians = Math.acos( tmpVec3.set( 0, 1, 0 ).dot( tmpVec4.copy( tmpVec1 ).normalize() ) );

			const objMatrix = new THREE.Matrix4().makeRotationAxis( axis.normalize(), radians );
			object.matrix.copy( objMatrix );
			object.quaternion.setFromRotationMatrix( object.matrix );

			object.matrixAutoUpdate = false;
			object.updateMatrix();

			root.add( object );

			objects.push( object );

			//

			const joint = new THREE.Object3D();
			joint.position.copy( start );
			joint.position.lerp( end, 0.5 );

			joint.matrix.copy( objMatrix );
			joint.quaternion.setFromRotationMatrix( joint.matrix );

			joint.matrixAutoUpdate = false;
			joint.updateMatrix();

			bond = document.createElement( 'div' );
			bond.className = 'bond';
			bond.style.height = bondLength + 'px';

			object = new CSS3DObject( bond );
			object.rotation.y = Math.PI / 2;

			object.matrixAutoUpdate = false;
			object.updateMatrix();

			object.userData.bondLengthShort = bondLength + 'px';
			object.userData.bondLengthFull = ( bondLength + 55 ) + 'px';

			object.userData.joint = joint;

			joint.add( object );
			root.add( joint );

			objects.push( object );

		}

		//console.log( "CSS3DObjects:", objects.length );

		changeVizType( params.vizType );

	} );


}

//

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	requestAnimationFrame( animate );
	controls.update();

	const time = Date.now() * 0.0004;

	root.rotation.x = time;
	root.rotation.y = time * 0.7;

	render();

}

function render() {

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { CSS3DRenderer, CSS3DObject } from 'three/addons/renderers/CSS3DRenderer.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let camera, scene, renderer;

let scene2, renderer2;

const frustumSize = 500;

init();
animate();

function init() {

	const aspect = window.innerWidth / window.innerHeight;
	camera = new THREE.OrthographicCamera( frustumSize * aspect / - 2, frustumSize * aspect / 2, frustumSize / 2, frustumSize / - 2, 1, 1000 );

	camera.position.set( - 200, 200, 200 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xf0f0f0 );

	scene2 = new THREE.Scene();

	const material = new THREE.MeshBasicMaterial( { color: 0x000000, wireframe: true, wireframeLinewidth: 1, side: THREE.DoubleSide } );

	// left
	createPlane(
		100, 100,
		'chocolate',
		new THREE.Vector3( - 50, 0, 0 ),
		new THREE.Euler( 0, - 90 * THREE.MathUtils.DEG2RAD, 0 )
	);
	// right
	createPlane(
		100, 100,
		'saddlebrown',
		new THREE.Vector3( 0, 0, 50 ),
		new THREE.Euler( 0, 0, 0 )
	);
	// top
	createPlane(
		100, 100,
		'yellowgreen',
		new THREE.Vector3( 0, 50, 0 ),
		new THREE.Euler( - 90 * THREE.MathUtils.DEG2RAD, 0, 0 )
	);
	// bottom
	createPlane(
		300, 300,
		'seagreen',
		new THREE.Vector3( 0, - 50, 0 ),
		new THREE.Euler( - 90 * THREE.MathUtils.DEG2RAD, 0, 0 )
	);

	//

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );

	renderer2 = new CSS3DRenderer();
	renderer2.setSize( window.innerWidth, window.innerHeight );
	renderer2.domElement.style.position = 'absolute';
	renderer2.domElement.style.top = 0;
	document.body.appendChild( renderer2.domElement );

	const controls = new OrbitControls( camera, renderer2.domElement );
	controls.minZoom = 0.5;
	controls.maxZoom = 2;

	function createPlane( width, height, cssColor, pos, rot ) {

		const element = document.createElement( 'div' );
		element.style.width = width + 'px';
		element.style.height = height + 'px';
		element.style.opacity = 0.75;
		element.style.background = cssColor;

		const object = new CSS3DObject( element );
		object.position.copy( pos );
		object.rotation.copy( rot );
		scene2.add( object );

		const geometry = new THREE.PlaneGeometry( width, height );
		const mesh = new THREE.Mesh( geometry, material );
		mesh.position.copy( object.position );
		mesh.rotation.copy( object.rotation );
		scene.add( mesh );

	}

	window.addEventListener( 'resize', onWindowResize );
	createPanel();

}

function onWindowResize() {

	const aspect = window.innerWidth / window.innerHeight;

	camera.left = - frustumSize * aspect / 2;
	camera.right = frustumSize * aspect / 2;
	camera.top = frustumSize / 2;
	camera.bottom = - frustumSize / 2;

	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	renderer2.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	requestAnimationFrame( animate );

	renderer.render( scene, camera );
	renderer2.render( scene2, camera );

}

function createPanel() {

	const panel = new GUI();
	const folder1 = panel.addFolder( 'camera setViewOffset' ).close();

	const settings = {
		'setViewOffset'() {

			folder1.children[ 1 ].enable().setValue( window.innerWidth );
			folder1.children[ 2 ].enable().setValue( window.innerHeight );
			folder1.children[ 3 ].enable().setValue( 0 );
			folder1.children[ 4 ].enable().setValue( 0 );
			folder1.children[ 5 ].enable().setValue( window.innerWidth );
			folder1.children[ 6 ].enable().setValue( window.innerHeight );

		},
		'fullWidth': 0,
		'fullHeight': 0,
		'offsetX': 0,
		'offsetY': 0,
		'width': 0,
		'height': 0,
		'clearViewOffset'() {

			folder1.children[ 1 ].setValue( 0 ).disable();
