	material = new THREE.MeshBasicMaterial( {
		color: 0xffffff,
		map: mapGrid
	} );

	object = new THREE.Mesh( new THREE.IcosahedronGeometry( 75, 0 ), material );
	object.position.set( - 200, 0, 200 );
	object.name = 'Icosahedron';
