	const controls = new OrbitControls( camera, renderer.domElement );
	controls.enableZoom = false;

	const geometry = new THREE.PlaneGeometry( terrainWidthExtents, terrainDepthExtents, terrainWidth - 1, terrainDepth - 1 );
