	function addGeo( geo, x, y, z, ry ) {

		position.set( x, y, z );
		rotation.set( 0, ry, 0 );

		matrix.compose( position, quaternion.setFromEuler( rotation ), scale );

		const positionAttribute = geo.getAttribute( 'position' );

