		color: 0xffffff,
		opacity: 0.5,
		side: THREE.DoubleSide,
		transparent: true
	} );

	const meshGeometry = new ConvexGeometry( vertices );

	const mesh = new THREE.Mesh( meshGeometry, meshMaterial );
	group.add( mesh );

	//

	window.addEventListener( 'resize', onWindowResize );

