class WaterMaterial extends THREE.MeshStandardMaterial {

	constructor( parameters ) {

		super();

		this.defines = {

			'STANDARD': '',
			'USE_UV': '',
			'WIDTH': WIDTH.toFixed( 1 ),
			'BOUNDS': BOUNDS.toFixed( 1 ),

		};

		this.extra = {};

		this.addParameter( 'heightmap', null );

		this.setValues( parameters );

	}

	addParameter( name, value ) {

		this.extra[ name ] = value;
		Object.defineProperty( this, name, {
			get: () => ( this.extra[ name ] ),
			set: ( v ) => {

				this.extra[ name ] = v;
				if ( this.userData.shader ) this.userData.shader.uniforms[ name ].value = this.extra[ name ];

			}
		} );

	}

	onBeforeCompile( shader ) {

		for ( const name in this.extra ) {

			shader.uniforms[ name ] = { value: this.extra[ name ] };

		}

		shader.vertexShader = shader.vertexShader.replace( '#include <common>', shaderChange.common );
		//shader.vertexShader = 'uniform sampler2D heightmap;\n' + shader.vertexShader;
		shader.vertexShader = shader.vertexShader.replace( '#include <beginnormal_vertex>', shaderChange.beginnormal_vertex );
		shader.vertexShader = shader.vertexShader.replace( '#include <begin_vertex>', shaderChange.begin_vertex );

		this.userData.shader = shader;

	}

}


const shaderChange = {

	heightmap_frag: /* glsl */`
	#include <common>

	uniform vec2 mousePos;
	uniform float mouseSize;
	uniform float viscosity;
	uniform float deep;

	void main()	{

		vec2 cellSize = 1.0 / resolution.xy;

		vec2 uv = gl_FragCoord.xy * cellSize;

		// heightmapValue.x == height from previous frame
		// heightmapValue.y == height from penultimate frame
		// heightmapValue.z, heightmapValue.w not used
		vec4 heightmapValue = texture2D( heightmap, uv );

		// Get neighbours
		vec4 north = texture2D( heightmap, uv + vec2( 0.0, cellSize.y ) );
		vec4 south = texture2D( heightmap, uv + vec2( 0.0, - cellSize.y ) );
		vec4 east = texture2D( heightmap, uv + vec2( cellSize.x, 0.0 ) );
		vec4 west = texture2D( heightmap, uv + vec2( - cellSize.x, 0.0 ) );

		//float newHeight = ( ( north.x + south.x + east.x + west.x ) * 0.5 - heightmapValue.y ) * viscosity;
		float newHeight = ( ( north.x + south.x + east.x + west.x ) * 0.5 - (heightmapValue.y) ) * viscosity;


		// Mouse influence
		float mousePhase = clamp( length( ( uv - vec2( 0.5 ) ) * BOUNDS - vec2( mousePos.x, - mousePos.y ) ) * PI / mouseSize, 0.0, PI );
		//newHeight += ( cos( mousePhase ) + 1.0 ) * 0.28 * 10.0;
		newHeight -= ( cos( mousePhase ) + 1.0 ) * deep;

		heightmapValue.y = heightmapValue.x;
		heightmapValue.x = newHeight;

		gl_FragColor = heightmapValue;

	}
	`,
	// FOR MATERIAL
	common: /* glsl */`
	#include <common>
	uniform sampler2D heightmap;
	`,
	beginnormal_vertex: /* glsl */`
	vec2 cellSize = vec2( 1.0 / WIDTH, 1.0 / WIDTH );
	vec3 objectNormal = vec3(
	( texture2D( heightmap, uv + vec2( - cellSize.x, 0 ) ).x - texture2D( heightmap, uv + vec2( cellSize.x, 0 ) ).x ) * WIDTH / BOUNDS,
	( texture2D( heightmap, uv + vec2( 0, - cellSize.y ) ).x - texture2D( heightmap, uv + vec2( 0, cellSize.y ) ).x ) * WIDTH / BOUNDS,
	1.0 );
	#ifdef USE_TANGENT
		vec3 objectTangent = vec3( tangent.xyz );
	#endif
	`,
	begin_vertex: /* glsl */`
	float heightValue = texture2D( heightmap, uv ).x;
	vec3 transformed = vec3( position.x, position.y, heightValue );
	#ifdef USE_ALPHAHASH
		vPosition = vec3( position );
	#endif
	`,
};

import * as THREE from 'three';

import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

import { VertexNormalsHelper } from 'three/addons/helpers/VertexNormalsHelper.js';
import { VertexTangentsHelper } from 'three/addons/helpers/VertexTangentsHelper.js';

let scene, renderer;
let camera, light;
let vnh;
let vth;

init();

function init() {

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	//

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.z = 400;

	scene = new THREE.Scene();

	light = new THREE.PointLight();
	light.position.set( 200, 100, 150 );
	scene.add( light );

	scene.add( new THREE.PointLightHelper( light, 15 ) );

	const gridHelper = new THREE.GridHelper( 400, 40, 0x0000ff, 0x808080 );
	gridHelper.position.y = - 150;
	gridHelper.position.x = - 150;
	scene.add( gridHelper );

	const polarGridHelper = new THREE.PolarGridHelper( 200, 16, 8, 64, 0x0000ff, 0x808080 );
	polarGridHelper.position.y = - 150;
	polarGridHelper.position.x = 200;
	scene.add( polarGridHelper );

	const loader = new GLTFLoader();
	loader.load( 'models/gltf/LeePerrySmith/LeePerrySmith.glb', function ( gltf ) {

		const mesh = gltf.scene.children[ 0 ];

		mesh.geometry.computeTangents(); // generates bad data due to degenerate UVs

		const group = new THREE.Group();
		group.scale.multiplyScalar( 50 );
		scene.add( group );

		// To make sure that the matrixWorld is up to date for the boxhelpers
		group.updateMatrixWorld( true );

		group.add( mesh );

		vnh = new VertexNormalsHelper( mesh, 5 );
		scene.add( vnh );

		vth = new VertexTangentsHelper( mesh, 5 );
		scene.add( vth );

		scene.add( new THREE.BoxHelper( mesh ) );

		const wireframe = new THREE.WireframeGeometry( mesh.geometry );
		let line = new THREE.LineSegments( wireframe );
		line.material.depthTest = false;
		line.material.opacity = 0.25;
		line.material.transparent = true;
		line.position.x = 4;
		group.add( line );
		scene.add( new THREE.BoxHelper( line ) );

		const edges = new THREE.EdgesGeometry( mesh.geometry );
		line = new THREE.LineSegments( edges );
		line.material.depthTest = false;
		line.material.opacity = 0.25;
		line.material.transparent = true;
		line.position.x = - 4;
		group.add( line );
		scene.add( new THREE.BoxHelper( line ) );

		scene.add( new THREE.BoxHelper( group ) );
		scene.add( new THREE.BoxHelper( scene ) );


	} );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	const time = - performance.now() * 0.0003;

	camera.position.x = 400 * Math.cos( time );
	camera.position.z = 400 * Math.sin( time );
	camera.lookAt( scene.position );

	light.position.x = Math.sin( time * 1.7 ) * 300;
	light.position.y = Math.cos( time * 1.5 ) * 400;
	light.position.z = Math.cos( time * 1.3 ) * 300;

	if ( vnh ) vnh.update();
	if ( vth ) vth.update();

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import TWEEN from 'three/addons/libs/tween.module.js';

let camera, scene, renderer, timer, mesh;

const amount = 100;

const count = Math.pow( amount, 2 );
const dummy = new THREE.Object3D();

const seeds = [];
const baseColors = [];

const color = new THREE.Color();
const colors = [ new THREE.Color( 0x00ffff ), new THREE.Color( 0xffff00 ), new THREE.Color( 0xff00ff ) ];
const animation = { t: 0 };
let currentColorIndex = 0;
let nextColorIndex = 1;

const maxDistance = 75;
const cameraTarget = new THREE.Vector3();

init();

function init() {

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.toneMapping = THREE.NeutralToneMapping;
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 10, 10, 10 );
	camera.lookAt( 0, 0, 0 );

	const pmremGenerator = new THREE.PMREMGenerator( renderer );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xadd8e6 );
	scene.environment = pmremGenerator.fromScene( new RoomEnvironment(), 0.04 ).texture;

	timer = new THREE.Timer();
	timer.connect( document );

	const loader = new THREE.TextureLoader();
	const texture = loader.load( 'textures/edge3.jpg' );
	texture.colorSpace = THREE.SRGBColorSpace;

	const geometry = new THREE.BoxGeometry();
	const material = new THREE.MeshStandardMaterial( { map: texture } );

	mesh = new THREE.InstancedMesh( geometry, material, count );
	mesh.instanceMatrix.setUsage( THREE.DynamicDrawUsage ); // will be updated every frame
	scene.add( mesh );

	let i = 0;
	const offset = ( amount - 1 ) / 2;

	for ( let x = 0; x < amount; x ++ ) {

		for ( let z = 0; z < amount; z ++ ) {

			dummy.position.set( offset - x, 0, offset - z );
			dummy.scale.set( 1, 2, 1 );

			dummy.updateMatrix();

			color.setHSL( 1, 0.5 + ( Math.random() * 0.5 ), 0.5 + ( Math.random() * 0.5 ) );
			baseColors.push( color.getHex() );

			mesh.setMatrixAt( i, dummy.matrix );
			mesh.setColorAt( i, color.multiply( colors[ 0 ] ) );

			i ++;

			seeds.push( Math.random() );

		}

	}

	//

	window.addEventListener( 'resize', onWindowResize );

	setInterval( startTween, 3000 );

}

function startTween() {

	// tween for animating color transition

	new TWEEN.Tween( animation )
		.to( {
			t: 1
		}, 2000 )
		.easing( TWEEN.Easing.Sinusoidal.In )
		.onComplete( () => {

			animation.t = 0;

			currentColorIndex = nextColorIndex;
			nextColorIndex ++;

			if ( nextColorIndex >= colors.length ) nextColorIndex = 0;

		} )
		.start();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function animate() {

	timer.update();

	const time = timer.getElapsed();

	TWEEN.update();

	// animate camera

	camera.position.x = Math.sin( time / 4 ) * 10;
	camera.position.z = Math.cos( time / 4 ) * 10;
	camera.position.y = 8 + Math.cos( time / 2 ) * 2;

	cameraTarget.x = Math.sin( time / 4 ) * - 8;
	cameraTarget.z = Math.cos( time / 2 ) * - 8;

	camera.lookAt( cameraTarget );

	camera.up.x = Math.sin( time / 400 );

	// animate instance positions and colors

	for ( let i = 0; i < mesh.count; i ++ ) {

		mesh.getMatrixAt( i, dummy.matrix );
		dummy.matrix.decompose( dummy.position, dummy.quaternion, dummy.scale );

		dummy.position.y = Math.abs( Math.sin( ( time + seeds[ i ] ) * 2 + seeds[ i ] ) );

		dummy.updateMatrix();

		mesh.setMatrixAt( i, dummy.matrix );

		// colors

		if ( animation.t > 0 ) {

			const currentColor = colors[ currentColorIndex ];
			const nextColor = colors[ nextColorIndex ];

			const f = dummy.position.length() / maxDistance;

			if ( f <= animation.t ) {

				color.set( baseColors[ i ] ).multiply( nextColor );

			} else {

				color.set( baseColors[ i ] ).multiply( currentColor );

			}

			mesh.setColorAt( i, color );

