let renderer, scene, camera, stats;
let pointclouds;
let raycaster;
let intersection = null;
let spheresIndex = 0;
let timer;
let toggle = 0;

const pointer = new THREE.Vector2();
const spheres = [];

const threshold = 0.1;
const pointSize = 0.05;
const width = 80;
const length = 160;
const rotateY = new THREE.Matrix4().makeRotationY( 0.005 );

init();

function generatePointCloudGeometry( color, width, length ) {

	const geometry = new THREE.BufferGeometry();
	const numPoints = width * length;

	const positions = new Float32Array( numPoints * 3 );
	const colors = new Float32Array( numPoints * 3 );

	let k = 0;

	for ( let i = 0; i < width; i ++ ) {

		for ( let j = 0; j < length; j ++ ) {

			const u = i / width;
			const v = j / length;
			const x = u - 0.5;
			const y = ( Math.cos( u * Math.PI * 4 ) + Math.sin( v * Math.PI * 8 ) ) / 20;
			const z = v - 0.5;

			positions[ 3 * k ] = x;
			positions[ 3 * k + 1 ] = y;
			positions[ 3 * k + 2 ] = z;

			const intensity = ( y + 0.1 ) * 5;
			colors[ 3 * k ] = color.r * intensity;
			colors[ 3 * k + 1 ] = color.g * intensity;
			colors[ 3 * k + 2 ] = color.b * intensity;

			k ++;

		}

	}

	geometry.setAttribute( 'position', new THREE.BufferAttribute( positions, 3 ) );
	geometry.setAttribute( 'color', new THREE.BufferAttribute( colors, 3 ) );
	geometry.computeBoundingBox();

	return geometry;

}

function generatePointcloud( color, width, length ) {

	const geometry = generatePointCloudGeometry( color, width, length );
	const material = new THREE.PointsMaterial( { size: pointSize, vertexColors: true } );

	return new THREE.Points( geometry, material );

}

function generateIndexedPointcloud( color, width, length ) {

	const geometry = generatePointCloudGeometry( color, width, length );
	const numPoints = width * length;
	const indices = new Uint16Array( numPoints );

	let k = 0;

	for ( let i = 0; i < width; i ++ ) {

		for ( let j = 0; j < length; j ++ ) {

			indices[ k ] = k;
			k ++;

		}

	}

	geometry.setIndex( new THREE.BufferAttribute( indices, 1 ) );

	const material = new THREE.PointsMaterial( { size: pointSize, vertexColors: true } );

	return new THREE.Points( geometry, material );

}

function generateIndexedWithOffsetPointcloud( color, width, length ) {

	const geometry = generatePointCloudGeometry( color, width, length );
	const numPoints = width * length;
	const indices = new Uint16Array( numPoints );

	let k = 0;

	for ( let i = 0; i < width; i ++ ) {

		for ( let j = 0; j < length; j ++ ) {

			indices[ k ] = k;
			k ++;

		}

	}

	geometry.setIndex( new THREE.BufferAttribute( indices, 1 ) );
	geometry.addGroup( 0, indices.length );

	const material = new THREE.PointsMaterial( { size: pointSize, vertexColors: true } );

	return new THREE.Points( geometry, material );

}

function init() {

	const container = document.getElementById( 'container' );

	scene = new THREE.Scene();

	timer = new THREE.Timer();
	timer.connect( document );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 10000 );
	camera.position.set( 10, 10, 10 );
	camera.lookAt( scene.position );
	camera.updateMatrix();

	//

	const pcBuffer = generatePointcloud( new THREE.Color( 1, 0, 0 ), width, length );
	pcBuffer.scale.set( 5, 10, 10 );
	pcBuffer.position.set( - 5, 0, 0 );
	scene.add( pcBuffer );

	const pcIndexed = generateIndexedPointcloud( new THREE.Color( 0, 1, 0 ), width, length );
	pcIndexed.scale.set( 5, 10, 10 );
	pcIndexed.position.set( 0, 0, 0 );
	scene.add( pcIndexed );

	const pcIndexedOffset = generateIndexedWithOffsetPointcloud( new THREE.Color( 0, 1, 1 ), width, length );
	pcIndexedOffset.scale.set( 5, 10, 10 );
	pcIndexedOffset.position.set( 5, 0, 0 );
	scene.add( pcIndexedOffset );

	pointclouds = [ pcBuffer, pcIndexed, pcIndexedOffset ];

	//

	const sphereGeometry = new THREE.SphereGeometry( 0.1, 32, 32 );
	const sphereMaterial = new THREE.MeshBasicMaterial( { color: 0xff0000 } );

	for ( let i = 0; i < 40; i ++ ) {

		const sphere = new THREE.Mesh( sphereGeometry, sphereMaterial );
		scene.add( sphere );
		spheres.push( sphere );

	}

	//

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	//

	raycaster = new THREE.Raycaster();
	raycaster.params.Points.threshold = threshold;

	//

	stats = new Stats();
	container.appendChild( stats.dom );

	//

	window.addEventListener( 'resize', onWindowResize );
	document.addEventListener( 'pointermove', onPointerMove );

}

function onPointerMove( event ) {

	pointer.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	pointer.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	render();
	stats.update();

}

function render() {

	camera.applyMatrix4( rotateY );
	camera.updateMatrixWorld();

	raycaster.setFromCamera( pointer, camera );

	const intersections = raycaster.intersectObjects( pointclouds, false );
	intersection = ( intersections.length ) > 0 ? intersections[ 0 ] : null;

	if ( toggle > 0.02 && intersection !== null ) {

		spheres[ spheresIndex ].position.copy( intersection.point );
		spheres[ spheresIndex ].scale.set( 1, 1, 1 );
		spheresIndex = ( spheresIndex + 1 ) % spheres.length;

		toggle = 0;

	}

	for ( let i = 0; i < spheres.length; i ++ ) {

		const sphere = spheres[ i ];
		sphere.scale.multiplyScalar( 0.98 );
		sphere.scale.clampScalar( 0.01, 1 );

	}

	toggle += timer.getDelta();

	renderer.render( scene, camera );

}

import * as THREE from 'three';

let camera, scene, renderer;
let plane;
let pointer, raycaster, isShiftDown = false;

let rollOverMesh, rollOverMaterial;
let cubeGeo, cubeMaterial;

const objects = [];

init();
render();

function init() {

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 10000 );
	camera.position.set( 500, 800, 1300 );
	camera.lookAt( 0, 0, 0 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xf0f0f0 );

	// roll-over helpers

	const rollOverGeo = new THREE.BoxGeometry( 50, 50, 50 );
	rollOverMaterial = new THREE.MeshBasicMaterial( { color: 0xff0000, opacity: 0.5, transparent: true } );
	rollOverMesh = new THREE.Mesh( rollOverGeo, rollOverMaterial );
	scene.add( rollOverMesh );

	// cubes

	const map = new THREE.TextureLoader().load( 'textures/square-outline-textured.png' );
	map.colorSpace = THREE.SRGBColorSpace;
	cubeGeo = new THREE.BoxGeometry( 50, 50, 50 );
	cubeMaterial = new THREE.MeshLambertMaterial( { color: 0xfeb74c, map: map } );

	// grid

	const gridHelper = new THREE.GridHelper( 1000, 20 );
	scene.add( gridHelper );

	//

	raycaster = new THREE.Raycaster();
	pointer = new THREE.Vector2();

	const geometry = new THREE.PlaneGeometry( 1000, 1000 );
	geometry.rotateX( - Math.PI / 2 );

	plane = new THREE.Mesh( geometry, new THREE.MeshBasicMaterial( { visible: false } ) );
	scene.add( plane );

	objects.push( plane );

	// lights

	const ambientLight = new THREE.AmbientLight( 0x606060, 3 );
	scene.add( ambientLight );

	const directionalLight = new THREE.DirectionalLight( 0xffffff, 3 );
	directionalLight.position.set( 1, 0.75, 0.5 ).normalize();
	scene.add( directionalLight );

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );

	document.addEventListener( 'pointermove', onPointerMove );
	document.addEventListener( 'pointerdown', onPointerDown );
	document.addEventListener( 'keydown', onDocumentKeyDown );
	document.addEventListener( 'keyup', onDocumentKeyUp );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	render();

}

function onPointerMove( event ) {

	pointer.set( ( event.clientX / window.innerWidth ) * 2 - 1, - ( event.clientY / window.innerHeight ) * 2 + 1 );

	raycaster.setFromCamera( pointer, camera );

	const intersects = raycaster.intersectObjects( objects, false );

	if ( intersects.length > 0 ) {

		const intersect = intersects[ 0 ];

		rollOverMesh.position.copy( intersect.point ).add( intersect.face.normal );
		rollOverMesh.position.divideScalar( 50 ).floor().multiplyScalar( 50 ).addScalar( 25 );

		render();

	}

}

function onPointerDown( event ) {

	pointer.set( ( event.clientX / window.innerWidth ) * 2 - 1, - ( event.clientY / window.innerHeight ) * 2 + 1 );

	raycaster.setFromCamera( pointer, camera );

	const intersects = raycaster.intersectObjects( objects, false );

	if ( intersects.length > 0 ) {

		const intersect = intersects[ 0 ];

		// delete cube

		if ( isShiftDown ) {

			if ( intersect.object !== plane ) {

				scene.remove( intersect.object );

				objects.splice( objects.indexOf( intersect.object ), 1 );

			}

			// create cube

		} else {

			const voxel = new THREE.Mesh( cubeGeo, cubeMaterial );
			voxel.position.copy( intersect.point ).add( intersect.face.normal );
			voxel.position.divideScalar( 50 ).floor().multiplyScalar( 50 ).addScalar( 25 );
			scene.add( voxel );

			objects.push( voxel );

		}

		render();

	}

}

function onDocumentKeyDown( event ) {

	switch ( event.keyCode ) {

		case 16: isShiftDown = true; break;

	}

}

function onDocumentKeyUp( event ) {

	switch ( event.keyCode ) {

		case 16: isShiftDown = false; break;

	}

}

function render() {

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

import { FlyControls } from 'three/addons/controls/FlyControls.js';
import { Lensflare, LensflareElement } from 'three/addons/objects/Lensflare.js';

let container, stats;

let camera, scene, renderer;
let controls;

const timer = new THREE.Timer();
timer.connect( document );

init();

function init() {

	container = document.createElement( 'div' );
	document.body.appendChild( container );

	// camera

	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 15000 );
	camera.position.z = 250;

	// scene

	scene = new THREE.Scene();
	scene.background = new THREE.Color().setHSL( 0.51, 0.4, 0.01, THREE.SRGBColorSpace );
	scene.fog = new THREE.Fog( scene.background, 3500, 15000 );

	// world

	const s = 250;

	const geometry = new THREE.BoxGeometry( s, s, s );
	const material = new THREE.MeshPhongMaterial( { color: 0xffffff, specular: 0xffffff, shininess: 50 } );

	for ( let i = 0; i < 3000; i ++ ) {

		const mesh = new THREE.Mesh( geometry, material );

		mesh.position.x = 8000 * ( 2.0 * Math.random() - 1.0 );
		mesh.position.y = 8000 * ( 2.0 * Math.random() - 1.0 );
		mesh.position.z = 8000 * ( 2.0 * Math.random() - 1.0 );

		mesh.rotation.x = Math.random() * Math.PI;
		mesh.rotation.y = Math.random() * Math.PI;
		mesh.rotation.z = Math.random() * Math.PI;

		mesh.matrixAutoUpdate = false;
		mesh.updateMatrix();

		scene.add( mesh );

	}


	// lights

	const dirLight = new THREE.DirectionalLight( 0xffffff, 0.15 );
	dirLight.position.set( 0, - 1, 0 ).normalize();
	dirLight.color.setHSL( 0.1, 0.7, 0.5 );
	scene.add( dirLight );

	// lensflares
	const textureLoader = new THREE.TextureLoader();

	const textureFlare0 = textureLoader.load( 'textures/lensflare/lensflare0.png' );
	const textureFlare3 = textureLoader.load( 'textures/lensflare/lensflare3.png' );

	addLight( 0.55, 0.9, 0.5, 5000, 0, - 1000 );
	addLight( 0.08, 0.8, 0.5, 0, 0, - 1000 );
	addLight( 0.995, 0.5, 0.9, 5000, 5000, - 1000 );

	function addLight( h, s, l, x, y, z ) {

		const light = new THREE.PointLight( 0xffffff, 1.5, 2000, 0 );
		light.color.setHSL( h, s, l );
		light.position.set( x, y, z );
		scene.add( light );

		const lensflare = new Lensflare();
		lensflare.addElement( new LensflareElement( textureFlare0, 700, 0, light.color ) );
		lensflare.addElement( new LensflareElement( textureFlare3, 60, 0.6 ) );
		lensflare.addElement( new LensflareElement( textureFlare3, 70, 0.7 ) );
		lensflare.addElement( new LensflareElement( textureFlare3, 120, 0.9 ) );
		lensflare.addElement( new LensflareElement( textureFlare3, 70, 1 ) );
		light.add( lensflare );

	}

	// renderer

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	//

	controls = new FlyControls( camera, renderer.domElement );

	controls.movementSpeed = 2500;
	controls.domElement = container;
	controls.rollSpeed = Math.PI / 6;
	controls.autoForward = false;
	controls.dragToLook = false;

	// stats

	stats = new Stats();
	container.appendChild( stats.dom );

	// events

	window.addEventListener( 'resize', onWindowResize );

}

//

function onWindowResize() {

	renderer.setSize( window.innerWidth, window.innerHeight );

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

}

//

function animate() {

	timer.update();

	render();
	stats.update();

}

function render() {

	const delta = timer.getDelta();

	controls.update( delta );
	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

import { LightProbeGenerator } from 'three/addons/lights/LightProbeGenerator.js';

import { LightProbeHelper } from 'three/addons/helpers/LightProbeHelper.js';

let mesh, renderer, scene, camera;

let gui;

let lightProbe;
let directionalLight;

// linear color space
const API = {
	lightProbeIntensity: 1.0,
	directionalLightIntensity: 0.6,
	envMapIntensity: 1
};

init();

function init() {

	// renderer
	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );

	// tone mapping
	renderer.toneMapping = THREE.NoToneMapping;


	// scene
	scene = new THREE.Scene();

	// camera
	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( 0, 0, 30 );

	// controls
	const controls = new OrbitControls( camera, renderer.domElement );
	controls.addEventListener( 'change', render );
	controls.minDistance = 10;
	controls.maxDistance = 50;
	controls.enablePan = false;

	// probe
	lightProbe = new THREE.LightProbe();
	scene.add( lightProbe );

	// light
	directionalLight = new THREE.DirectionalLight( 0xffffff, API.directionalLightIntensity );
	directionalLight.position.set( 10, 10, 10 );
	scene.add( directionalLight );

	// envmap
	const genCubeUrls = function ( prefix, postfix ) {

		return [
			prefix + 'px' + postfix, prefix + 'nx' + postfix,
			prefix + 'py' + postfix, prefix + 'ny' + postfix,
			prefix + 'pz' + postfix, prefix + 'nz' + postfix
		];

	};

	const urls = genCubeUrls( 'textures/cube/pisa/', '.png' );

	new THREE.CubeTextureLoader().load( urls, function ( cubeTexture ) {

		scene.background = cubeTexture;

		lightProbe.copy( LightProbeGenerator.fromCubeTexture( cubeTexture ) );
		lightProbe.intensity = API.lightProbeIntensity;
		lightProbe.position.set( - 10, 0, 0 ); // position not used in scene lighting calculations (helper honors the position, however)

		const geometry = new THREE.SphereGeometry( 5, 64, 32 );
		//const geometry = new THREE.TorusKnotGeometry( 4, 1.5, 256, 32, 2, 3 );

		const material = new THREE.MeshStandardMaterial( {
			color: 0xffffff,
			metalness: 0,
			roughness: 0,
			envMap: cubeTexture,
			envMapIntensity: API.envMapIntensity,
		} );

		// mesh
		mesh = new THREE.Mesh( geometry, material );
		scene.add( mesh );

		// helper
		const helper = new LightProbeHelper( lightProbe, 1 );
		scene.add( helper );

		render();

	} );


	// gui
	gui = new GUI( { title: 'Intensity' } );

	gui.add( API, 'lightProbeIntensity', 0, 1, 0.02 )
		.name( 'light probe' )
		.onChange( function () {

			lightProbe.intensity = API.lightProbeIntensity; render();

		} );

	gui.add( API, 'directionalLightIntensity', 0, 1, 0.02 )
		.name( 'directional light' )
		.onChange( function () {

			directionalLight.intensity = API.directionalLightIntensity; render();

		} );

	gui.add( API, 'envMapIntensity', 0, 1, 0.02 )
		.name( 'envMap' )
		.onChange( function () {

			mesh.material.envMapIntensity = API.envMapIntensity; render();

		} );

	// listener
	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	renderer.setSize( window.innerWidth, window.innerHeight );

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	render();

}

function render() {

	renderer.render( scene, camera );

}

