		map.anisotropy = 4;
		map.repeat.set( 10, 24 );
		map.colorSpace = THREE.SRGBColorSpace;
		floorMat.map = map;
		floorMat.needsUpdate = true;

	} );
	textureLoader.load( 'textures/hardwood2_bump.jpg', function ( map ) {

		map.wrapS = THREE.RepeatWrapping;
		map.wrapT = THREE.RepeatWrapping;
		map.anisotropy = 4;
		map.repeat.set( 10, 24 );
		floorMat.bumpMap = map;
		floorMat.needsUpdate = true;

	} );
	textureLoader.load( 'textures/hardwood2_roughness.jpg', function ( map ) {

		map.wrapS = THREE.RepeatWrapping;
		map.wrapT = THREE.RepeatWrapping;
		map.anisotropy = 4;
		map.repeat.set( 10, 24 );
		floorMat.roughnessMap = map;
		floorMat.needsUpdate = true;

	} );

	cubeMat = new THREE.MeshStandardMaterial( {
		roughness: 0.7,
		color: 0xffffff,
		bumpScale: 1,
		metalness: 0.2
	} );
	textureLoader.load( 'textures/brick_diffuse.jpg', function ( map ) {

		map.wrapS = THREE.RepeatWrapping;
		map.wrapT = THREE.RepeatWrapping;
		map.anisotropy = 4;
		map.repeat.set( 1, 1 );
		map.colorSpace = THREE.SRGBColorSpace;
		cubeMat.map = map;
		cubeMat.needsUpdate = true;

	} );
	textureLoader.load( 'textures/brick_bump.jpg', function ( map ) {

		map.wrapS = THREE.RepeatWrapping;
		map.wrapT = THREE.RepeatWrapping;
		map.anisotropy = 4;
		map.repeat.set( 1, 1 );
		cubeMat.bumpMap = map;
		cubeMat.needsUpdate = true;

	} );

	ballMat = new THREE.MeshStandardMaterial( {
		color: 0xffffff,
		roughness: 0.5,
		metalness: 1.0
	} );
	textureLoader.load( 'textures/planets/earth_atmos_2048.jpg', function ( map ) {

		map.anisotropy = 4;
		map.colorSpace = THREE.SRGBColorSpace;
		ballMat.map = map;
		ballMat.needsUpdate = true;

	} );
	textureLoader.load( 'textures/planets/earth_specular_2048.jpg', function ( map ) {

		map.anisotropy = 4;
		map.colorSpace = THREE.SRGBColorSpace;
		ballMat.metalnessMap = map;
		ballMat.needsUpdate = true;

	} );

	const floorGeometry = new THREE.PlaneGeometry( 20, 20 );
	const floorMesh = new THREE.Mesh( floorGeometry, floorMat );
	floorMesh.receiveShadow = true;
	floorMesh.rotation.x = - Math.PI / 2.0;
	scene.add( floorMesh );

	const ballGeometry = new THREE.SphereGeometry( 0.25, 32, 32 );
	const ballMesh = new THREE.Mesh( ballGeometry, ballMat );
	ballMesh.position.set( 1, 0.25, 1 );
	ballMesh.rotation.y = Math.PI;
	ballMesh.castShadow = true;
	scene.add( ballMesh );

	const boxGeometry = new THREE.BoxGeometry( 0.5, 0.5, 0.5 );
	const boxMesh = new THREE.Mesh( boxGeometry, cubeMat );
	boxMesh.position.set( - 0.5, 0.25, - 1 );
	boxMesh.castShadow = true;
	scene.add( boxMesh );

	const boxMesh2 = new THREE.Mesh( boxGeometry, cubeMat );
	boxMesh2.position.set( 0, 0.25, - 5 );
	boxMesh2.castShadow = true;
	scene.add( boxMesh2 );

	const boxMesh3 = new THREE.Mesh( boxGeometry, cubeMat );
	boxMesh3.position.set( 7, 0.25, 0 );
	boxMesh3.castShadow = true;
	scene.add( boxMesh3 );


	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.toneMapping = THREE.ReinhardToneMapping;
	container.appendChild( renderer.domElement );


	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 1;
	controls.maxDistance = 20;

	window.addEventListener( 'resize', onWindowResize );


	const gui = new GUI();

	gui.add( params, 'hemiIrradiance', Object.keys( hemiLuminousIrradiances ) );
	gui.add( params, 'bulbPower', Object.keys( bulbLuminousPowers ) );
	gui.add( params, 'exposure', 0, 1 );
	gui.add( params, 'shadows' );
	gui.open();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function animate() {

	renderer.toneMappingExposure = Math.pow( params.exposure, 5.0 ); // to allow for very bright scenes.
	renderer.shadowMap.enabled = params.shadows;
	bulbLight.castShadow = params.shadows;

	if ( params.shadows !== previousShadowMap ) {

		ballMat.needsUpdate = true;
		cubeMat.needsUpdate = true;
		floorMat.needsUpdate = true;
		previousShadowMap = params.shadows;

	}

	bulbLight.power = bulbLuminousPowers[ params.bulbPower ];
	bulbMat.emissiveIntensity = bulbLight.intensity / Math.pow( 0.02, 2.0 ); // convert from intensity to irradiance at bulb surface

	hemiLight.intensity = hemiLuminousIrradiances[ params.hemiIrradiance ];
	const time = Date.now() * 0.0005;

	bulbLight.position.y = Math.cos( time ) * 0.75 + 1.25;

	renderer.render( scene, camera );

	stats.update();

}

import * as THREE from 'three';

import Stats from 'three/addons/libs/stats.module.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RectAreaLightHelper } from 'three/addons/helpers/RectAreaLightHelper.js';
import { RectAreaLightUniformsLib } from 'three/addons/lights/RectAreaLightUniformsLib.js';

let renderer, scene, camera;
let rectLight1, rectLight2, rectLight3;
let timer, stats;

init();

function init() {

	timer = new THREE.Timer();

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animation );
	document.body.appendChild( renderer.domElement );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( 0, 5, - 15 );

	scene = new THREE.Scene();

	RectAreaLightUniformsLib.init();

	rectLight1 = new THREE.RectAreaLight( 0xff0000, 5, 4, 10 );
	rectLight1.position.set( - 5, 6, 5 );
	scene.add( rectLight1 );

	rectLight2 = new THREE.RectAreaLight( 0x00ff00, 5, 4, 10 );
	rectLight2.position.set( 0, 6, 5 );
	scene.add( rectLight2 );

	rectLight3 = new THREE.RectAreaLight( 0x0000ff, 5, 4, 10 );
	rectLight3.position.set( 5, 6, 5 );
	scene.add( rectLight3 );

	scene.add( new RectAreaLightHelper( rectLight1 ) );
	scene.add( new RectAreaLightHelper( rectLight2 ) );
	scene.add( new RectAreaLightHelper( rectLight3 ) );

	const geoFloor = new THREE.BoxGeometry( 2000, 0.1, 2000 );
	const matStdFloor = new THREE.MeshStandardMaterial( { color: 0x444444 } );
	matStdFloor.roughnessMap = createCheckerTexture( 400 );
	const mshStdFloor = new THREE.Mesh( geoFloor, matStdFloor );
	scene.add( mshStdFloor );

	const geoKnot = new THREE.TorusKnotGeometry( 1.5, 0.5, 200, 16 );
	const matKnot = new THREE.MeshStandardMaterial( { color: 0xffffff, roughness: 0, metalness: 0 } );
	const meshKnot = new THREE.Mesh( geoKnot, matKnot );
	meshKnot.position.set( 0, 5.5, 0 );
	scene.add( meshKnot );

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.target.copy( meshKnot.position );
	controls.update();

	//

	window.addEventListener( 'resize', onWindowResize );

	stats = new Stats();
	document.body.appendChild( stats.dom );

}

function createCheckerTexture( repeat = 1 ) {

	const canvas = document.createElement( 'canvas' );
	canvas.width = 2;
	canvas.height = 2;

	const ctx = canvas.getContext( '2d' );
	ctx.fillStyle = '#000';
	ctx.fillRect( 0, 0, 2, 2 );
	ctx.fillStyle = '#fff';
	ctx.fillRect( 0, 0, 1, 1 );
	ctx.fillRect( 1, 1, 1, 1 );

	const texture = new THREE.CanvasTexture( canvas );
	texture.repeat.set( repeat, repeat );
	texture.magFilter = THREE.NearestFilter;
	texture.wrapS = THREE.RepeatWrapping;
	texture.wrapT = THREE.RepeatWrapping;

	return texture;

}

function onWindowResize() {

	renderer.setSize( window.innerWidth, window.innerHeight );
	camera.aspect = ( window.innerWidth / window.innerHeight );
	camera.updateProjectionMatrix();

}

function animation() {

	timer.update();

	const delta = timer.getDelta();

	rectLight1.rotation.y += - delta;
	rectLight2.rotation.y += delta * .5;
	rectLight3.rotation.y += delta;

	renderer.render( scene, camera );

	stats.update();

}

