		[ material, scale * 1.5, [ 0, - d / 2, 0 ], geometry2 ],
		[ material, scale * 1.5, [ d, - d / 2, 0 ], geometry3 ],

		[ material, scale * 1.5, [ - d, d / 2, 0 ], geometry4 ],
		[ material, scale * 1.5, [ 0, d / 2, 0 ], geometry5 ],
		[ material, scale * 1.5, [ d, d / 2, 0 ], geometry6 ],
