let line, renderer, scene, camera, camera2, controls;
let cameraPerspective, cameraOrthographic;
let line1;
let matLine, matLineBasic, matLineDashed;
let gui;

// viewport
let insetWidth;
let insetHeight;

const frustumSize = 60;

init();

function init() {

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setClearColor( 0x000000, 0.0 );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	const aspect = window.innerWidth / window.innerHeight;

	cameraPerspective = new THREE.PerspectiveCamera( 40, aspect, 1, 1000 );
	cameraPerspective.position.set( - 40, 0, 60 );

	cameraOrthographic = new THREE.OrthographicCamera( - frustumSize * aspect / 2, frustumSize * aspect / 2, frustumSize / 2, - frustumSize / 2, 1, 1000 );
	cameraOrthographic.position.copy( cameraPerspective.position );

