		mesh.scale.multiplyScalar( 0.0006 );

		mesh.castShadow = true;
		mesh.receiveShadow = true;

		scene.add( mesh );

	} );

	// Lights

	scene.add( new THREE.HemisphereLight( 0x8d7c7c, 0x494966, 3 ) );

