			scene.background = texture;
			scene.environment = texture;

		} );

	};

	loadEnvironment( params.resolution, params.type );

	const gui = new GUI();

	gui.add( params, 'autoRotate' );
	gui.add( params, 'metalness', 0, 1, 0.01 );
	gui.add( params, 'roughness', 0, 1, 0.01 );
	gui.add( params, 'exposure', 0, 4, 0.01 );
	gui.add( params, 'resolution', [ '2k', '4k' ] ).onChange( ( value ) => {

		loadEnvironment( value, params.type );

	} );
	gui.add( params, 'type', [ 'HalfFloatType', 'FloatType' ] ).onChange( ( value ) => {

		loadEnvironment( params.resolution, value );

	} );

	gui.open();

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;

	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function render() {

	torusMesh.material.roughness = params.roughness;
	torusMesh.material.metalness = params.metalness;

	if ( params.autoRotate ) {

		torusMesh.rotation.y += 0.005;

	}

	renderer.toneMappingExposure = params.exposure;

	controls.update();

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { TTFLoader } from 'three/addons/loaders/TTFLoader.js';
import { Font } from 'three/addons/loaders/FontLoader.js';
import { TextGeometry } from 'three/addons/geometries/TextGeometry.js';

let container;
let camera, cameraTarget, scene, renderer;
let group, textMesh1, textMesh2, textGeo, material;
let firstLetter = true;

let text = 'three.js';
const depth = 20,
	size = 70,
	hover = 30,
	curveSegments = 4,
	bevelThickness = 2,
	bevelSize = 1.5;

let font = null;
const mirror = true;

let targetRotation = 0;
let targetRotationOnPointerDown = 0;

let pointerX = 0;
let pointerXOnPointerDown = 0;

let windowHalfX = window.innerWidth / 2;

init();

function init() {

	container = document.createElement( 'div' );
	document.body.appendChild( container );

	// CAMERA

	camera = new THREE.PerspectiveCamera( 30, window.innerWidth / window.innerHeight, 1, 1500 );
	camera.position.set( 0, 400, 700 );

	cameraTarget = new THREE.Vector3( 0, 150, 0 );

	// SCENE

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x000000 );
	scene.fog = new THREE.Fog( 0x000000, 250, 1400 );

	// LIGHTS

	const dirLight1 = new THREE.DirectionalLight( 0xffffff, 0.4 );
	dirLight1.position.set( 0, 0, 1 ).normalize();
	scene.add( dirLight1 );

	const dirLight2 = new THREE.DirectionalLight( 0xffffff, 2 );
	dirLight2.position.set( 0, hover, 10 ).normalize();
	dirLight2.color.setHSL( Math.random(), 1, 0.5, THREE.SRGBColorSpace );
	scene.add( dirLight2 );

	material = new THREE.MeshPhongMaterial( { color: 0xffffff, flatShading: true } );

	group = new THREE.Group();
	group.position.y = 100;

	scene.add( group );

	const loader = new TTFLoader();

	loader.load( 'fonts/ttf/kenpixel.ttf', function ( json ) {

		font = new Font( json );
		createText();

	} );

	const plane = new THREE.Mesh(
		new THREE.PlaneGeometry( 10000, 10000 ),
		new THREE.MeshBasicMaterial( { color: 0xffffff, opacity: 0.5, transparent: true } )
	);
	plane.position.y = 100;
	plane.rotation.x = - Math.PI / 2;
	scene.add( plane );

	// RENDERER

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	// EVENTS

	container.style.touchAction = 'none';
	container.addEventListener( 'pointerdown', onPointerDown );

	document.addEventListener( 'keypress', onDocumentKeyPress );
	document.addEventListener( 'keydown', onDocumentKeyDown );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	windowHalfX = window.innerWidth / 2;

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function onDocumentKeyDown( event ) {

	if ( firstLetter ) {

		firstLetter = false;
		text = '';

	}

	const keyCode = event.keyCode;

	// backspace

	if ( keyCode === 8 ) {

		event.preventDefault();

		text = text.substring( 0, text.length - 1 );
		refreshText();

		return false;

	}

}

function onDocumentKeyPress( event ) {

	const keyCode = event.which;

	// backspace

	if ( keyCode === 8 ) {

		event.preventDefault();

	} else {

		const ch = String.fromCharCode( keyCode );
		text += ch;

		refreshText();

	}

}

function createText() {

	textGeo = new TextGeometry( text, {

		font: font,

		size: size,
		depth: depth,
		curveSegments: curveSegments,

		bevelThickness: bevelThickness,
		bevelSize: bevelSize,
		bevelEnabled: true

	} );

	textGeo.computeBoundingBox();
	textGeo.computeVertexNormals();

	const centerOffset = - 0.5 * ( textGeo.boundingBox.max.x - textGeo.boundingBox.min.x );

	textMesh1 = new THREE.Mesh( textGeo, material );

	textMesh1.position.x = centerOffset;
	textMesh1.position.y = hover;
	textMesh1.position.z = 0;

	textMesh1.rotation.x = 0;
	textMesh1.rotation.y = Math.PI * 2;

	group.add( textMesh1 );

	if ( mirror ) {

		textMesh2 = new THREE.Mesh( textGeo, material );

		textMesh2.position.x = centerOffset;
		textMesh2.position.y = - hover;
		textMesh2.position.z = depth;

		textMesh2.rotation.x = Math.PI;
		textMesh2.rotation.y = Math.PI * 2;

		group.add( textMesh2 );

	}

}

function refreshText() {

	group.remove( textMesh1 );
	if ( mirror ) group.remove( textMesh2 );

	if ( ! text ) return;

	createText();

}

function onPointerDown( event ) {

	if ( event.isPrimary === false ) return;

	pointerXOnPointerDown = event.clientX - windowHalfX;
	targetRotationOnPointerDown = targetRotation;

	document.addEventListener( 'pointermove', onPointerMove );
	document.addEventListener( 'pointerup', onPointerUp );

}

function onPointerMove( event ) {

	if ( event.isPrimary === false ) return;

	pointerX = event.clientX - windowHalfX;

	targetRotation = targetRotationOnPointerDown + ( pointerX - pointerXOnPointerDown ) * 0.02;

}

function onPointerUp( event ) {

	if ( event.isPrimary === false ) return;

	document.removeEventListener( 'pointermove', onPointerMove );
	document.removeEventListener( 'pointerup', onPointerUp );

}

//

function animate() {

	group.rotation.y += ( targetRotation - group.rotation.y ) * 0.05;

	camera.lookAt( cameraTarget );

	renderer.render( scene, camera );

}

