import { radixSort } from 'three/addons/utils/SortUtils.js';

let stats, gui, guiStatsEl;
let camera, controls, scene, renderer;
let geometries, mesh;
const ids = [];
const matrix = new THREE.Matrix4();

//

const position = new THREE.Vector3();
const rotation = new THREE.Euler();
const quaternion = new THREE.Quaternion();
const scale = new THREE.Vector3();

//

const MAX_GEOMETRY_COUNT = 20000;

const Method = {
	BATCHED: 'BATCHED',
	NAIVE: 'NAIVE'
};

const api = {
	method: Method.BATCHED,
	count: 256,
	dynamic: 16,

	transparent: true,
	sortObjects: true,
	perObjectFrustumCulled: true,
	useCustomSort: true,
};

init();
initGeometries();
initMesh();

//

function randomizeMatrix( matrix ) {

	position.x = Math.random() * 40 - 20;
	position.y = Math.random() * 40 - 20;
	position.z = Math.random() * 40 - 20;

	rotation.x = Math.random() * 2 * Math.PI;
	rotation.y = Math.random() * 2 * Math.PI;
	rotation.z = Math.random() * 2 * Math.PI;

	quaternion.setFromEuler( rotation );

	scale.x = scale.y = scale.z = 0.5 + ( Math.random() * 0.5 );

	return matrix.compose( position, quaternion, scale );

}

function randomizeRotationSpeed( rotation ) {

	rotation.x = Math.random() * 0.01;
	rotation.y = Math.random() * 0.01;
	rotation.z = Math.random() * 0.01;
	return rotation;

}

function randomizeColor( color ) {

	return color.setHSL( Math.random() * 0.5, 0.6, 0.5 );

}

function randomizeAlpha() {

	// make ~20% of all objects transparent
	return Math.random() > 0.8 ? 0.5 : 1.0;

}

function initGeometries() {

	const cone = new THREE.ConeGeometry( 1.0, 2.0 );
	const box = new THREE.BoxGeometry( 2.0, 2.0, 2.0 );
	const sphere = new THREE.SphereGeometry( 1.0, 16, 8 );

	geometries = [ cone, box, sphere ];

	for ( const geometry of geometries ) {

		// add vertex colors for testing
		const count = geometry.getAttribute( 'position' ).count;
		const attribute = new THREE.BufferAttribute( new Float32Array( count * 3 ), 3 );
		geometry.setAttribute( 'color', attribute );

		for ( let i = 0, l = attribute.array.length; i < l; ++ i ) {

			attribute.array[ i ] = 1.0;

		}

	}

}

function createMaterial() {

	return new THREE.MeshPhongMaterial( {
		vertexColors: true,
		transparent: api.transparent,
		depthWrite: ! api.transparent
	} );

}

function cleanup() {

	if ( mesh ) {

		mesh.traverse( node => {

			if ( node instanceof THREE.Mesh ) {

				node.material.dispose();

			}

		} );

		mesh.parent.remove( mesh );

		if ( mesh.dispose ) {

			mesh.dispose();

		}

	}

}

function initMesh() {

	cleanup();

	if ( api.method === Method.BATCHED ) {

		initBatchedMesh();

	} else {

		initRegularMesh();

	}

}

function initRegularMesh() {

	mesh = new THREE.Group();

	for ( let i = 0; i < api.count; i ++ ) {

		const material = createMaterial();
		randomizeColor( material.color );
		material.opacity = randomizeAlpha();

		const child = new THREE.Mesh( geometries[ i % geometries.length ], material );
		randomizeMatrix( child.matrix );
		child.matrix.decompose( child.position, child.quaternion, child.scale );
		child.userData.rotationSpeed = randomizeRotationSpeed( new THREE.Euler() );
		mesh.add( child );

	}

	scene.add( mesh );

}

function initBatchedMesh() {

	const geometryCount = api.count;
	const vertexCount = geometries.length * 512;
	const indexCount = geometries.length * 1024;

	const euler = new THREE.Euler();
	const matrix = new THREE.Matrix4();
	const color = new THREE.Color();
	const colorWithAlpha = new THREE.Vector4();
	mesh = new THREE.BatchedMesh( geometryCount, vertexCount, indexCount, createMaterial() );
	mesh.userData.rotationSpeeds = [];

	// disable full-object frustum culling since all of the objects can be dynamic.
	mesh.frustumCulled = false;

	ids.length = 0;

	const geometryIds = [
		mesh.addGeometry( geometries[ 0 ] ),
		mesh.addGeometry( geometries[ 1 ] ),
		mesh.addGeometry( geometries[ 2 ] ),
	];

	for ( let i = 0; i < api.count; i ++ ) {

		randomizeColor( color );
		colorWithAlpha.set( color.r, color.g, color.b, randomizeAlpha() );

		const id = mesh.addInstance( geometryIds[ i % geometryIds.length ] );
		mesh.setMatrixAt( id, randomizeMatrix( matrix ) );
		mesh.setColorAt( id, colorWithAlpha );

		const rotationMatrix = new THREE.Matrix4();
		rotationMatrix.makeRotationFromEuler( randomizeRotationSpeed( euler ) );
		mesh.userData.rotationSpeeds.push( rotationMatrix );

		ids.push( id );

	}

	scene.add( mesh );

}

function init() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	// camera

	camera = new THREE.PerspectiveCamera( 70, width / height, 1, 100 );
	camera.position.z = 30;

	// renderer

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( width, height );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	// scene

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xffffff );

	// controls

	controls = new OrbitControls( camera, renderer.domElement );
	controls.autoRotate = true;
	controls.autoRotateSpeed = 1.0;

	// light

	const ambientLight = new THREE.AmbientLight( 0xffffff, 2 );
	const directionalLight = new THREE.DirectionalLight( 0xffffff, 2 );
	directionalLight.position.set( 1, 1, 1 );
	scene.add( directionalLight, ambientLight );

	// stats

	stats = new Stats();
	document.body.appendChild( stats.dom );

	// gui

	gui = new GUI();
	gui.add( api, 'count', 1, MAX_GEOMETRY_COUNT ).step( 1 ).onChange( initMesh );
	gui.add( api, 'dynamic', 0, MAX_GEOMETRY_COUNT ).step( 1 );
	gui.add( api, 'method', Method ).onChange( initMesh );

	gui.add( api, 'transparent' ).onChange( v => mesh.traverse( node => {

		if ( node instanceof THREE.Mesh ) {

			const material = node.material;
			material.transparent = v;
			material.depthWrite = ! v;
			material.needsUpdate = true;

		}

	} ) );

	gui.add( api, 'sortObjects' );
	gui.add( api, 'perObjectFrustumCulled' );
	gui.add( api, 'useCustomSort' );

	guiStatsEl = document.createElement( 'li' );
	guiStatsEl.classList.add( 'gui-stats' );

	// listeners

	window.addEventListener( 'resize', onWindowResize );

}

//

function sortFunction( list ) {

	// initialize options
	this._options = this._options || {
		get: el => el.z,
		aux: new Array( this.maxInstanceCount )
	};

	const options = this._options;
	options.reversed = this.material.transparent;

	let minZ = Infinity;
	let maxZ = - Infinity;
	for ( let i = 0, l = list.length; i < l; i ++ ) {

		const z = list[ i ].z;
		if ( z > maxZ ) maxZ = z;
		if ( z < minZ ) minZ = z;

	}

	// convert depth to unsigned 32 bit range
	const depthDelta = maxZ - minZ;
	const factor = ( 2 ** 32 - 1 ) / depthDelta; // UINT32_MAX / z range
	for ( let i = 0, l = list.length; i < l; i ++ ) {

		list[ i ].z -= minZ;
		list[ i ].z *= factor;

	}

	// perform a fast-sort using the hybrid radix sort function
	radixSort( list, options );

}

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

function animate() {

	animateMeshes();

	controls.update();
	stats.update();

	render();

}

function animateMeshes() {

	const loopNum = Math.min( api.count, api.dynamic );

	if ( api.method === Method.BATCHED ) {

		for ( let i = 0; i < loopNum; i ++ ) {

			const rotationMatrix = mesh.userData.rotationSpeeds[ i ];
			const id = ids[ i ];

			mesh.getMatrixAt( id, matrix );
			matrix.multiply( rotationMatrix );
			mesh.setMatrixAt( id, matrix );

		}

	} else {

		for ( let i = 0; i < loopNum; i ++ ) {

			const child = mesh.children[ i ];
			const rotationSpeed = child.userData.rotationSpeed;

			child.rotation.set(
				child.rotation.x + rotationSpeed.x,
				child.rotation.y + rotationSpeed.y,
				child.rotation.z + rotationSpeed.z
			);

		}

	}

}

function render() {

	if ( mesh.isBatchedMesh ) {

		mesh.sortObjects = api.sortObjects;
		mesh.perObjectFrustumCulled = api.perObjectFrustumCulled;
		mesh.setCustomSort( api.useCustomSort ? sortFunction : null );

	}

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { Reflector } from 'three/addons/objects/Reflector.js';

let camera, scene, renderer;

let cameraControls;

let sphereGroup, smallSphere;

let groundMirror, verticalMirror;

let resolutionScale = 1; // render target scale factor in [ 0, 1 ]

const size = new THREE.Vector2();

init();

function init() {

	const container = document.getElementById( 'container' );

	// renderer
	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	container.appendChild( renderer.domElement );

	// scene
	scene = new THREE.Scene();

	// camera
	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 500 );
	camera.position.set( 0, 75, 160 );

	cameraControls = new OrbitControls( camera, renderer.domElement );
	cameraControls.target.set( 0, 40, 0 );
	cameraControls.maxDistance = 400;
	cameraControls.minDistance = 10;
	cameraControls.update();

	//

	const planeGeo = new THREE.PlaneGeometry( 100.1, 100.1 );

	// reflectors/mirrors

	let geometry, material;

	renderer.getDrawingBufferSize( size );
	size.multiplyScalar( resolutionScale ).round();

	geometry = new THREE.CircleGeometry( 40, 64 );
	groundMirror = new Reflector( geometry, {
		clipBias: 0.003,
		textureWidth: size.width,
		textureHeight: size.height,
		color: 0xb5b5b5
	} );
	groundMirror.position.y = 0.5;
	groundMirror.rotateX( - Math.PI / 2 );
	scene.add( groundMirror );

	geometry = new THREE.PlaneGeometry( 100, 100 );
	verticalMirror = new Reflector( geometry, {
		clipBias: 0.003,
		textureWidth: size.width,
		textureHeight: size.height,
		color: 0xc1cbcb
	} );
	verticalMirror.position.y = 50;
	verticalMirror.position.z = - 50;
	scene.add( verticalMirror );


	sphereGroup = new THREE.Object3D();
	scene.add( sphereGroup );

	geometry = new THREE.CylinderGeometry( 0.1, 15 * Math.cos( Math.PI / 180 * 30 ), 0.1, 24, 1 );
	material = new THREE.MeshPhongMaterial( { color: 0xffffff, emissive: 0x8d8d8d } );
	const sphereCap = new THREE.Mesh( geometry, material );
	sphereCap.position.y = - 15 * Math.sin( Math.PI / 180 * 30 ) - 0.05;
	sphereCap.rotateX( - Math.PI );

	geometry = new THREE.SphereGeometry( 15, 24, 24, Math.PI / 2, Math.PI * 2, 0, Math.PI / 180 * 120 );
	const halfSphere = new THREE.Mesh( geometry, material );
	halfSphere.add( sphereCap );
	halfSphere.rotateX( - Math.PI / 180 * 135 );
	halfSphere.rotateZ( - Math.PI / 180 * 20 );
	halfSphere.position.y = 7.5 + 15 * Math.sin( Math.PI / 180 * 30 );

	sphereGroup.add( halfSphere );

	geometry = new THREE.IcosahedronGeometry( 5, 0 );
	material = new THREE.MeshPhongMaterial( { color: 0xffffff, emissive: 0x7b7b7b, flatShading: true } );
	smallSphere = new THREE.Mesh( geometry, material );
	scene.add( smallSphere );

	// walls
	const planeTop = new THREE.Mesh( planeGeo, new THREE.MeshPhongMaterial( { color: 0xffffff } ) );
	planeTop.position.y = 100;
	planeTop.rotateX( Math.PI / 2 );
	scene.add( planeTop );

	const planeBottom = new THREE.Mesh( planeGeo, new THREE.MeshPhongMaterial( { color: 0xffffff } ) );
	planeBottom.rotateX( - Math.PI / 2 );
	scene.add( planeBottom );

	const planeFront = new THREE.Mesh( planeGeo, new THREE.MeshPhongMaterial( { color: 0x7f7fff } ) );
	planeFront.position.z = 50;
	planeFront.position.y = 50;
	planeFront.rotateY( Math.PI );
	scene.add( planeFront );

	const planeRight = new THREE.Mesh( planeGeo, new THREE.MeshPhongMaterial( { color: 0x00ff00 } ) );
	planeRight.position.x = 50;
	planeRight.position.y = 50;
	planeRight.rotateY( - Math.PI / 2 );
	scene.add( planeRight );

	const planeLeft = new THREE.Mesh( planeGeo, new THREE.MeshPhongMaterial( { color: 0xff0000 } ) );
	planeLeft.position.x = - 50;
	planeLeft.position.y = 50;
	planeLeft.rotateY( Math.PI / 2 );
	scene.add( planeLeft );

	// lights
	const mainLight = new THREE.PointLight( 0xe7e7e7, 2.5, 250, 0 );
	mainLight.position.y = 60;
	scene.add( mainLight );

	const greenLight = new THREE.PointLight( 0x00ff00, 0.5, 1000, 0 );
	greenLight.position.set( 550, 50, 0 );
	scene.add( greenLight );

	const redLight = new THREE.PointLight( 0xff0000, 0.5, 1000, 0 );
	redLight.position.set( - 550, 50, 0 );
	scene.add( redLight );

	const blueLight = new THREE.PointLight( 0xbbbbfe, 0.5, 1000, 0 );
	blueLight.position.set( 0, 50, 550 );
	scene.add( blueLight );

	// GUI

	const params = {
		resolution: resolutionScale,
	};

	const gui = new GUI();

	const folder = gui.addFolder( 'Mirrors' );

	folder.add( params, 'resolution', 0.2, 1, 0.1 )
		.onChange( function ( val ) {

			resolutionScale = val;
			onWindowResize();

		} );

	folder.open();

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	renderer.getDrawingBufferSize( size );
	size.multiplyScalar( resolutionScale ).round();

	groundMirror.getRenderTarget().setSize( size.width, size.height );
	verticalMirror.getRenderTarget().setSize( size.width, size.height );

}

function animate() {

	const timer = Date.now() * 0.01;

	sphereGroup.rotation.y -= 0.002;

	smallSphere.position.set(
		Math.cos( timer * 0.1 ) * 30,
		Math.abs( Math.cos( timer * 0.2 ) ) * 20 + 5,
		Math.sin( timer * 0.1 ) * 30
	);
	smallSphere.rotation.y = ( Math.PI / 2 ) - timer * 0.1;
	smallSphere.rotation.z = timer * 0.8;

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import { TransformControls } from 'three/addons/controls/TransformControls.js';
import Stats from 'three/addons/libs/stats.module.js';
import { Flow } from 'three/addons/modifiers/CurveModifier.js';
import { FontLoader } from 'three/addons/loaders/FontLoader.js';
import { TextGeometry } from 'three/addons/geometries/TextGeometry.js';

const ACTION_SELECT = 1, ACTION_NONE = 0;
const curveHandles = [];
const mouse = new THREE.Vector2();

let stats;
let scene,
	camera,
	renderer,
	rayCaster,
	control,
	flow,
	action = ACTION_NONE;

init();

function init() {

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera(
		40,
		window.innerWidth / window.innerHeight,
		1,
		1000
	);
	camera.position.set( 2, 2, 4 );
	camera.lookAt( scene.position );

	const initialPoints = [
		{ x: 1, y: 0, z: - 1 },
		{ x: 1, y: 0, z: 1 },
		{ x: - 1, y: 0, z: 1 },
		{ x: - 1, y: 0, z: - 1 },
	];

	const boxGeometry = new THREE.BoxGeometry( 0.1, 0.1, 0.1 );
	const boxMaterial = new THREE.MeshBasicMaterial();

	for ( const handlePos of initialPoints ) {

		const handle = new THREE.Mesh( boxGeometry, boxMaterial );
		handle.position.copy( handlePos );
		curveHandles.push( handle );
		scene.add( handle );

	}

	const curve = new THREE.CatmullRomCurve3(
		curveHandles.map( ( handle ) => handle.position )
	);
	curve.curveType = 'centripetal';
	curve.closed = true;

	const points = curve.getPoints( 50 );
	const line = new THREE.LineLoop(
		new THREE.BufferGeometry().setFromPoints( points ),
		new THREE.LineBasicMaterial( { color: 0x00ff00 } )
	);

	scene.add( line );

	//

	const light = new THREE.DirectionalLight( 0xffaa33, 3 );
	light.position.set( - 10, 10, 10 );
	scene.add( light );

	const light2 = new THREE.AmbientLight( 0x003973, 3 );
	scene.add( light2 );

	//

	const loader = new FontLoader();
	loader.load( 'fonts/helvetiker_regular.typeface.json', function ( font ) {

		const geometry = new TextGeometry( 'Hello three.js!', {
			font: font,
			size: 0.2,
			depth: 0.05,
			curveSegments: 12,
			bevelEnabled: true,
			bevelThickness: 0.02,
			bevelSize: 0.01,
			bevelOffset: 0,
			bevelSegments: 5,
		} );

		geometry.rotateX( Math.PI );

		const material = new THREE.MeshStandardMaterial( {
			color: 0x99ffff
		} );

		const objectToCurve = new THREE.Mesh( geometry, material );

		flow = new Flow( objectToCurve );
		flow.updateCurve( 0, curve );
		scene.add( flow.object3D );

	} );

	//

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	renderer.domElement.addEventListener( 'pointerdown', onPointerDown );

	rayCaster = new THREE.Raycaster();
	control = new TransformControls( camera, renderer.domElement );
	control.addEventListener( 'dragging-changed', function ( event ) {

		if ( ! event.value ) {

			const points = curve.getPoints( 50 );
			line.geometry.setFromPoints( points );
			flow.updateCurve( 0, curve );

		}

	} );

	stats = new Stats();
	document.body.appendChild( stats.dom );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function onPointerDown( event ) {

	action = ACTION_SELECT;
	mouse.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	mouse.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

}

function animate() {

	if ( action === ACTION_SELECT ) {

		rayCaster.setFromCamera( mouse, camera );
		action = ACTION_NONE;
		const intersects = rayCaster.intersectObjects( curveHandles, false );
		if ( intersects.length ) {

			const target = intersects[ 0 ].object;
			control.attach( target );
			scene.add( control.getHelper() );

		}

	}

	if ( flow ) {

		flow.moveAlongCurve( 0.001 );

	}

	render();

}

function render() {

	renderer.render( scene, camera );

	stats.update();

}

import * as THREE from 'three';
import { TransformControls } from 'three/addons/controls/TransformControls.js';
import Stats from 'three/addons/libs/stats.module.js';
import { InstancedFlow } from 'three/addons/modifiers/CurveModifier.js';
import { FontLoader } from 'three/addons/loaders/FontLoader.js';
import { TextGeometry } from 'three/addons/geometries/TextGeometry.js';

const ACTION_SELECT = 1, ACTION_NONE = 0;
const curveHandles = [];
const mouse = new THREE.Vector2();

let stats;
let scene,
	camera,
	renderer,
	rayCaster,
	control,
	flow,
	action = ACTION_NONE;

init();

function init() {

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera(
		40,
		window.innerWidth / window.innerHeight,
		1,
		1000
	);
	camera.position.set( 2, 2, 4 );
	camera.lookAt( scene.position );

	const boxGeometry = new THREE.BoxGeometry( 0.1, 0.1, 0.1 );
	const boxMaterial = new THREE.MeshBasicMaterial();

	const curves = [[
		{ x: 1, y: - 0.5, z: - 1 },
		{ x: 1, y: - 0.5, z: 1 },
		{ x: - 1, y: - 0.5, z: 1 },
		{ x: - 1, y: - 0.5, z: - 1 },
	],
	[
		{ x: - 1, y: 0.5, z: - 1 },
		{ x: - 1, y: 0.5, z: 1 },
		{ x: 1, y: 0.5, z: 1 },
		{ x: 1, y: 0.5, z: - 1 },
	]].map( function ( curvePoints ) {

		const curveVertices = curvePoints.map( function ( handlePos ) {

			const handle = new THREE.Mesh( boxGeometry, boxMaterial );
			handle.position.copy( handlePos );
			curveHandles.push( handle );
			scene.add( handle );
			return handle.position;

		} );

		const curve = new THREE.CatmullRomCurve3( curveVertices );
		curve.curveType = 'centripetal';
		curve.closed = true;

		const points = curve.getPoints( 50 );
		const line = new THREE.LineLoop(
			new THREE.BufferGeometry().setFromPoints( points ),
			new THREE.LineBasicMaterial( { color: 0x00ff00 } )
		);

		scene.add( line );

		return {
			curve,
			line
		};

	} );


	//

	const light = new THREE.DirectionalLight( 0xffaa33, 3 );
	light.position.set( - 10, 10, 10 );
	scene.add( light );

	const light2 = new THREE.AmbientLight( 0x003973, 3 );
	scene.add( light2 );

	//

	const loader = new FontLoader();
	loader.load( 'fonts/helvetiker_regular.typeface.json', function ( font ) {

		const geometry = new TextGeometry( 'Hello three.js!', {
			font: font,
			size: 0.2,
			depth: 0.05,
			curveSegments: 12,
			bevelEnabled: true,
			bevelThickness: 0.02,
			bevelSize: 0.01,
			bevelOffset: 0,
			bevelSegments: 5,
		} );

		geometry.rotateX( Math.PI );

		const material = new THREE.MeshStandardMaterial( {
			color: 0x99ffff
		} );

		const numberOfInstances = 8;
		flow = new InstancedFlow( numberOfInstances, curves.length, geometry, material );

		curves.forEach( function ( { curve }, i ) {

			flow.updateCurve( i, curve );
			scene.add( flow.object3D );

		} );

		for ( let i = 0; i < numberOfInstances; i ++ ) {

			const curveIndex = i % curves.length;
			flow.setCurve( i, curveIndex );
			flow.moveIndividualAlongCurve( i, i * 1 / numberOfInstances );
			flow.object3D.setColorAt( i, new THREE.Color( 0xffffff * Math.random() ) );

		}

	} );

	//

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	renderer.domElement.addEventListener( 'pointerdown', onPointerDown );

	rayCaster = new THREE.Raycaster();
	control = new TransformControls( camera, renderer.domElement );
	control.addEventListener( 'dragging-changed', function ( event ) {

		if ( ! event.value ) {

			curves.forEach( function ( { curve, line }, i ) {

				const points = curve.getPoints( 50 );
				line.geometry.setFromPoints( points );
				flow.updateCurve( i, curve );

			} );

