let views, t, canvas, renderer;

window.onload = init;

function init() {

	const balls = 20;
	const size = .25;

	const colors = [
		'rgb(0,127,255)', 'rgb(255,0,0)', 'rgb(0,255,0)', 'rgb(0,255,255)',
		'rgb(255,0,255)', 'rgb(255,0,127)', 'rgb(255,255,0)', 'rgb(0,255,127)'
	];

	canvas = document.getElementById( 'c' );

	renderer = new THREE.WebGLRenderer( { canvas: canvas, antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setAnimationLoop( animate );

	views = document.querySelectorAll( '.view' );

	for ( let n = 0; n < views.length; n ++ ) {

		const scene = new THREE.Scene();
		scene.background = new THREE.Color( 0xffffff );

		const geometry0 = new THREE.BufferGeometry();
		const geometry1 = new THREE.BufferGeometry();

		const vertices = [];

		if ( views[ n ].lattice ) {

			const range = balls / 2;
			for ( let i = - range; i <= range; i ++ ) {

				for ( let j = - range; j <= range; j ++ ) {

					for ( let k = - range; k <= range; k ++ ) {

						vertices.push( i, j, k );

					}

				}

			}

		} else {

			for ( let m = 0; m < Math.pow( balls, 3 ); m ++ ) {

				const i = balls * Math.random() - balls / 2;
				const j = balls * Math.random() - balls / 2;
				const k = balls * Math.random() - balls / 2;

				vertices.push( i, j, k );

			}

		}

		geometry0.setAttribute( 'position', new THREE.Float32BufferAttribute( vertices, 3 ) );
		geometry1.setAttribute( 'position', new THREE.Float32BufferAttribute( vertices.slice(), 3 ) );

		const index = Math.floor( colors.length * Math.random() );

		const canvas2 = document.createElement( 'canvas' );
		canvas2.width = 128;
		canvas2.height = 128;
		const context = canvas2.getContext( '2d' );
		context.arc( 64, 64, 64, 0, 2 * Math.PI );
		context.fillStyle = colors[ index ];
		context.fill();
		const texture = new THREE.CanvasTexture( canvas2 );
		texture.colorSpace = THREE.SRGBColorSpace;

		const material = new THREE.PointsMaterial( { size: size, map: texture, transparent: true, alphaTest: 0.1 } );

		scene.add( new THREE.Points( geometry0, material ) );

		scene.userData.view = views[ n ];
		scene.userData.geometry1 = geometry1;

		const camera = new THREE.PerspectiveCamera( 75, 1, 0.1, 100 );
		camera.position.set( 0, 0, 1.2 * balls );
		scene.userData.camera = camera;

		const controls = new OrbitControls( camera, views[ n ] );
		scene.userData.controls = controls;

		scenes.push( scene );

	}

	t = 0;
	animate();

}

function updateSize() {

	const width = canvas.clientWidth;
	const height = canvas.clientHeight;

	if ( canvas.width !== width || canvas.height != height ) {

		renderer.setSize( width, height, false );

	}

}

function animate() {

	timer.update();

	updateSize();

	renderer.setClearColor( 0xffffff );
	renderer.setScissorTest( false );
	renderer.clear();

	renderer.setClearColor( 0x000000 );
	renderer.setScissorTest( true );

	scenes.forEach( function ( scene ) {

		const rect = scene.userData.view.getBoundingClientRect();

		// check if it's offscreen. If so skip it

		if ( rect.bottom < 0 || rect.top > renderer.domElement.clientHeight ||
			 rect.right < 0 || rect.left > renderer.domElement.clientWidth ) {

			return; // it's off screen

		}

		// set the viewport

		const width = rect.right - rect.left;
		const height = rect.bottom - rect.top;
		const left = rect.left;
		const bottom = renderer.domElement.clientHeight - rect.bottom;

		renderer.setViewport( left, bottom, width, height );
		renderer.setScissor( left, bottom, width, height );

		renderer.render( scene, scene.userData.camera );

		const points = scene.children[ 0 ];
		const position = points.geometry.attributes.position;

		const point = new THREE.Vector3();
		const offset = new THREE.Vector3();

		for ( let i = 0; i < position.count; i ++ ) {

			point.fromBufferAttribute( scene.userData.geometry1.attributes.position, i );

			scene.userData.view.displacement( point.x, point.y, point.z, t / 5, offset );

			position.setXYZ( i, point.x + offset.x, point.y + offset.y, point.z + offset.z );

		}

		position.needsUpdate = true;

	} );

	t += timer.getDelta() * 60;

}

import * as THREE from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let camera, scene, renderer, controls;
let renderTarget;
let postScene, postCamera;

const parameters = {
	samples: 4,
	wireframe: false
};

const gui = new GUI();
gui.add( parameters, 'samples', 0, 4 ).step( 1 );
gui.add( parameters, 'wireframe' );
gui.onChange( render );

init();

function init() {

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	document.body.appendChild( renderer.domElement );

	// Create a multi render target with Float buffers

	renderTarget = new THREE.WebGLRenderTarget(
		window.innerWidth * window.devicePixelRatio,
		window.innerHeight * window.devicePixelRatio,
		{
			count: 2,
			minFilter: THREE.NearestFilter,
			magFilter: THREE.NearestFilter
		}
	);

	// Name our G-Buffer attachments for debugging

	renderTarget.textures[ 0 ].name = 'diffuse';
	renderTarget.textures[ 1 ].name = 'normal';

	// Scene setup

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x222222 );

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 0.1, 50 );
	camera.position.z = 4;

	const loader = new THREE.TextureLoader();

	const diffuse = loader.load( 'textures/hardwood2_diffuse.jpg', render );
	diffuse.wrapS = THREE.RepeatWrapping;
	diffuse.wrapT = THREE.RepeatWrapping;
	diffuse.colorSpace = THREE.SRGBColorSpace;

	scene.add( new THREE.Mesh(
		new THREE.TorusKnotGeometry( 1, 0.3, 128, 32 ),
		new THREE.RawShaderMaterial( {
			name: 'G-Buffer Shader',
			vertexShader: document.querySelector( '#gbuffer-vert' ).textContent.trim(),
			fragmentShader: document.querySelector( '#gbuffer-frag' ).textContent.trim(),
			uniforms: {
				tDiffuse: { value: diffuse },
				repeat: { value: new THREE.Vector2( 5, 0.5 ) }
			},
			glslVersion: THREE.GLSL3
		} )
	) );

	// PostProcessing setup

	postScene = new THREE.Scene();
	postCamera = new THREE.OrthographicCamera( - 1, 1, 1, - 1, 0, 1 );

	postScene.add( new THREE.Mesh(
		new THREE.PlaneGeometry( 2, 2 ),
		new THREE.RawShaderMaterial( {
			name: 'Post-FX Shader',
			vertexShader: document.querySelector( '#render-vert' ).textContent.trim(),
			fragmentShader: document.querySelector( '#render-frag' ).textContent.trim(),
			uniforms: {
				tDiffuse: { value: renderTarget.textures[ 0 ] },
				tNormal: { value: renderTarget.textures[ 1 ] },
			},
			glslVersion: THREE.GLSL3
		} )
	) );

	// Controls

	controls = new OrbitControls( camera, renderer.domElement );
	controls.addEventListener( 'change', render );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	const dpr = renderer.getPixelRatio();
	renderTarget.setSize( window.innerWidth * dpr, window.innerHeight * dpr );

	render();

}

function render() {

	renderTarget.samples = parameters.samples;

	scene.traverse( function ( child ) {

		if ( child.material !== undefined ) {

			child.material.wireframe = parameters.wireframe;

		}

	} );

	// render scene into target
	renderer.setRenderTarget( renderTarget );
	renderer.render( scene, camera );

	// render post FX
	renderer.setRenderTarget( null );
	renderer.render( postScene, postCamera );

}

