let container, stats;
let camera, scene, renderer, materialDepth;

let windowHalfX = window.innerWidth / 2;
let windowHalfY = window.innerHeight / 2;

let distance = 100;
let effectController;

const postprocessing = { enabled: true };

const shaderSettings = {
