	const snappingFolder = gui.addFolder( 'Snapping' ).close();
	snappingControl.onChange( enabled => snappingFolder.controllers.forEach( c => c.enable( enabled ) ) );
	snappingFolder.add( params, 'pixelAlignedPanning' );
