		geometry.computeVertexNormals();

		const material = new THREE.MeshStandardMaterial( { color: 0xa5a5a5 } );
		const mesh = new THREE.Mesh( geometry, material );
		mesh.position.y = - 0.0365;
		scene.add( mesh );
