init();

function generateCloudTexture( size, scaleFactor = 1.0 ) {

	const data = new Uint8Array( size * size * size );
	const scale = scaleFactor * 10.0 / size;

	let i = 0;
	const perlin = new ImprovedNoise();
	const vector = new THREE.Vector3();

	for ( let z = 0; z < size; z ++ ) {

		for ( let y = 0; y < size; y ++ ) {

			for ( let x = 0; x < size; x ++ ) {

				const dist = vector.set( x, y, z ).subScalar( size / 2 ).divideScalar( size ).length();
				const fadingFactor = ( 1.0 - dist ) * ( 1.0 - dist );
				data[ i ] = ( 128 + 128 * perlin.noise( x * scale / 1.5, y * scale, z * scale / 1.5 ) ) * fadingFactor;

				i ++;

			}

		}

	}

	return new THREE.Data3DTexture( data, size, size, size );

}

function init() {

	renderer = new THREE.WebGLRenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 0, 0, 1.5 );

	new OrbitControls( camera, renderer.domElement );

	// Sky

	const canvas = document.createElement( 'canvas' );
	canvas.width = 1;
	canvas.height = 32;

	const context = canvas.getContext( '2d' );
	const gradient = context.createLinearGradient( 0, 0, 0, 32 );
	gradient.addColorStop( 0.0, '#014a84' );
	gradient.addColorStop( 0.5, '#0561a0' );
	gradient.addColorStop( 1.0, '#437ab6' );
	context.fillStyle = gradient;
	context.fillRect( 0, 0, 1, 32 );

	const skyMap = new THREE.CanvasTexture( canvas );
	skyMap.colorSpace = THREE.SRGBColorSpace;

	const sky = new THREE.Mesh(
		new THREE.SphereGeometry( 10 ),
		new THREE.MeshBasicMaterial( { map: skyMap, side: THREE.BackSide } )
	);
	scene.add( sky );

	// Texture

	const texture = new THREE.Data3DTexture(
		new Uint8Array( INITIAL_CLOUD_SIZE * INITIAL_CLOUD_SIZE * INITIAL_CLOUD_SIZE ).fill( 0 ),
		INITIAL_CLOUD_SIZE,
		INITIAL_CLOUD_SIZE,
		INITIAL_CLOUD_SIZE
	);
	texture.format = THREE.RedFormat;
	texture.minFilter = THREE.LinearFilter;
	texture.magFilter = THREE.LinearFilter;
	texture.unpackAlignment = 1;
	texture.needsUpdate = true;

	cloudTexture = texture;

	// Material

	const vertexShader = /* glsl */`
		in vec3 position;

		uniform mat4 modelMatrix;
		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;
		uniform vec3 cameraPos;

		out vec3 vOrigin;
		out vec3 vDirection;

		void main() {
			vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );

			vOrigin = vec3( inverse( modelMatrix ) * vec4( cameraPos, 1.0 ) ).xyz;
			vDirection = position - vOrigin;

			gl_Position = projectionMatrix * mvPosition;
		}
	`;

	const fragmentShader = /* glsl */`
		precision highp float;
		precision highp sampler3D;

		uniform mat4 modelViewMatrix;
		uniform mat4 projectionMatrix;

		in vec3 vOrigin;
		in vec3 vDirection;

		out vec4 color;

		uniform vec3 base;
		uniform sampler3D map;

		uniform float threshold;
		uniform float range;
		uniform float opacity;
		uniform float steps;
		uniform float frame;

		uint wang_hash(uint seed)
		{
				seed = (seed ^ 61u) ^ (seed >> 16u);
				seed *= 9u;
				seed = seed ^ (seed >> 4u);
				seed *= 0x27d4eb2du;
				seed = seed ^ (seed >> 15u);
				return seed;
		}

		float randomFloat(inout uint seed)
		{
				return float(wang_hash(seed)) / 4294967296.;
		}

		vec2 hitBox( vec3 orig, vec3 dir ) {
			const vec3 box_min = vec3( - 0.5 );
			const vec3 box_max = vec3( 0.5 );
			vec3 inv_dir = 1.0 / dir;
			vec3 tmin_tmp = ( box_min - orig ) * inv_dir;
			vec3 tmax_tmp = ( box_max - orig ) * inv_dir;
			vec3 tmin = min( tmin_tmp, tmax_tmp );
			vec3 tmax = max( tmin_tmp, tmax_tmp );
			float t0 = max( tmin.x, max( tmin.y, tmin.z ) );
			float t1 = min( tmax.x, min( tmax.y, tmax.z ) );
			return vec2( t0, t1 );
		}

		float sample1( vec3 p ) {
			return texture( map, p ).r;
		}

		float shading( vec3 coord ) {
			float step = 0.01;
			return sample1( coord + vec3( - step ) ) - sample1( coord + vec3( step ) );
		}

		vec4 linearToSRGB( in vec4 value ) {
			return vec4( mix( pow( value.rgb, vec3( 0.41666 ) ) * 1.055 - vec3( 0.055 ), value.rgb * 12.92, vec3( lessThanEqual( value.rgb, vec3( 0.0031308 ) ) ) ), value.a );
		}

		void main(){
			vec3 rayDir = normalize( vDirection );
			vec2 bounds = hitBox( vOrigin, rayDir );

			if ( bounds.x > bounds.y ) discard;

			bounds.x = max( bounds.x, 0.0 );

			vec3 p = vOrigin + bounds.x * rayDir;
			vec3 inc = 1.0 / abs( rayDir );
			float delta = min( inc.x, min( inc.y, inc.z ) );
			delta /= steps;

			// Jitter

			// Nice little seed from
			// https://blog.demofox.org/2020/05/25/casual-shadertoy-path-tracing-1-basic-camera-diffuse-emissive/
			uint seed = uint( gl_FragCoord.x ) * uint( 1973 ) + uint( gl_FragCoord.y ) * uint( 9277 ) + uint( frame ) * uint( 26699 );
			vec3 size = vec3( textureSize( map, 0 ) );
			float randNum = randomFloat( seed ) * 2.0 - 1.0;
			p += rayDir * randNum * ( 1.0 / size );

			//

			vec4 ac = vec4( base, 0.0 );

			for ( float t = bounds.x; t < bounds.y; t += delta ) {

				float d = sample1( p + 0.5 );

				d = smoothstep( threshold - range, threshold + range, d ) * opacity;

				float col = shading( p + 0.5 ) * 3.0 + ( ( p.x + p.y ) * 0.25 ) + 0.2;

				ac.rgb += ( 1.0 - ac.a ) * d * col;

				ac.a += ( 1.0 - ac.a ) * d;

				if ( ac.a >= 0.95 ) break;

				p += rayDir * delta;

			}

			color = linearToSRGB( ac );

			if ( color.a == 0.0 ) discard;

		}
	`;

	const geometry = new THREE.BoxGeometry( 1, 1, 1 );
	const material = new THREE.RawShaderMaterial( {
		glslVersion: THREE.GLSL3,
		uniforms: {
			base: { value: new THREE.Color( 0x798aa0 ) },
			map: { value: texture },
			cameraPos: { value: new THREE.Vector3() },
			threshold: { value: 0.25 },
			opacity: { value: 0.25 },
			range: { value: 0.1 },
			steps: { value: 100 },
			frame: { value: 0 }
		},
		vertexShader,
		fragmentShader,
		side: THREE.BackSide,
		transparent: true
	} );

	mesh = new THREE.Mesh( geometry, material );
	scene.add( mesh );

	//

	const parameters = {
		threshold: 0.25,
		opacity: 0.25,
		range: 0.1,
		steps: 100
	};

	function update() {

		material.uniforms.threshold.value = parameters.threshold;
		material.uniforms.opacity.value = parameters.opacity;
		material.uniforms.range.value = parameters.range;
		material.uniforms.steps.value = parameters.steps;

	}

	const gui = new GUI();
	gui.add( parameters, 'threshold', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'opacity', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'range', 0, 1, 0.01 ).onChange( update );
	gui.add( parameters, 'steps', 0, 200, 1 ).onChange( update );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

let curr = 0;
const countPerRow = 4;
const countPerSlice = countPerRow * countPerRow;
const sliceCount = 4;
const totalCount = sliceCount * countPerSlice;
const margins = 8;

const perElementPaddedSize = ( INITIAL_CLOUD_SIZE - margins ) / countPerRow;
const perElementSize = Math.floor( ( INITIAL_CLOUD_SIZE - 1 ) / countPerRow );

function animate() {

	const time = performance.now();
	if ( time - prevTime > 1500.0 && curr < totalCount ) {

		const position = new THREE.Vector3(
			Math.floor( curr % countPerRow ) * perElementSize + margins * 0.5,
			( Math.floor( ( ( curr % countPerSlice ) / countPerRow ) ) ) * perElementSize + margins * 0.5,
			Math.floor( curr / countPerSlice ) * perElementSize + margins * 0.5
		).floor();

		const maxDimension = perElementPaddedSize - 1;
		const box = new THREE.Box3( new THREE.Vector3( 0, 0, 0 ), new THREE.Vector3( maxDimension, maxDimension, maxDimension ) );
		const scaleFactor = ( Math.random() + 0.5 ) * 0.5;
		const source = generateCloudTexture( perElementPaddedSize, scaleFactor );

		renderer.copyTextureToTexture( source, cloudTexture, box, position );

		prevTime = time;

		curr ++;

	}

	mesh.material.uniforms.cameraPos.value.copy( camera.position );
	// mesh.rotation.y = - performance.now() / 7500;

	mesh.material.uniforms.frame.value ++;

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';
import { HDRLoader } from 'three/addons/loaders/HDRLoader.js';

let renderer, scene, camera, controls;
let gui, guiExposure = null;

const params = {
	exposure: 1.0,
	toneMapping: 'Neutral',
	blurriness: 0.3,
	intensity: 1.0,
};

const toneMappingOptions = {
	None: THREE.NoToneMapping,
	Linear: THREE.LinearToneMapping,
	Reinhard: THREE.ReinhardToneMapping,
	Cineon: THREE.CineonToneMapping,
	ACESFilmic: THREE.ACESFilmicToneMapping,
	AgX: THREE.AgXToneMapping,
	Neutral: THREE.NeutralToneMapping,
	Custom: THREE.CustomToneMapping
};

init().catch( function ( err ) {

	console.error( err );

} );

async function init() {

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	renderer.toneMapping = toneMappingOptions[ params.toneMapping ];
	renderer.toneMappingExposure = params.exposure;

	// Set CustomToneMapping to Uncharted2
	// source: http://filmicworlds.com/blog/filmic-tonemapping-operators/

	THREE.ShaderChunk.tonemapping_pars_fragment = THREE.ShaderChunk.tonemapping_pars_fragment.replace(

		'vec3 CustomToneMapping( vec3 color ) { return color; }',

		`#define Uncharted2Helper( x ) max( ( ( x * ( 0.15 * x + 0.10 * 0.50 ) + 0.20 * 0.02 ) / ( x * ( 0.15 * x + 0.50 ) + 0.20 * 0.30 ) ) - 0.02 / 0.30, vec3( 0.0 ) )

		float toneMappingWhitePoint = 1.0;

		vec3 CustomToneMapping( vec3 color ) {
			color *= toneMappingExposure;
			return saturate( Uncharted2Helper( color ) / Uncharted2Helper( vec3( toneMappingWhitePoint ) ) );

		}`

	);

	scene = new THREE.Scene();
	scene.backgroundBlurriness = params.blurriness;

	const light = new THREE.DirectionalLight( 0xfff3ee, 3 ); // simulate sun
	light.position.set( 1, 0.05, 0.7 );
	scene.add( light );

	// scene.add( new THREE.DirectionalLightHelper( light, 1, 0x000000 ) );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.01, 10 );
	camera.position.set( - 0.02, 0.03, 0.05 );

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enablePan = false;
	controls.enableDamping = true;
	controls.minDistance = 0.03;
	controls.maxDistance = 0.2;
	controls.target.set( 0, 0.03, 0 );
	controls.update();

	const hdrLoader = new HDRLoader()
		.setPath( 'textures/equirectangular/' );

	const dracoLoader = new DRACOLoader();
	const gltfLoader = new GLTFLoader();
	gltfLoader.setDRACOLoader( dracoLoader );
	gltfLoader.setPath( 'models/gltf/' );

	const [ texture, gltf ] = await Promise.all( [
		hdrLoader.loadAsync( 'venice_sunset_1k.hdr' ),
		gltfLoader.loadAsync( 'venice_mask.glb' ),
	] );

	// environment

	texture.mapping = THREE.EquirectangularReflectionMapping;

	scene.background = texture;
	scene.environment = texture;

	// model

	scene.add( gltf.scene );

	window.addEventListener( 'resize', onWindowResize );

	//

	gui = new GUI();
	const toneMappingFolder = gui.addFolder( 'Tone Mapping' );

	toneMappingFolder.add( params, 'toneMapping', Object.keys( toneMappingOptions ) )

		.name( 'type' )
		.onChange( function () {

			updateGUI();

			renderer.toneMapping = toneMappingOptions[ params.toneMapping ];

		} );

	guiExposure = toneMappingFolder.add( params, 'exposure', 0, 2 )

		.onChange( function ( value ) {

			renderer.toneMappingExposure = value;

		} );

	const backgroundFolder = gui.addFolder( 'Background' );

	backgroundFolder.add( params, 'blurriness', 0, 1 )

		.onChange( function ( value ) {

			scene.backgroundBlurriness = value;

		} );

	backgroundFolder.add( params, 'intensity', 0, 1 )

		.onChange( function ( value ) {

			scene.backgroundIntensity = value;

		} );

	updateGUI();

	gui.open();

}

function updateGUI() {

	if ( params.toneMapping === 'None' ) {

		guiExposure.hide();

	} else {

		guiExposure.show();

	}

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;

	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	controls.update();

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';
import { WebGLNodesHandler } from 'three/addons/tsl/WebGLNodesHandler.js';
import { WebGLRenderer } from 'three';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { HDRCubeTextureLoader } from 'three/addons/loaders/HDRCubeTextureLoader.js';

import { FlakesTexture } from 'three/addons/textures/FlakesTexture.js';

let camera, scene, renderer;

let particleLight;
let group;

init();

function init() {

	camera = new THREE.PerspectiveCamera( 27, window.innerWidth / window.innerHeight, 0.25, 50 );
	camera.position.z = 10;

	scene = new THREE.Scene();

	group = new THREE.Group();

	new HDRCubeTextureLoader()
		.setPath( 'textures/cube/pisaHDR/' )
		.load( [ 'px.hdr', 'nx.hdr', 'py.hdr', 'ny.hdr', 'pz.hdr', 'nz.hdr' ],
			async function ( texture ) {

				const geometry = new THREE.SphereGeometry( .8, 64, 32 );

				const textureLoader = new THREE.TextureLoader();

				const diffuse = textureLoader.load( 'textures/carbon/Carbon.png' );
				diffuse.colorSpace = THREE.SRGBColorSpace;
				diffuse.wrapS = THREE.RepeatWrapping;
				diffuse.wrapT = THREE.RepeatWrapping;
				diffuse.repeat.x = 10;
				diffuse.repeat.y = 10;

				const normalMap = textureLoader.load( 'textures/carbon/Carbon_Normal.png' );
				normalMap.wrapS = THREE.RepeatWrapping;
				normalMap.wrapT = THREE.RepeatWrapping;
				normalMap.repeat.x = 10;
				normalMap.repeat.y = 10;

				const normalMap2 = textureLoader.load( 'textures/water/Water_1_M_Normal.jpg' );

				const normalMap3 = new THREE.CanvasTexture( new FlakesTexture() );
				normalMap3.wrapS = THREE.RepeatWrapping;
				normalMap3.wrapT = THREE.RepeatWrapping;
				normalMap3.repeat.x = 10;
				normalMap3.repeat.y = 6;
				normalMap3.anisotropy = 16;

				const normalMap4 = textureLoader.load( 'textures/golfball.jpg' );

				const clearcoatNormalMap = textureLoader.load( 'textures/pbr/Scratched_gold/Scratched_gold_01_1K_Normal.png' );

				// car paint

				let material = new THREE.MeshPhysicalNodeMaterial( {
					clearcoat: 1.0,
					clearcoatRoughness: 0.1,
					metalness: 0.9,
					roughness: 0.5,
					color: 0x0000ff,
					normalMap: normalMap3,
					normalScale: new THREE.Vector2( 0.15, 0.15 )
				} );
				let mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = - 1;
				mesh.position.y = 1;
				mesh.castShadow = true;
				mesh.receiveShadow = true;
				group.add( mesh );

				// fibers

				material = new THREE.MeshPhysicalNodeMaterial( {
					roughness: 0.5,
					clearcoat: 1.0,
					clearcoatRoughness: 0.1,
					map: diffuse,
					normalMap: normalMap
				} );
				mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = 1;
				mesh.position.y = 1;
				mesh.castShadow = true;
				mesh.receiveShadow = true;
				group.add( mesh );

				// golf

				material = new THREE.MeshPhysicalNodeMaterial( {
					metalness: 0.0,
					roughness: 0.1,
					clearcoat: 1.0,
					normalMap: normalMap4,
					clearcoatNormalMap: clearcoatNormalMap,

					// y scale is negated to compensate for normal map handedness.
					clearcoatNormalScale: new THREE.Vector2( 2.0, - 2.0 )
				} );
				mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = - 1;
				mesh.position.y = - 1;
				mesh.castShadow = true;
				mesh.receiveShadow = true;
				group.add( mesh );

				// clearcoat + normalmap

				material = new THREE.MeshPhysicalNodeMaterial( {
					clearcoat: 1.0,
					metalness: 1.0,
					color: 0xff0000,
					normalMap: normalMap2,
					normalScale: new THREE.Vector2( 0.15, 0.15 ),
					clearcoatNormalMap: clearcoatNormalMap,

					// y scale is negated to compensate for normal map handedness.
					clearcoatNormalScale: new THREE.Vector2( 2.0, - 2.0 )
				} );
				mesh = new THREE.Mesh( geometry, material );
				mesh.position.x = 1;
				mesh.position.y = - 1;
				mesh.castShadow = true;
				mesh.receiveShadow = true;
				group.add( mesh );

				//

				scene.background = texture;
				scene.environment = texture;

				// wait until the models can be added to the scene without blocking due to shader compilation

				await renderer.compileAsync( group, camera, scene );

				scene.add( group );

			}

		);

	// LIGHTS

	particleLight = new THREE.Mesh(
		new THREE.SphereGeometry( .05, 8, 8 ),
		new THREE.MeshBasicNodeMaterial( { color: 0xffffff } )
	);
	scene.add( particleLight );

	const pointLight = new THREE.PointLight( 0xffffff, 30 );
	pointLight.castShadow = true;
	particleLight.add( pointLight );

	renderer = new WebGLRenderer( { antialias: true } );
	renderer.setNodesHandler( new WebGLNodesHandler() );
	renderer.shadowMap.enabled = true;
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	//

	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 1.25;

	// EVENTS

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 3;
	controls.maxDistance = 30;

	window.addEventListener( 'resize', onWindowResize );

}

//

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

//

function animate() {

	render();

}

function render() {

	const timer = Date.now() * 0.00025;

	particleLight.position.x = Math.sin( timer * 7 ) * 3;
	particleLight.position.y = Math.cos( timer * 5 ) * 4;
	particleLight.position.z = Math.cos( timer * 3 ) * 3;

	for ( let i = 0; i < group.children.length; i ++ ) {

		const child = group.children[ i ];
		child.rotation.y += 0.005;

	}

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import { WebGLNodesHandler } from 'three/addons/tsl/WebGLNodesHandler.js';

import Stats from 'three/addons/libs/stats.module.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { MeshPhongNodeMaterial } from 'three/webgpu';
import { sin, time, vec3, positionWorld } from 'three/tsl';

let container, stats, gui, guiStatsEl;
let camera, controls, scene, renderer, material;

// gui

const Method = {
	INSTANCED: 'INSTANCED',
	MERGED: 'MERGED',
	NAIVE: 'NAIVE'
};

const api = {
	method: Method.INSTANCED,
	count: 1000
};

//

init();
initMesh();

//

function clean() {

	const meshes = [];

	scene.traverse( function ( object ) {

		if ( object.isMesh ) meshes.push( object );

	} );

	for ( let i = 0; i < meshes.length; i ++ ) {

		const mesh = meshes[ i ];
		mesh.material.dispose();
		mesh.geometry.dispose();

		scene.remove( mesh );

	}

}

const randomizeMatrix = function () {

	const position = new THREE.Vector3();
	const quaternion = new THREE.Quaternion();
	const scale = new THREE.Vector3();

	return function ( matrix ) {

		position.x = Math.random() * 40 - 20;
		position.y = Math.random() * 40 - 20;
		position.z = Math.random() * 40 - 20;

		quaternion.random();

		scale.x = scale.y = scale.z = Math.random() * 1;

		matrix.compose( position, quaternion, scale );

	};

}();

function initMesh() {

	clean();

	// make instances
	new THREE.BufferGeometryLoader()
		.setPath( 'models/json/' )
		.load( 'suzanne_buffergeometry.json', function ( geometry ) {

			const posY = positionWorld;
			const t = time.mul( 4 );
			material = new MeshPhongNodeMaterial();
			material.colorNode = vec3(
				sin( posY.mul( 0.1 ).add( t ) ).mul( 0.5 ).add( 0.5 ).x,
				sin( posY.mul( 0.1 ).add( t.mul( 0.5 ).add( 2 ) ) ).mul( 0.5 ).add( 0.5 ).y,
				sin( posY.mul( 0.1 ).add( t.mul( 1.5 ).add( 4 ) ) ).mul( 0.5 ).add( 0.5 ).z,
			);

			geometry.computeVertexNormals();

			console.time( api.method + ' (build)' );

			switch ( api.method ) {

				case Method.INSTANCED:
					makeInstanced( geometry );
					break;

				case Method.MERGED:
					makeMerged( geometry );
					break;

				case Method.NAIVE:
					makeNaive( geometry );
					break;

			}

			console.timeEnd( api.method + ' (build)' );

		} );

}

function makeInstanced( geometry ) {

	const matrix = new THREE.Matrix4();
	const mesh = new THREE.InstancedMesh( geometry, material, api.count );

	for ( let i = 0; i < api.count; i ++ ) {

		randomizeMatrix( matrix );
		mesh.setMatrixAt( i, matrix );

	}

	scene.add( mesh );

	//

	const geometryByteLength = getGeometryByteLength( geometry );

	guiStatsEl.innerHTML = [

		'<i>GPU draw calls</i>: 1',
		'<i>GPU memory</i>: ' + formatBytes( api.count * 16 + geometryByteLength, 2 )

	].join( '<br/>' );

}

function makeMerged( geometry ) {

	const geometries = [];
	const matrix = new THREE.Matrix4();

	for ( let i = 0; i < api.count; i ++ ) {

		randomizeMatrix( matrix );

		const instanceGeometry = geometry.clone();
		instanceGeometry.applyMatrix4( matrix );

		geometries.push( instanceGeometry );

	}

	const mergedGeometry = BufferGeometryUtils.mergeGeometries( geometries );

	scene.add( new THREE.Mesh( mergedGeometry, material ) );

	//

	guiStatsEl.innerHTML = [

		'<i>GPU draw calls</i>: 1',
		'<i>GPU memory</i>: ' + formatBytes( getGeometryByteLength( mergedGeometry ), 2 )

	].join( '<br/>' );

}

function makeNaive( geometry ) {

	const matrix = new THREE.Matrix4();

	for ( let i = 0; i < api.count; i ++ ) {

		randomizeMatrix( matrix );

		const mesh = new THREE.Mesh( geometry, material );
		mesh.applyMatrix4( matrix );

		scene.add( mesh );

	}

	//

	const geometryByteLength = getGeometryByteLength( geometry );

	guiStatsEl.innerHTML = [

		'<i>GPU draw calls</i>: ' + api.count,
		'<i>GPU memory</i>: ' + formatBytes( api.count * 16 + geometryByteLength, 2 )

	].join( '<br/>' );

}

function init() {

	const width = window.innerWidth;
	const height = window.innerHeight;

