	controls.target.set( 0, 1, 0 );
	controls.update();

	// GUI

	const gui = renderer.inspector.createParameters( 'Clipping settings' );
	const props = {
		alphaToCoverage: true,
	};

	const folderKnot = gui.addFolder( 'Knot Clipping Group' );
	const propsKnot = {

		get 'Enabled'() {

			return knotClippingGroup.enabled;

		},
		set 'Enabled'( v ) {

			knotClippingGroup.enabled = v;

		},

		get 'Shadows'() {

			return knotClippingGroup.clipShadows;

		},
		set 'Shadows'( v ) {

			knotClippingGroup.clipShadows = v;

		},

		get 'Intersection'() {

			return knotClippingGroup.clipIntersection;

		},

		set 'Intersection'( v ) {

			knotClippingGroup.clipIntersection = v;

		},

		get 'Plane'() {

			return localPlane1.constant;

		},
		set 'Plane'( v ) {

			localPlane1.constant = v;

		}

	};

	const folderGlobal = gui.addFolder( 'Global Clipping Group' );
	const propsGlobal = {

		get 'Enabled'() {

			return globalClippingGroup.enabled;

		},
		set 'Enabled'( v ) {

			globalClippingGroup.enabled = v;

		},

		get 'Plane'() {

			return globalPlane.constant;

		},
		set 'Plane'( v ) {

			globalPlane.constant = v;

		}

	};

	gui.add( props, 'alphaToCoverage' ).onChange( function ( value ) {

		ground.material.alphaToCoverage = value;
		ground.material.needsUpdate = true;

		material.alphaToCoverage = value;
		material.needsUpdate = true;

	} );

	folderKnot.add( propsKnot, 'Enabled' );
	folderKnot.add( propsKnot, 'Shadows' );
	folderKnot.add( propsKnot, 'Intersection' );
	folderKnot.add( propsKnot, 'Plane', 0.3, 1.25 );

	folderGlobal.add( propsGlobal, 'Enabled' );
	folderGlobal.add( propsGlobal, 'Plane', - 0.4, 3 );

	// Start

	startTime = Date.now();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate( currentTime ) {

	const time = ( currentTime - startTime ) / 1000;

	object.position.y = 0.8;
	object.rotation.x = time * 0.5;
	object.rotation.y = time * 0.2;
	object.scale.setScalar( Math.cos( time ) * 0.125 + 0.875 );

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';

import { Inspector } from 'three/addons/inspector/Inspector.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

let camera, scene, renderer, object;
let planes, planeObjects, planeHelpers;
let timer;

const params = {

	animate: true,
	planeX: {

		constant: 0,
		negated: false,
		displayHelper: false

	},
	planeY: {

		constant: 0,
		negated: false,
		displayHelper: false

	},
	planeZ: {

		constant: 0,
		negated: false,
		displayHelper: false

	}


};

init();

function createPlaneStencilGroup( geometry, plane, stencilBit, renderOrder ) {

	const group = new THREE.ClippingGroup();
	group.clippingPlanes = [ plane ];

	const material = new THREE.MeshBasicNodeMaterial();
	material.side = THREE.DoubleSide;
	material.depthWrite = false;
	material.depthTest = false;
	material.colorWrite = false;
	material.stencilWrite = true;
	material.stencilWriteMask = stencilBit;
	material.stencilFunc = THREE.AlwaysStencilFunc;
	material.stencilFail = THREE.InvertStencilOp;
	material.stencilZFail = THREE.InvertStencilOp;
	material.stencilZPass = THREE.InvertStencilOp;

	const mesh = new THREE.Mesh( geometry, material );
	mesh.renderOrder = renderOrder;
	group.add( mesh );

	return group;

}

function init() {

	timer = new THREE.Timer();
	timer.connect( document );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x263238 );

	camera = new THREE.PerspectiveCamera( 36, window.innerWidth / window.innerHeight, 1, 100 );
	camera.position.set( 2, 2, 2 );

	scene.add( new THREE.AmbientLight( 0xffffff, 1.5 ) );

	const dirLight = new THREE.DirectionalLight( 0xffffff, 3 );
	dirLight.position.set( 5, 10, 7.5 );
	dirLight.castShadow = true;
	dirLight.shadow.camera.right = 2;
	dirLight.shadow.camera.left = - 2;
	dirLight.shadow.camera.top	= 2;
	dirLight.shadow.camera.bottom = - 2;

	dirLight.shadow.mapSize.width = 1024;
	dirLight.shadow.mapSize.height = 1024;
	scene.add( dirLight );

	planes = [
		new THREE.Plane( new THREE.Vector3( - 1, 0, 0 ), 0 ),
		new THREE.Plane( new THREE.Vector3( 0, - 1, 0 ), 0 ),
		new THREE.Plane( new THREE.Vector3( 0, 0, - 1 ), 0 )
	];

	planeHelpers = planes.map( p => new THREE.PlaneHelper( p, 2, 0xffffff ) );
	planeHelpers.forEach( ph => {

		ph.visible = false;
		scene.add( ph );

	} );

	const geometry = new THREE.TorusKnotGeometry( 0.4, 0.15, 220, 60 );
	object = new THREE.Group();
	scene.add( object );

	// Set up clip plane rendering

	planeObjects = [];
	const planeGeom = new THREE.PlaneGeometry( 4, 4 );

	for ( let i = 0; i < 3; i ++ ) {

		const plane = planes[ i ];
		const stencilBit = 1 << i;

		const stencilGroup = createPlaneStencilGroup( geometry, plane, stencilBit, i + 1 );
		object.add( stencilGroup );

		// the cap is only rendered where the stencil bit of its plane is set
		// and is clipped by the other clipping planes

		const planeMat =
			new THREE.MeshStandardNodeMaterial( {

				color: 0xE91E63,
				metalness: 0.1,
				roughness: 0.75,

				stencilWrite: true,
				stencilRef: 0,
				stencilFuncMask: stencilBit,
				stencilWriteMask: stencilBit,
				stencilFunc: THREE.NotEqualStencilFunc,
				stencilFail: THREE.ReplaceStencilOp,
				stencilZFail: THREE.ReplaceStencilOp,
				stencilZPass: THREE.ReplaceStencilOp,

			} );
		const po = new THREE.Mesh( planeGeom, planeMat );
		po.renderOrder = i + 1.1;

		const poGroup = new THREE.ClippingGroup();
		poGroup.clippingPlanes = planes.filter( p => p !== plane );
		poGroup.add( po );

		planeObjects.push( po );
		scene.add( poGroup );

	}

	const clippingGroup = new THREE.ClippingGroup();
	clippingGroup.clippingPlanes = planes;
	clippingGroup.clipShadows = true;
	object.add( clippingGroup );

	const material = new THREE.MeshStandardNodeMaterial( {

		color: 0xFFC107,
		metalness: 0.1,
		roughness: 0.75,
		shadowSide: THREE.DoubleSide

	} );

	// add the color

	const clippedColorFront = new THREE.Mesh( geometry, material );
	clippedColorFront.castShadow = true;
	clippedColorFront.renderOrder = 6;
	clippingGroup.add( clippedColorFront );

	const ground = new THREE.Mesh(
		new THREE.PlaneGeometry( 9, 9, 1, 1 ),
		new THREE.ShadowNodeMaterial( { color: 0x000000, opacity: 0.25, side: THREE.DoubleSide } )
	);

	ground.rotation.x = - Math.PI / 2; // rotates X/Y to X/Z
	ground.position.y = - 1;
	ground.receiveShadow = true;
	scene.add( ground );

	// Renderer

	renderer = new THREE.WebGPURenderer( { antialias: true, stencil: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	//

	window.addEventListener( 'resize', onWindowResize );

	// Controls

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 2;
	controls.maxDistance = 20;
	controls.update();

	// GUI

	const gui = renderer.inspector.createParameters( 'Clipping settings' );
	gui.add( params, 'animate' );

	const planeX = gui.addFolder( 'planeX' );
	planeX.add( params.planeX, 'displayHelper' ).onChange( v => planeHelpers[ 0 ].visible = v );
	planeX.add( params.planeX, 'constant', - 1, 1 ).onChange( d => planes[ 0 ].constant = d );
	planeX.add( params.planeX, 'negated' ).onChange( () => {

		planes[ 0 ].negate();
		params.planeX.constant = planes[ 0 ].constant;

	} );

	const planeY = gui.addFolder( 'planeY' );
	planeY.add( params.planeY, 'displayHelper' ).onChange( v => planeHelpers[ 1 ].visible = v );
	planeY.add( params.planeY, 'constant', - 1, 1 ).onChange( d => planes[ 1 ].constant = d );
	planeY.add( params.planeY, 'negated' ).onChange( () => {

		planes[ 1 ].negate();
		params.planeY.constant = planes[ 1 ].constant;

	} );

	const planeZ = gui.addFolder( 'planeZ' );
	planeZ.add( params.planeZ, 'displayHelper' ).onChange( v => planeHelpers[ 2 ].visible = v );
	planeZ.add( params.planeZ, 'constant', - 1, 1 ).onChange( d => planes[ 2 ].constant = d );
	planeZ.add( params.planeZ, 'negated' ).onChange( () => {

		planes[ 2 ].negate();
		params.planeZ.constant = planes[ 2 ].constant;

	} );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	const delta = timer.getDelta();

	if ( params.animate ) {

		object.rotation.x += delta * 0.5;
		object.rotation.y += delta * 0.2;

	}

	for ( let i = 0; i < planeObjects.length; i ++ ) {

		const plane = planes[ i ];
		const po = planeObjects[ i ];
		plane.coplanarPoint( po.position );
		po.lookAt(
			po.position.x - plane.normal.x,
			po.position.y - plane.normal.y,
			po.position.z - plane.normal.z,
		);

	}

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';
import { uv, float, vec3, hash, mx_noise_vec3, mx_worley_noise_vec3, mx_cell_noise_float, mx_fractal_noise_vec3 } from 'three/tsl';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';

let MESH_COUNT = 256;
let GRID_SIZE = 16;
const ADD_DELAY = 1000;

let camera, scene, renderer;
let sphere;
let gui;

// Frame timing
let lastFrameTime = 0;
let longestFrameTime = 0;
let isTracking = false;
let shouldStartTracking = false;
let sphereStartTime = 0;
let currentMode = '';
let framesAfterComplete = 0;
let testDone = false;
let meshGroup = null;

const longestFrameEl = document.getElementById( 'longestFrame' );
const meshCountEl = document.getElementById( 'meshCount' );
const compileModeEl = document.getElementById( 'compileMode' );

const params = {
	withoutCompile: function () {

		window.location.href = window.location.pathname + '?mode=no-compile';

	},
	withCompileAsync: function () {

		window.location.href = window.location.pathname + '?mode=compile-async';

	}
};

init();

async function init() {

	// GUI
	gui = new GUI();
	gui.add( params, 'withoutCompile' ).name( 'Build on render' );
	gui.add( params, 'withCompileAsync' ).name( 'Pre-build (compileAsync)' );

	window.addEventListener( 'resize', onWindowResize );

	// Orthographic camera
	const aspect = window.innerWidth / window.innerHeight;
	const frustumSize = 20;
	camera = new THREE.OrthographicCamera(
		frustumSize * aspect / - 2,
		frustumSize * aspect / 2,
		frustumSize / 2,
		frustumSize / - 2,
		0.1,
		100
	);
	camera.position.set( 0, 0, 20 );
	camera.lookAt( 0, 0, 0 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x111111 );

	// Create animated sphere
	const sphereGeometry = new THREE.SphereGeometry( 0.5, 32, 32 );
	const sphereMaterial = new THREE.MeshNormalMaterial();
	sphere = new THREE.Mesh( sphereGeometry, sphereMaterial );
	scene.add( sphere );

	// Renderer
	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	// Reduce mesh count for WebGL (slower compilation)
	if ( renderer.backend.isWebGLBackend ) {

		MESH_COUNT = 64;
		GRID_SIZE = 8;
		document.getElementById( 'materialCount' ).textContent = '64';
		meshCountEl.textContent = '0 / 64';

	}

	// Get mode from URL
	const urlParams = new URLSearchParams( window.location.search );
	const mode = urlParams.get( 'mode' ) || 'compile-async';

	const modeLabel = mode === 'compile-async' ? 'Pre-build (compileAsync)' : 'Build on render';
	compileModeEl.textContent = modeLabel;

	// Start sphere animation
	sphereStartTime = performance.now();

	// Schedule mesh addition after delay
	setTimeout( () => addMeshes( mode ), ADD_DELAY );

}

function createUniqueMaterial( index ) {

	const material = new THREE.MeshBasicNodeMaterial();

	const seed = float( index * 0.1 + 1.0 );
	const scale = float( ( index % 5 ) + 2.0 );
	const uvNode = uv().mul( scale ).add( hash( float( index ) ) );

	const noiseType = index % 4;
	let colorNode;

	switch ( noiseType ) {

		case 0:
			colorNode = mx_noise_vec3( uvNode.mul( seed ) ).mul( 0.5 ).add( 0.5 );
			break;

		case 1:
			colorNode = mx_worley_noise_vec3( uvNode.mul( seed.mul( 0.5 ) ) );
			break;

		case 2:
			const cellNoise = mx_cell_noise_float( uvNode.mul( seed ) );
			colorNode = vec3( cellNoise, cellNoise.mul( 0.7 ), cellNoise.mul( 0.4 ) );
			break;

		case 3:
			colorNode = mx_fractal_noise_vec3( uvNode.mul( seed.mul( 0.3 ) ), float( 3 ), float( 2.0 ), float( 0.5 ) )
				.mul( 0.5 ).add( 0.5 );
			break;

	}

	const tintR = hash( float( index * 3 ) );
	const tintG = hash( float( index * 3 + 1 ) );
	const tintB = hash( float( index * 3 + 2 ) );
	const tint = vec3( tintR, tintG, tintB ).mul( 0.3 ).add( 0.7 );

	material.colorNode = colorNode.mul( tint );

	return material;

}

async function addMeshes( mode ) {

	const geometry = new THREE.PlaneGeometry( 0.9, 0.9 );
	const startX = - ( GRID_SIZE - 1 ) / 2;
	const startY = - ( GRID_SIZE - 1 ) / 2;

	meshGroup = new THREE.Group();

	for ( let i = 0; i < MESH_COUNT; i ++ ) {

		const material = createUniqueMaterial( i );
		const mesh = new THREE.Mesh( geometry, material );

		const col = i % GRID_SIZE;
		const row = Math.floor( i / GRID_SIZE );

		mesh.position.x = startX + col;
		mesh.position.y = startY + row;

		meshGroup.add( mesh );

	}

	currentMode = mode;

	if ( mode === 'compile-async' ) {

		// Pre-compile all meshes before adding to scene
		// Start tracking BEFORE compile to measure longest frame during compile
		shouldStartTracking = true;

		await renderer.compileAsync( meshGroup, camera, scene );

		// Add all meshes at once (already compiled - should render instantly)
		scene.add( meshGroup );
		testDone = true;

	} else {

		// Add all meshes at once - renderer compiles on-demand
		// Meshes appear progressively as they compile
		scene.add( meshGroup );

		// Start tracking on next animate() frame
		shouldStartTracking = true;
		testDone = true;

	}

}

function finishTest() {

	isTracking = false;

	longestFrameEl.textContent = longestFrameTime.toFixed( 1 ) + ' ms';
	longestFrameEl.className = longestFrameTime > 100 ? 'value bad' : 'value';

}

function onWindowResize() {

	if ( ! renderer || ! camera ) return;

	const aspect = window.innerWidth / window.innerHeight;
	const frustumSize = 12;

	camera.left = frustumSize * aspect / - 2;
	camera.right = frustumSize * aspect / 2;
	camera.top = frustumSize / 2;
	camera.bottom = frustumSize / - 2;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	const now = performance.now();

	// Initialize tracking on first frame after meshes added
	if ( shouldStartTracking ) {

