	}

	// Finish test - wait a few frames after testDone to capture frame times
	if ( isTracking && testDone ) {

		framesAfterComplete ++;

		// Wait longer for deferred mode (meshes compile progressively)
		const framesToWait = currentMode === 'compile-async' ? 2 : 60;

