init();

async function init() {

	const { innerWidth, innerHeight } = window;

	camera = new THREE.PerspectiveCamera( 60, innerWidth / innerHeight, .1, 100 );
	camera.position.set( 20, 2, 20 );
	camera.layers.enable( 2 );
