import * as THREE from 'three/webgpu';
import { color, fog, positionWorld, triNoise3D, normalWorld, uniform, densityFogFactor } from 'three/tsl';

import { FirstPersonControls } from 'three/addons/controls/FirstPersonControls.js';
import { Inspector } from 'three/addons/inspector/Inspector.js';
import { SkyMesh } from 'three/addons/objects/SkyMesh.js';
import { TerrainGenerator } from 'three/addons/generators/TerrainGenerator.js';
import { ForestGenerator } from 'three/addons/generators/ForestGenerator.js';

let camera, scene, renderer, controls, timer;
let terrain, forest, terrainGroup, forestGroup;
let sky, sun, sunLight, pmremGenerator, envScene, envRenderTarget;

const parameters = {
	elevation: 11, // sun height above the horizon, in degrees ( low = golden hour )
	azimuth: 150 // sun compass direction, in degrees
};

init();

async function init() {

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 0.62;
	renderer.shadowMap.enabled = true;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	pmremGenerator = new THREE.PMREMGenerator( renderer );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 1, 20000 );
	camera.position.set( - 50, 88, 230 );

	scene = new THREE.Scene();
	scene.environmentIntensity = 0.16; // a dim, cool sky fill so the warm sun stays the key and shadows read

	// a physical sky, used only to bake the image-based lighting ( it is not
	// the visible background — the fog gradient below is ); elevation / azimuth move the sun

	sky = new SkyMesh();
	sky.scale.setScalar( 10000 );
	sky.turbidity.value = 12;
	sky.rayleigh.value = 2;
	sky.mieCoefficient.value = 0.005;
	sky.mieDirectionalG.value = 0.88;

	sun = new THREE.Vector3();
	envScene = new THREE.Scene();
	sky.showSunDisc.value = false;
	envScene.add( sky );

	// custom fog. an animated, two-octave triNoise3D haze that settles into
	// the valley as a level band: solid below `fogBase` ( down under the
	// mountains ) and fading out by `fogTop` ( around mid-height ), so the
	// peaks rise clear above it. the band sits at a fixed altitude whatever
	// the distance, and the noise wobbles its top edge and drifts it through
	// world space, so it reads as slow-moving cloud. ( the peaks reach ~130 )

	const skyColorValue = 0xf0f5f5;
	const groundColorValue = 0xd0dee7;

	const skyColor = color( skyColorValue );
	const groundColor = color( groundColorValue );

	const fogBase = uniform( - 20 ); // world-y the fog is solid below ( the valley floor )
	const fogTop = uniform( 55 ); // world-y the fog fades out by ( mid-mountain )
	const haze = uniform( 0.0012 ); // distance haze, so the far peaks dissolve into the same grey

	// a alternative way to create a TimerNode
	const time = uniform( 0 ).onFrameUpdate( ( frame ) => frame.time );

	const fogNoiseA = triNoise3D( positionWorld.mul( .005 ), 0.2, time );
	const fogNoiseB = triNoise3D( positionWorld.mul( .01 ), 0.2, time.mul( 1.2 ) );

	const fogNoise = fogNoiseA.add( fogNoiseB );

	// the noise lifts and drops the top of the band so it breaks into wisps
	const top = fogTop.add( fogNoise.sub( 0.7 ).mul( 22 ) );
	const groundFogArea = top.sub( positionWorld.y ).div( top.sub( fogBase ) ).saturate().mul( .98 );

	// the valley band plus a distance haze, so the far peaks dissolve into the grey too
	const fogArea = groundFogArea.oneMinus().mul( densityFogFactor( haze ).oneMinus() ).oneMinus();

	scene.fogNode = fog( groundColor, fogArea );
	scene.backgroundNode = normalWorld.y.max( 0 ).mix( groundColor, skyColor );

	// terrain + forest

	terrain = new TerrainGenerator( {
		seed: 1,
		size: 900,
		segments: 512,
		frequency: 0.0065,
		heightScale: 150,
		erosion: 0.7,
		valleyBias: 1.2
	} );

	forest = new ForestGenerator( { count: 500000, castShadow: true } );

	generate();

	// a single directional key aligned with the sky's sun, for the crisp relief
	// shadows the sky fill alone can't give. its colour, intensity and position —
	// and the baked environment — are set by updateSun()

	sunLight = new THREE.DirectionalLight();
	sunLight.castShadow = true;
	sunLight.shadow.camera.left = - 420;
	sunLight.shadow.camera.right = 420;
	sunLight.shadow.camera.top = 420;
	sunLight.shadow.camera.bottom = - 420;
	sunLight.shadow.camera.near = 200;
	sunLight.shadow.camera.far = 1800;
	sunLight.shadow.mapSize.set( 4096, 4096 );
	sunLight.shadow.bias = - 0.0004;
	sunLight.shadow.normalBias = 0.15;
	sunLight.shadow.autoUpdate = false; // the scene is static — re-render the shadow map only when the sun moves ( see updateSun ), not every frame
	scene.add( sunLight );

	updateSun();

	// gui

	const gui = renderer.inspector.createParameters( 'Settings' );

	const skyFolder = gui.addFolder( 'Sun' );
	skyFolder.add( parameters, 'elevation', 1, 40 ).step( 0.5 ).name( 'elevation' ).onChange( updateSun );
	skyFolder.add( parameters, 'azimuth', 0, 360 ).step( 1 ).name( 'azimuth' ).onChange( updateSun );

	const fogFolder = gui.addFolder( 'Fog' );
	fogFolder.add( fogBase, 'value', - 40, 20 ).step( 1 ).name( 'base' );
	fogFolder.add( fogTop, 'value', 0, 130 ).step( 1 ).name( 'top' );
	fogFolder.add( haze, 'value', 0, 0.005 ).step( 0.0001 ).name( 'haze' );

	const forestFolder = gui.addFolder( 'Forest' );
	forestFolder.add( forest.from, 'value', 50, 1000 ).step( 10 ).name( 'cull from' );
	forestFolder.add( forest.to, 'value', 100, 1400 ).step( 10 ).name( 'cull to' );

	const terrainFolder = gui.addFolder( 'Terrain' );
	terrainFolder.add( terrain.parameters, 'erosion', 0, 1.5 ).step( 0.05 ).name( 'erosion' );
	terrainFolder.add( terrain.parameters, 'valleyBias', 1, 3 ).step( 0.1 ).name( 'valley bias' );
	terrainFolder.add( { newSeed }, 'newSeed' ).name( 'regenerate' );

	// controls

	timer = new THREE.Timer();

	controls = new FirstPersonControls( camera, renderer.domElement );
	controls.movementSpeed = 20;
	controls.lookSpeed = 0.2;
	controls.lookAt( 0, 5, - 120 ); // face across the valley

	window.addEventListener( 'resize', resize );

}

// walks the sun: aligns the sky and the key light ( warm and dim near the
// horizon ), then re-bakes the sky into the IBL environment
function updateSun() {

	const elevation = parameters.elevation;

	sun.setFromSphericalCoords(
		1,
		THREE.MathUtils.degToRad( 90 - elevation ),
		THREE.MathUtils.degToRad( parameters.azimuth )
	);
	sky.sunPosition.value.copy( sun );

	// the longer air path near the horizon dims and warms the sun. it stays
	// far brighter than the sky fill, so it reads as the key and casts firm shadows
	const transmittance = Math.sqrt( Math.max( Math.sin( THREE.MathUtils.degToRad( elevation ) ), 0 ) );
	sunLight.color.set( 0xff7a2f ).lerp( new THREE.Color( 0xfff2e0 ), transmittance ); // deep orange → warm white
	sunLight.intensity = 11 * transmittance + 0.3;
	sunLight.position.copy( sun ).multiplyScalar( 900 );
	sunLight.shadow.needsUpdate = true; // the sun moved, so the on-demand shadow map needs one refresh

	// Reuse the environment render target when the sun moves.
	envRenderTarget = pmremGenerator.fromScene( envScene, 0, 0.1, 100, { renderTarget: envRenderTarget } );
	scene.environment = envRenderTarget.texture;

}

// a new seed ( and whatever erosion / valley bias is dialled in ) rebuilds
// the terrain, and with it the forest that sits on top
function newSeed() {

	terrain.parameters.seed ++;
	generate();

}

// the forest sits on the terrain, so a new terrain means a new forest
function generate() {

	if ( terrainGroup ) scene.remove( terrainGroup );
	if ( forestGroup ) scene.remove( forestGroup );

	terrainGroup = terrain.build();
	forestGroup = forest.build( terrain );

	scene.add( terrainGroup );
	scene.add( forestGroup );

	if ( sunLight ) sunLight.shadow.needsUpdate = true; // rebuilt geometry ⇒ re-render the shadow map ( skipped on the first build, before the light exists; updateSun covers it )

}

function resize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	controls.update( timer.getDelta() );

	forest.setCameraPosition( camera.position ); // drives the forest cull

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';
import { pass, color, rangeFogFactor } from 'three/tsl';

import { UltraHDRLoader } from 'three/addons/loaders/UltraHDRLoader.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

let camera, scene, renderer;
let renderPipeline;

init();

function init() {

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.25, 20 );
	camera.position.set( - 1.8, 0.6, 2.7 );

	scene = new THREE.Scene();

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.toneMapping = THREE.NoToneMapping; // apply tone mapping in post processing, instead
	document.body.appendChild( renderer.domElement );

	// post processing

	// render scene pass
	const scenePass = pass( scene, camera );
	const scenePassViewZ = scenePass.getViewZNode();

	// fog color
	const fogColor = color( 0x4080cc ); // in sRGB color space

	// get fog factor from the scene pass context
	// equivalent to: scene.fog = new THREE.Fog( 0x4080cc, 2.7, 4 );
	const fogFactor = rangeFogFactor( 2.7, 4 ).context( { getViewZ: () => scenePassViewZ } );

	// tone-mapped scene pass
	const scenePassTM = scenePass.toneMapping( THREE.ACESFilmicToneMapping, 1 );

	// mix fog using fog factor and fog color
	const compose = fogFactor.mix( scenePassTM, fogColor );

	renderPipeline = new THREE.RenderPipeline( renderer );
	renderPipeline.outputColorTransform = true; // no tone mapping will be applied, only the default color space transform
	renderPipeline.outputNode = compose;

	//

	new UltraHDRLoader()
		.setPath( 'textures/equirectangular/' )
		.load( 'royal_esplanade_2k.hdr.jpg', function ( texture ) {

			texture.mapping = THREE.EquirectangularReflectionMapping;
			scene.environment = texture;

			// model

			const loader = new GLTFLoader().setPath( 'models/gltf/DamagedHelmet/glTF/' );
			loader.load( 'DamagedHelmet.gltf', function ( gltf ) {

				scene.add( gltf.scene );

			} );

		} );

	//

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 2;
	controls.maxDistance = 5;
	controls.target.set( 0, - 0.1, - 0.2 );
	controls.update();

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function animate() {

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { densityFogFactor, mix, pass, positionLocal, reference, uniform, vec2 } from 'three/tsl';
import { gaussianBlur } from 'three/addons/tsl/display/GaussianBlurNode.js';

import { FirstPersonControls } from 'three/addons/controls/FirstPersonControls.js';
import { Inspector } from 'three/addons/inspector/Inspector.js';
import { TreeGenerator, createTreeMaterial } from 'three/addons/generators/TreeGenerator.js';

let camera, scene, renderer, renderPipeline, controls;

const timer = new THREE.Timer();

const params = {
	scatteringEnabled: true
};

init();

function init() {

	camera = new THREE.PerspectiveCamera( 55, window.innerWidth / window.innerHeight, 0.1, 120 );
	camera.position.set( 0.4, 1.7, 9 ); // ~human eye height

	scene = new THREE.Scene();

	// fog: a bright, cool haze. the background matches it so the trunks read
	// as dark silhouettes that dissolve into depth — the scattering subject

	scene.fog = new THREE.FogExp2( 0xc6cace, 0.11 );
	scene.background = new THREE.Color( 0xc6cace );
	updateFogRange();

	// Soft sky light reveals the bark nearby; the distant trees fade into silhouettes.

	const treeMaterial = createTreeMaterial( { barkColor: 0x302c28, barkScale: new THREE.Vector3( 35, 2, 35 ) } );
	treeMaterial.colorNode = treeMaterial.colorNode.mul( positionLocal.y.smoothstep( 0, 0.5 ) );

	scene.add( new THREE.HemisphereLight( 0xdce6ed, 0x292521, 1.5 ) );

	const skyLight = new THREE.DirectionalLight( 0xdce6ed, 2 );
	skyLight.position.set( - 3, 8, 5 );
	scene.add( skyLight );

	// Bare deciduous trees with uneven crowns, gently curved trunks and fine twigs.

	const variants = [];

	const generator = new TreeGenerator( treeMaterial )
		.setTaper( 0.94 )
		.setTaperCurve( 0.85 )
		.setLevels( 5 )
		.setBranchAngle( [ 62, 46, 38, 32 ] )
		.setAngleVariance( 24 )
		.setLengthRatio( 0.62 )
		.setLengthVariance( 0.3 )
		.setBranchLengthFalloff( 0.45 )
		.setMinLength( 0.04 )
		.setDroop( 0.08 )
		.setUpPull( 0.18 )
		.setGnarl( [ 0.045, 0.13, 0.2, 0.26, 0.3 ] )
		.setSectionLength( 0.26 )
		.setRadialSegments( 7 )
		.setRadiusExponent( 2 )
		.setMinRadius( 0.0007 )
		.setRootFlare( 0.5 )
		.setFlareFrac( 0.12 )
		.setChildStart( 0.22 );

	for ( let v = 0; v < 10; v ++ ) {

		const mesh = generator
			.setSeed( v + 1 )
			.setTrunkLength( 3.4 + v * 0.16 )
			.setTrunkRadius( 0.065 + v * 0.004 )
			.setChildren( [ 7 + v % 3, 4, 3, 1 ] )
			.setTrunkClear( 0.38 + ( v % 4 ) * 0.05 )
			.build();

		variants.push( mesh.geometry );

	}

	const placements = variants.map( () => [] );

	THREE.MathUtils.seededRandom( 25 );
	const random = THREE.MathUtils.seededRandom;
	const dummy = new THREE.Object3D();
	const cols = 13, rows = 12, spacing = 1.9;

	for ( let i = 0; i < cols; i ++ ) {

		for ( let j = 0; j < rows; j ++ ) {

			const v = Math.floor( random() * variants.length );

			const x = ( i - cols / 2 ) * spacing + ( random() - 0.5 ) * spacing * 1.4;
			const z = j * spacing - rows * spacing + 4.2 + ( random() - 0.5 ) * spacing * 1.4;

			dummy.position.set( x, 0, z );

			const scale = 0.7 + random() * 0.65;
			dummy.rotation.set( ( random() - 0.5 ) * 0.08, random() * Math.PI * 2, ( random() - 0.5 ) * 0.08 );
			dummy.scale.set( scale, scale * ( 0.85 + random() * 0.3 ), scale );
			dummy.updateMatrix();

			placements[ v ].push( dummy.matrix.clone() );

		}

	}

	variants.forEach( ( geometry, v ) => {

		const list = placements[ v ];
		const mesh = new THREE.InstancedMesh( geometry, treeMaterial, list.length );
		for ( let k = 0; k < list.length; k ++ ) mesh.setMatrixAt( k, list[ k ] );
		mesh.instanceMatrix.needsUpdate = true;
		scene.add( mesh );

	} );

	// a couple of dominant trunks close to the camera to anchor the depth

	[[ - 1.1, 4.9, 1.25, 1.1, 8 ], [ 1.5, 4, 1.1, 0.3, 5 ]].forEach( ( [ x, z, s, ry, v ] ) => {

		const hero = new THREE.Mesh( variants[ v ], treeMaterial );
		hero.position.set( x, 0, z );
		hero.rotation.y = ry;
		hero.scale.setScalar( s );
		scene.add( hero );

	} );

	// ground

	const groundMaterial = new THREE.MeshBasicMaterial( { color: 0x000000 } );
	const ground = new THREE.Mesh( new THREE.PlaneGeometry( 600, 600 ).rotateX( - Math.PI / 2 ), groundMaterial );
	scene.add( ground );

	// renderer

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	// controls

	controls = new FirstPersonControls( camera, renderer.domElement );
	controls.movementSpeed = 2;
	controls.lookSpeed = 0.2;
	controls.lookAt( - 0.2, 1.7, - 8 );

	renderPipeline = new THREE.RenderPipeline( renderer );

	// uniforms

	const density = reference( 'density', 'float', scene.fog );
	const scattering = uniform( 2 );

	// scene pass

	const scenePass = pass( scene, camera );

	const scenePassColor = scenePass.getTextureNode( 'output' );
	const scenePassViewZ = scenePass.getViewZNode();

	// blur pass (always downsampled to improve performance)

	const sceneColorBlurred = gaussianBlur( scenePassColor, vec2( scattering ), 4, { resolutionScale: 0.5 } );

	// composite

	const fogFactor = densityFogFactor( density ).context( { getViewZ: () => scenePassViewZ } );

	const compositeNode = mix( scenePassColor, sceneColorBlurred, fogFactor );

	renderPipeline.outputNode = compositeNode;

	// gui

	const gui = renderer.inspector.createParameters( 'Settings' );
	gui.add( scene.fog, 'density', 0.025, 0.16 ).step( 0.0005 ).name( 'fog density' ).onChange( updateFogRange );
	gui.add( scattering, 'value', 0, 5 ).name( 'scattering factor' );
	gui.add( params, 'scatteringEnabled' ).name( 'enable scattering' ).onChange( ( value ) => {

		renderPipeline.outputNode = value === true ? compositeNode : scenePassColor;
		renderPipeline.needsUpdate = true;

	} );

	window.addEventListener( 'resize', resize );

}

function updateFogRange() {

	// Clip where FogExp2 leaves only 0.1% of the unfogged scene color.
	camera.far = Math.min( 120, Math.sqrt( - Math.log( 0.001 ) ) / scene.fog.density );
	camera.updateProjectionMatrix();

}

function resize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();
	controls.update( timer.getDelta() );

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { vec4, normalView, pass, diffuseColor, positionGeometry, positionView, positionViewDirection, roughness, metalness, mrt, Fn, overrideNodes } from 'three/tsl';

import { Inspector } from 'three/addons/inspector/Inspector.js';

import { UltraHDRLoader } from 'three/addons/loaders/UltraHDRLoader.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { TeapotGeometry } from 'three/addons/geometries/TeapotGeometry.js';

const RESOLVE_LAYER = 2;

let camera, scene, renderer;
let renderPipeline;
let lightGroup, planesGroup;
let params;

const timer = new THREE.Timer();

init();

function init() {

	const container = document.createElement( 'div' );
	document.body.appendChild( container );

	// scene

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.25, 20 );
	camera.position.set( - 1.8, 0.6, 2.7 );

	scene = new THREE.Scene();

	new UltraHDRLoader()
		.setPath( 'textures/equirectangular/' )
		.load( 'royal_esplanade_2k.hdr.jpg', function ( texture ) {

			texture.mapping = THREE.EquirectangularReflectionMapping;

			scene.background = texture;
			scene.environment = texture;

			// teapot model
			const teapotGeometry = new TeapotGeometry( 0.4, 18 );
			const teapotMaterial = new THREE.MeshStandardMaterial( { color: 0x333333, roughness: 0.2, metalness: 0.8 } );
			const teapot = new THREE.Mesh( teapotGeometry, teapotMaterial );
			teapot.position.y = - 0.15;
			scene.add( teapot );

		} );

	// light group
	lightGroup = new THREE.Group();
	lightGroup.position.y = - 0.15;
	scene.add( lightGroup );

	const numLights = 8;
	const radius = 1.2;
	const sphereGeometry = new THREE.SphereGeometry( 0.03, 16, 8 );

	for ( let i = 0; i < numLights; i ++ ) {

		const angle = ( i / numLights ) * Math.PI * 2;
		const x = Math.cos( angle ) * radius;
		const z = Math.sin( angle ) * radius;

		const colorHex = new THREE.Color().setHSL( i / numLights, 1.0, 0.5 );

		const lightMat = new THREE.MeshStandardMaterial( { color: colorHex } );
		const lightMesh = new THREE.Mesh( sphereGeometry, lightMat );

		const light = new THREE.PointLight( colorHex, 5, 5 );
		light.layers.enable( RESOLVE_LAYER );
		light.position.set( x, 0, z );
		light.add( lightMesh );

		lightGroup.add( light );

	}

	// planes group
	planesGroup = new THREE.Group();
	planesGroup.position.y = - 0.15;
	scene.add( planesGroup );

	const planeGeometry = new THREE.PlaneGeometry( 0.4, 0.4 );
	const planeMaterial = new THREE.MeshStandardMaterial( { color: 0x999999, roughness: 0.5, metalness: 0.5, side: THREE.DoubleSide, transparent: true, opacity: 0.5 } );

	const numPlanes = 6;
	const planesRadius = 1.5;

	for ( let i = 0; i < numPlanes; i ++ ) {

		const angle = ( i / numPlanes ) * Math.PI * 2;

		const pivot = new THREE.Group();
		pivot.rotation.y = angle;
		planesGroup.add( pivot );

		const plane = new THREE.Mesh( planeGeometry, planeMaterial );
		plane.position.z = planesRadius;
		pivot.add( plane );

	}

	// renderer

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( render );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.inspector = new Inspector();
	container.appendChild( renderer.domElement );

	// opaque pass

	const opaquePass = pass( scene, camera );
	opaquePass.name = 'opaque pass';
	opaquePass.transparent = false;
	opaquePass.setLayers( new THREE.Layers() ); // default layer 0 is used by the renderer
	opaquePass.setMRT( mrt( {
		output: diffuseColor,
		position: vec4( positionView, metalness ),
		normal: vec4( normalView, roughness )
	} ) );

	opaquePass.lighting = new THREE.Lighting();
	opaquePass.lighting.enabled = false;

	// opaque nodes

	const opaqueOutputNode = opaquePass.getTextureNode( 'output' ).toInspector( 'output' );
	const opaquePositionView = opaquePass.getTextureNode( 'position' ).xyz.toInspector( 'position' );
	const opaqueNormalView = opaquePass.getTextureNode( 'normal' ).xyz.toInspector( 'normal' );
	const opaqueDepthNode = opaquePass.getTextureNode( 'depth' ).toInspector( 'depth' );
	const opaqueMetalness = opaquePass.getTextureNode( 'position' ).w.toInspector( 'metalness' );
	const opaqueRoughness = opaquePass.getTextureNode( 'normal' ).w.toInspector( 'roughness' );

	// resolve opaque pass - deferred lighting

	const resolveLayers = new THREE.Layers();
	resolveLayers.disableAll();
	resolveLayers.enable( RESOLVE_LAYER );

	// the resolve material must be compatible with the other materials in the scene;
	// in common deferred rendering scenarios, a standardized material is used.

	const resolveMaterial = new THREE.MeshStandardNodeMaterial();
	resolveMaterial.colorNode = Fn( () => {

		opaqueDepthNode.greaterThanEqual( 1.0 ).discard();

		return opaqueOutputNode;

	} )();
	resolveMaterial.metalnessNode = opaqueMetalness;
	resolveMaterial.roughnessNode = opaqueRoughness;
	resolveMaterial.vertexNode = vec4( positionGeometry.xy, 0.0, 1.0 );
	resolveMaterial.depthNode = opaqueDepthNode;
	resolveMaterial.contextNode =
		overrideNodes( [
			[ positionView, opaquePositionView ],
			[ positionViewDirection, opaquePositionView.negate().normalize() ],
			[ normalView, opaqueNormalView ]
		] );

	const resolveMesh = new THREE.QuadMesh( resolveMaterial );
	resolveMesh.layers.set( RESOLVE_LAYER );
	scene.add( resolveMesh );

	const resolvedPass = pass( scene, camera );
	resolvedPass.setLayers( resolveLayers );
	resolvedPass.lighting = new THREE.Lighting();

	// transparent pass

	const opaqueDepthTexture = opaquePass.getTexture( 'depth' );

	const transparentPass = pass( scene, camera, { depthTexture: opaqueDepthTexture, autoClearDepth: false } );
	transparentPass.name = 'transparent pass';
	transparentPass.setLayers( new THREE.Layers() ); // default layer 0 is used by the renderer
	transparentPass.opaque = false;

	// forward pass

	const forwardPass = pass( scene, camera ).toInspector( 'forward' );

	// resolved - render pipeline

	const opaqueNode = resolvedPass.toInspector( 'resolved opaque' );
	const transparentNode = transparentPass.toInspector( 'transparent' );

	const deferredNode = vec4( opaqueNode.rgb.mul( transparentNode.a.oneMinus() ).add( transparentNode.rgb ), 1.0 );

	renderPipeline = new THREE.RenderPipeline( renderer );
	renderPipeline.outputNode = deferredNode;

	// gui

	params = {
		mode: 'deferred',
		animated: true
	};

	const gui = renderer.inspector.createParameters( 'Settings' );
	gui.add( params, 'mode', [ 'forward', 'deferred' ] ).onChange( ( value ) => {

		renderPipeline.outputNode = ( value === 'forward' ) ? forwardPass : deferredNode;
		renderPipeline.needsUpdate = true;

	} );
	gui.add( params, 'animated' );

	// controls

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 2;
	controls.maxDistance = 10;
	controls.target.set( 0, 0, - 0.2 );
	controls.update();

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function render() {

	timer.update();

	if ( params.animated ) {

		const delta = timer.getDelta();

		lightGroup.rotation.y += delta * 1.0;
		planesGroup.rotation.y -= delta * 0.5;

	}

	renderPipeline.render();

}

