async function init() {

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.01, 100 );
	camera.position.set( 0, 0.35, 3.2 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x07080f );

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.minDistance = 1.2;
	controls.maxDistance = 8;
	controls.target.set( 0, 0, 0 );
	controls.update();

	const gui = renderer.inspector.createParameters( 'Building' );
	gui.add( params, 'source', sourceNames ).name( 'Splat' ).onChange( async ( value ) => {

		await loadSplatSource( getSourceKeyByName( value ) );

	} );

	hitMarker = new THREE.Mesh(
		new THREE.SphereGeometry( 1, 16, 12 ),
		new THREE.MeshBasicMaterial( { color: 0xff0000, depthTest: false } )
	);
	hitMarker.visible = false;
	scene.add( hitMarker );

	await loadSplatSource( getSourceKeyByName( params.source ) );

	window.addEventListener( 'resize', onWindowResize );
	renderer.domElement.addEventListener( 'pointerdown', onPointerDown );
	renderer.domElement.addEventListener( 'click', onClick );

}

function onPointerDown( event ) {

	pointerDownX = event.clientX;
	pointerDownY = event.clientY;

}

function onClick( event ) {

	// check drag distance
	const dx = event.clientX - pointerDownX;
	const dy = event.clientY - pointerDownY;
	if ( Math.sqrt( dx * dx + dy * dy ) > CLICK_DRAG_THRESHOLD ) {

		return;

	}

	pointer.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	pointer.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

	raycaster.setFromCamera( pointer, camera );

	const hit = raycaster.intersectObject( splatRoot, true )[ 0 ];
	if ( hit ) {

		hitMarker.position.copy( hit.point );
		hitMarker.visible = true;

	} else {

		hitMarker.visible = false;

	}

}

async function loadSplatSource( sourceKey ) {

	const source = sources[ sourceKey ];
	const splatData = await new source.loader().loadAsync( source.url );

	disposeCurrentSplats();

	splats = new GaussianSplat( splatData, { autoSort: false } );
	splatRoot = splats;

	if ( source.rotation !== undefined ) splatRoot.rotation.copy( source.rotation );

	scene.add( splatRoot );

	fitCameraToSplats( splats, source );
	updateHitMarkerSize( splats );

	updateLicenseInfo( source );

}

function getWorldBoundingSphere( mesh ) {

	mesh.updateWorldMatrix( true, false );

	return mesh.splatGeometry.boundingSphere.clone().applyMatrix4( mesh.matrixWorld );

}

function updateHitMarkerSize( mesh ) {

	const sphere = getWorldBoundingSphere( mesh );
	hitMarker.scale.setScalar( Math.max( sphere.radius * HIT_MARKER_SIZE_RATIO, 0.0001 ) );

}

function updateLicenseInfo( source ) {

	const license = document.getElementById( 'license' );
	const credit = source.credit;

	if ( credit === undefined ) {

		license.innerHTML = '';
		return;

	}

	license.innerHTML = 'Model by <a href="' + credit.authorUrl + '" target="_blank" rel="noopener">' + credit.author + '</a>, ' +
		'via <a href="' + credit.source + '" target="_blank" rel="noopener">superspl.at</a>. ' +
		'Licensed under <a href="' + credit.licenseUrl + '" target="_blank" rel="noopener">' + credit.license + '</a>.';

}

function getSourceKeyByName( sourceName ) {

	return Object.keys( sources ).find( ( key ) => sources[ key ].name === sourceName );

}

function disposeCurrentSplats() {

	if ( splatRoot === undefined ) return;

	scene.remove( splatRoot );
	splats.geometry.dispose();
	splats.material.dispose();
	splats = undefined;
	splatRoot = undefined;

}

function fitCameraToSplats( mesh, source ) {

	const sphere = getWorldBoundingSphere( mesh );
	const radius = Math.max( sphere.radius, 0.01 );
	const distance = radius / Math.sin( THREE.MathUtils.degToRad( camera.fov ) * 0.5 );

	controls.minDistance = source.minDistance || radius * 1.1;
	controls.maxDistance = source.maxDistance || radius * 8;
	controls.target.copy( sphere.center ).add( source.cameraTarget || zeroVector );
	camera.position.copy( source.cameraPosition ).normalize().multiplyScalar( distance * 1.15 ).add( sphere.center );
	camera.near = Math.max( distance / 1000, 0.001 );
	camera.far = Math.max( distance * 10, 10 );

	camera.updateProjectionMatrix();
	controls.update();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	controls.update();

	if ( splats !== undefined ) {

		splats.updateSort( renderer, camera );

	}

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';
