function createStarGeometry() {

	const sections = [];

	for ( let i = 0; i <= 60; i ++ ) {

		const t = i / 60;

		const twist = t * Math.PI / 3;
		const scale = 1 - 0.35 * Math.sin( t * Math.PI );

		const points = [];

		for ( let j = 0; j < 96; j ++ ) {

