function createRibbonGeometry() {

	const sections = [];

	for ( let i = 0; i <= 120; i ++ ) {

		const t = i / 120;

		const angle = t * Math.PI * 2 * 2.5;
		const sin = Math.sin( angle );
		const cos = Math.cos( angle );

		sections.push( [
			new THREE.Vector3( 3 * sin, t * 7.5, 3 * cos ),
			new THREE.Vector3( 3 * sin, t * 7.5 + 2, 3 * cos )
		] );

