const params = {
	enabled: true,
	showProbes: false,
	probeSize: 0.2,
	boundsX: - 0.5,
	boundsY: 6,
	boundsZ: - 0.3,
	sizeX: 21,
	sizeY: 11,
	sizeZ: 9,
	countX: 10,
	countY: 7,
	countZ: 7,
	bounces: 1,
	lightAzimuth: - 75,
	lightElevation: 60,
	lightIntensity: 100.0,
	shadows: true
};

init();

async function init() {

	timer = new THREE.Timer();

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 1000 );
	camera.position.set( - 10.25, 4.99, 0.40 );
	camera.rotation.set( 1.6505, - 1.5008, 1.6507 );

	scene = new THREE.Scene();

	sky = new SkyMesh();
	sky.scale.setScalar( 450000 );
	sky.turbidity.value = 10;
	sky.rayleigh.value = 2;
	sky.mieCoefficient.value = 0.005;
	sky.mieDirectionalG.value = 0.8;
	sky.cloudSpeed.value = 0; // keep the clouds static, like the WebGL version
	sky.showSunDisc.value = false; // the sun is represented by the light
	scene.add( sky );

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	SunLight.registerNode( SunLightNode );
	renderer.setPixelRatio( Math.min( window.devicePixelRatio, 1.5 ) );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 1.0;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	controls = new FirstPersonControls( camera, renderer.domElement );
	controls.movementSpeed = 2.0;
	controls.lookSpeed = 0.2;

	const progressBar = document.getElementById( 'progressBar' );

	const manager = new THREE.LoadingManager();
	manager.onProgress = function ( url, loaded, total ) {

		progressBar.value = loaded / total * 100;

	};

	manager.onLoad = function () {

		progressBar.remove();

	};

	const loader = new GLTFLoader( manager );
	const modelURL = await getSponzaModelURL();
	const gltf = await loader.loadAsync( modelURL );
	const model = gltf.scene;
	const embeddedLights = [];

	model.traverse( ( child ) => {

		if ( child.isMesh ) {

			child.castShadow = true;
			child.receiveShadow = true;

		} else if ( child.isLight ) {

			embeddedLights.push( child );

		}

	} );

	for ( const light of embeddedLights ) {

		if ( light.parent ) light.parent.remove( light );

	}

	scene.add( model );

	_box.setFromObject( model );
	modelSize = _box.getSize( _size ).clone();
	probeFar = Math.max( modelSize.x, modelSize.y, modelSize.z ) * 2.0;

	sunLight = new SunLight( 0xfff2dc, 100.0 );
	sunLight.castShadow = true;
	sunLight.shadow.camera.far = 50;
	sunLight.shadow.mapSize.setScalar( 2048 );
	scene.add( sunLight );

	function updateLightPosition() {

		const elevation = THREE.MathUtils.degToRad( params.lightElevation );
		const azimuth = THREE.MathUtils.degToRad( params.lightAzimuth );

		sunLight.position.setFromSphericalCoords( 1, Math.PI / 2 - elevation, azimuth );
		sky.sunPosition.value.copy( sunLight.position );

	}

	updateLightPosition();

	const gui = renderer.inspector.createParameters( 'Light Probes' );
	gui.add( params, 'enabled' ).name( 'GI' ).onChange( ( value ) => {

		if ( probes ) probes.visible = value;

	} );

	gui.add( params, 'lightAzimuth', - 180, 180, 1 ).name( 'Light Azimuth' ).onChange( () => {

		updateLightPosition();
		resetProbeBake();

	} );
	gui.add( params, 'lightElevation', 5, 85, 1 ).name( 'Light Elevation' ).onChange( () => {

		updateLightPosition();
		resetProbeBake();

	} );
	gui.add( params, 'lightIntensity', 0, 100, 0.1 ).name( 'Light Intensity' ).onChange( ( value ) => {

		sunLight.intensity = value;
		resetProbeBake();

	} );
	gui.add( params, 'shadows' ).name( 'Shadows' ).onChange( ( value ) => {

		setShadowsEnabled( value );
		resetProbeBake();

	} );

	gui.add( params, 'countX', 2, 32, 1 ).name( 'Probes X' ).debounce( 250 ).onChange( createProbes );
	gui.add( params, 'countY', 2, 16, 1 ).name( 'Probes Y' ).debounce( 250 ).onChange( createProbes );
	gui.add( params, 'countZ', 2, 16, 1 ).name( 'Probes Z' ).debounce( 250 ).onChange( createProbes );
	gui.add( params, 'bounces', 0, 2, 1 ).name( 'Bounces' ).onChange( resetProbeBake );

	gui.add( params, 'showProbes' ).name( 'Show Probes' ).onChange( ( value ) => {

		if ( probesHelper ) probesHelper.visible = value;

	} );
	gui.add( params, 'probeSize', 0.05, 2.0, 0.05 ).name( 'Probe Size' ).onChange( ( value ) => {

		if ( probesHelper ) {

			scene.remove( probesHelper );
			probesHelper.dispose();
			probesHelper = new LightProbeGridHelper( probes, value );
			probesHelper.visible = params.showProbes;
			scene.add( probesHelper );

		}

	} );

	gui.add( { log: () => {

		console.log( 'position:', camera.position.x.toFixed( 2 ), camera.position.y.toFixed( 2 ), camera.position.z.toFixed( 2 ) );
		console.log( 'rotation:', camera.rotation.x.toFixed( 4 ), camera.rotation.y.toFixed( 4 ), camera.rotation.z.toFixed( 4 ) );

	} }, 'log' ).name( 'Log Camera' );

	setShadowsEnabled( params.shadows );
	createProbes();

	window.addEventListener( 'resize', onWindowResize );

}

function createProbes() {

	if ( probesHelper ) {

		scene.remove( probesHelper );
		probesHelper.dispose();
		probesHelper = null;

	}

	if ( probes ) {

		scene.remove( probes );
		probes.dispose();

	}

	probes = new LightProbeGrid(
		params.sizeX, params.sizeY, params.sizeZ,
		params.countX, params.countY, params.countZ
	);
	probes.position.set( params.boundsX, params.boundsY, params.boundsZ );
	probes.visible = params.enabled;
	scene.add( probes );

	resetProbeBake();

}

function resetProbeBake() {

	bakeIndex = 0;
	bakePass = 0;

}

function updateProbes() {

	if ( probes === null || bakePass > params.bounces ) return;

	const resolution = probes.resolution;
	const totalProbes = resolution.x * resolution.y * resolution.z;
	const count = Math.min( 4, totalProbes - bakeIndex );

	// Keep the helper spheres out of the cubemap captures.
	if ( probesHelper ) probesHelper.visible = false;

	try {

		// Publish a few probes per frame, finishing each pass before the next bounce.
		probes.bake( renderer, scene, {
			cubemapSize: 32,
			near: 0.05,
			far: probeFar,
			start: bakeIndex,
			count,
			pass: bakePass
		} );

	} finally {

		if ( probesHelper ) probesHelper.visible = params.showProbes;

	}

	if ( probesHelper === null ) {

		probesHelper = new LightProbeGridHelper( probes, params.probeSize );
		probesHelper.visible = params.showProbes;
		scene.add( probesHelper );

	}

	bakeIndex += count;

	if ( bakeIndex === totalProbes ) {

		bakeIndex = 0;
		bakePass ++;

	}

}

async function getSponzaModelURL() {

	const response = await fetch( MODEL_INDEX_URL );
	const models = await response.json();
	const sponzaInfo = models.find( ( model ) => model.name === 'Sponza' );

	if ( ! sponzaInfo ) {

		throw new Error( 'Sponza entry was not found in the glTF sample model index.' );

	}

	const variants = sponzaInfo.variants || {};
	const variantName = variants[ 'glTF-Binary' ] || variants[ 'glTF' ] || variants[ 'glTF-Embedded' ] || Object.values( variants )[ 0 ];

	if ( ! variantName ) {

		throw new Error( 'Sponza has no supported glTF variant in the model index.' );

	}

	const variantFolder = variantName.endsWith( '.glb' ) ? 'glTF-Binary' : 'glTF';
	return `${ SAMPLE_ASSETS_BASE_URL }${ sponzaInfo.name }/${ variantFolder }/${ variantName }`;

}

function setShadowsEnabled( enabled ) {

	if ( ! renderer || ! sunLight ) return;

	renderer.shadowMap.enabled = enabled;
	sunLight.castShadow = enabled;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate( timestamp ) {

	timer.update( timestamp );
	controls.update( timer.getDelta() );
	updateProbes();
	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';
import { instancedBufferAttribute, pass, uniform, vec3, float, mix, step, renderOutput } from 'three/tsl';
import { fxaa } from 'three/addons/tsl/display/FXAANode.js';

import { ClusteredLighting } from 'three/addons/lighting/ClusteredLighting.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

import WebGPU from 'three/addons/capabilities/WebGPU.js';

const GRID = 30; // GRID x GRID spheres
const SPACING = 5;
const RADIUS = 0.5;
const WAVE_HEIGHT = 4;
const BIG_RADIUS = 6;
const BASE_POWER = 45;

let camera, scene, renderer, controls, spheresMesh, lighting;
let renderPipeline, scenePass, clusterInfluence, debugZSliceNode;

const balls = [];
const dummy = new THREE.Object3D();

const params = {
	intensity: 1,
	animate: true
};

init();

async function init() {

	if ( WebGPU.isAvailable() === false ) {

		document.body.appendChild( WebGPU.getErrorMessage() );

		throw new Error( 'No WebGPU support' );

	}

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 1, 200 );
	camera.position.set( 36, 18, 36 );

	scene = new THREE.Scene();

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.toneMapping = THREE.NeutralToneMapping;
	renderer.toneMappingExposure = 1;
	lighting = new ClusteredLighting();
	renderer.lighting = lighting; // set lighting system
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	// ground

	const ground = new THREE.Mesh(
		new THREE.PlaneGeometry( 1000, 1000 ).rotateX( - Math.PI / 2 ),
		new THREE.MeshPhongNodeMaterial( { color: 0x2a2a2a, shininess: 80 } )
	);
	scene.add( ground );

	// four big spheres in the middle for the surrounding lights to play across

	const bigPositions = [
		new THREE.Vector3( - 9, BIG_RADIUS, - 9 ),
		new THREE.Vector3( 9, BIG_RADIUS, - 9 ),
		new THREE.Vector3( - 9, BIG_RADIUS, 9 ),
		new THREE.Vector3( 9, BIG_RADIUS, 9 )
	];

	const bigGeometry = new THREE.SphereGeometry( BIG_RADIUS, 64, 32 );
	const bigMaterial = new THREE.MeshPhongNodeMaterial( { color: 0xdddddd, shininess: 80 } );

	for ( const position of bigPositions ) {

		const bigSphere = new THREE.Mesh( bigGeometry, bigMaterial );
		bigSphere.position.copy( position );
		scene.add( bigSphere );

	}

	// a grid of coloured spheres drawn as a single InstancedMesh; each is
	// unlit in its own colour and holds a matching point light at its centre

	const maxCount = GRID * GRID;
	const colorAttribute = new THREE.InstancedBufferAttribute( new Float32Array( maxCount * 3 ), 3 );

	const material = new THREE.MeshBasicNodeMaterial();
	material.colorNode = instancedBufferAttribute( colorAttribute );

	spheresMesh = new THREE.InstancedMesh( new THREE.SphereGeometry( RADIUS, 32, 16 ), material, maxCount );
	spheresMesh.instanceMatrix.setUsage( THREE.DynamicDrawUsage );
	scene.add( spheresMesh );

	const color = new THREE.Color();
	const span = ( GRID - 1 ) * SPACING;

	let i = 0;

	for ( let ix = 0; ix < GRID; ix ++ ) {

		for ( let iz = 0; iz < GRID; iz ++ ) {

			const x = ix * SPACING - span / 2;
			const z = iz * SPACING - span / 2;

			// leave a clearing where a big sphere sits
			if ( bigPositions.some( ( position ) => Math.hypot( x - position.x, z - position.z ) < BIG_RADIUS + 1 ) ) continue;

			const phase = ( ix + iz ) * 0.5;

			dummy.position.set( x, RADIUS, z );
			dummy.updateMatrix();
			spheresMesh.setMatrixAt( i, dummy.matrix );

			color.setHSL( ( ix * GRID + iz ) / ( GRID * GRID ), 1.0, 0.5 );
			colorAttribute.setXYZ( i, color.r, color.g, color.b );

			const light = new THREE.PointLight( color, 1, 9 );
			light.power = BASE_POWER;
			light.position.set( x, RADIUS, z );
			scene.add( light );

			balls.push( { x, z, phase, light } );

			i ++;

		}

	}

	spheresMesh.count = i;

	// controls

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.target.set( 0, 6, 0 );
	controls.maxPolarAngle = Math.PI * 0.49;
	controls.minDistance = 4;
	controls.maxDistance = 400;
	controls.update();

	// post-processing: a debug overlay that tints each screen tile by how many
	// lights its cluster holds, for the selected depth slice

	scenePass = pass( scene, camera );
	clusterInfluence = uniform( 0 );

	debugZSliceNode = uniform( 20, 'int' );

	renderPipeline = new THREE.RenderPipeline( renderer );
	renderPipeline.outputColorTransform = false;

	updatePostProcessing();

	// gui

	const gui = renderer.inspector.createParameters( 'Settings' );
	gui.add( params, 'intensity', 0, 3 ).name( 'light intensity' ).onChange( ( value ) => {

		for ( const ball of balls ) ball.light.power = BASE_POWER * value;

	} );
	gui.add( params, 'animate' );
	gui.add( clusterInfluence, 'value', 0, .7 ).name( 'lights per tile' );
	gui.add( debugZSliceNode, 'value', 0, lighting.zSlices - 1, 1 ).name( 'z-slice' );

	// events

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	updatePostProcessing();

}

function updatePostProcessing() {

	// the overlay samples the cluster grid at the current resolution, so it
	// is rebuilt whenever the renderer size changes

	const lightingNode = lighting.getNode( scene ).setSize( window.innerWidth * window.devicePixelRatio, window.innerHeight * window.devicePixelRatio );

	// map the light count of each cluster ( 0 … maxLightsPerCluster ) to a
	// blue → green → red gradient
	const lightCount = lightingNode.getClusterLightCount( debugZSliceNode );
	const heatmap = float( lightCount ).div( float( lighting.maxLightsPerCluster ) );

	let heatColor = mix( vec3( 0.0, 0.0, 1.0 ), vec3( 0.0, 1.0, 0.0 ), heatmap.mul( 2.0 ).saturate() );
	heatColor = mix( heatColor, vec3( 1.0, 0.0, 0.0 ), heatmap.sub( 0.5 ).mul( 2.0 ).saturate() );

	// blend the heatmap over the scene by the slider amount; step() keeps
	// empty clusters transparent
	const finalInfluence = clusterInfluence.mul( step( 0.0001, heatmap ) );

	const outputPass = renderOutput( mix( scenePass, heatColor, finalInfluence ) );

	renderPipeline.outputNode = fxaa( outputPass );
	renderPipeline.needsUpdate = true;

}

function animate() {

	if ( params.animate === true ) {

		const time = performance.now() / 1000;

		for ( let i = 0; i < balls.length; i ++ ) {

			const ball = balls[ i ];
			const y = RADIUS + ( 0.5 + 0.5 * Math.sin( time * 1.5 + ball.phase ) ) * WAVE_HEIGHT;

			dummy.position.set( ball.x, y, ball.z );
			dummy.updateMatrix();
			spheresMesh.setMatrixAt( i, dummy.matrix );

			ball.light.position.y = y;

		}

		spheresMesh.instanceMatrix.needsUpdate = true;

	}

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { color, lights } from 'three/tsl';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

class CustomLightingModel extends THREE.LightingModel {

	direct( { lightColor, reflectedLight }/*, builder */ ) {

		reflectedLight.directDiffuse.addAssign( lightColor );

	}

}

let camera, scene, renderer;

let light1, light2, light3;

init();

function init() {

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 0.1, 10 );
	camera.position.z = 1.5;

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x000000 );

	// lights

	const sphereGeometry = new THREE.SphereGeometry( 0.02, 16, 8 );

	const addLight = ( hexColor ) => {

		const material = new THREE.NodeMaterial();
		material.colorNode = color( hexColor );
		material.lightsNode = lights(); // ignore scene lights

		const mesh = new THREE.Mesh( sphereGeometry, material );

		const light = new THREE.PointLight( hexColor, 0.1, 1 );
		light.add( mesh );

		scene.add( light );

		return light;

	};

	light1 = addLight( 0xffaa00 );
	light2 = addLight( 0x0040ff );
	light3 = addLight( 0x80ff80 );

	//light nodes ( selective lights )

	const allLightsNode = lights( [ light1, light2, light3 ] );

	// points

	const points = [];

	for ( let i = 0; i < 500000; i ++ ) {

		const point = new THREE.Vector3().random().subScalar( 0.5 ).multiplyScalar( 3 );
		points.push( point );

	}

	const geometryPoints = new THREE.BufferGeometry().setFromPoints( points );
	const materialPoints = new THREE.PointsNodeMaterial();

	// custom lighting model

	const lightingModel = new CustomLightingModel();
	const lightingModelContext = allLightsNode.context( { lightingModel } );

	materialPoints.lightsNode = lightingModelContext;

	//

	const pointCloud = new THREE.Points( geometryPoints, materialPoints );
	scene.add( pointCloud );

	//

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	// controls

	const controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 0;
	controls.maxDistance = 4;

	// events

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	const time = Date.now() * 0.001;
	const scale = .5;

	light1.position.x = Math.sin( time * 0.7 ) * scale;
	light1.position.y = Math.cos( time * 0.5 ) * scale;
	light1.position.z = Math.cos( time * 0.3 ) * scale;

	light2.position.x = Math.cos( time * 0.3 ) * scale;
	light2.position.y = Math.sin( time * 0.5 ) * scale;
	light2.position.z = Math.sin( time * 0.7 ) * scale;

	light3.position.x = Math.sin( time * 0.7 ) * scale;
	light3.position.y = Math.cos( time * 0.3 ) * scale;
	light3.position.z = Math.sin( time * 0.5 ) * scale;

	scene.rotation.y = time * 0.1;

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { DynamicLighting } from 'three/addons/lighting/DynamicLighting.js';
import { Inspector } from 'three/addons/inspector/Inspector.js';
import Stats from 'three/addons/libs/stats.module.js';

let camera, scene, renderer, controls, timer, stats;

const pointLights = [];
let autoAddInterval = null;

const params = {
	dynamic: true,
	autoAdd: false,
	lightCount: 2,
	addLight() {

		addLight();

	},
	removeLight() {

		removeLight();

	},
	removeAll() {

		removeAllLights();

	}
};

init();

function init() {

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.1, 200 );
	camera.position.set( 0, 15, 30 );

	scene = new THREE.Scene();

	timer = new THREE.Timer();
	timer.connect( document );

	// Stats

	stats = new Stats();
	document.body.appendChild( stats.dom );

	// Floor

	const floorGeometry = new THREE.PlaneGeometry( 120, 120 );
	const floorMaterial = new THREE.MeshStandardMaterial( { color: 0x444444, roughness: 0.8 } );
	const floor = new THREE.Mesh( floorGeometry, floorMaterial );
	floor.rotation.x = - Math.PI / 2;
	scene.add( floor );

	// Shared geometries

	const sphereGeometry = new THREE.SphereGeometry( 0.8, 128, 128 );
	const boxGeometry = new THREE.BoxGeometry( 1.2, 1.2, 1.2, 64, 64, 64 );
	const torusGeometry = new THREE.TorusGeometry( 0.6, 0.25, 128, 128 );
	const cylinderGeometry = new THREE.CylinderGeometry( 0.5, 0.5, 1.4, 128, 64 );
	const coneGeometry = new THREE.ConeGeometry( 0.6, 1.4, 128, 64 );

	const geometries = [ sphereGeometry, boxGeometry, torusGeometry, cylinderGeometry, coneGeometry ];

	// 100 meshes — first 50 with unique PBR materials, remaining 50 reuse them

	const uniqueMaterials = [];

	for ( let i = 0; i < 50; i ++ ) {

		const material = new THREE.MeshStandardMaterial( {
			color: new THREE.Color().setHSL( i / 50, 0.6 + Math.random() * 0.4, 0.35 + Math.random() * 0.3 ),
			roughness: Math.random(),
			metalness: Math.random(),
		} );
		material.name = 'Standard_' + i;

		uniqueMaterials.push( material );

	}

	const meshesPerRing = 10;

	for ( let i = 0; i < 100; i ++ ) {

		const material = i < 50 ? uniqueMaterials[ i ] : uniqueMaterials[ i - 50 ];
		const geometry = geometries[ i % geometries.length ];
		const mesh = new THREE.Mesh( geometry, material );

		const ring = Math.floor( i / meshesPerRing );
		const indexInRing = i % meshesPerRing;
		const angle = ( indexInRing / meshesPerRing ) * Math.PI * 2 + ring * 0.3;
		const radius = 6 + ring * 4;

		mesh.position.set(
			Math.cos( angle ) * radius,
			0.7 + Math.random() * 2,
			Math.sin( angle ) * radius
		);

		mesh.rotation.set(
			Math.random() * Math.PI,
			Math.random() * Math.PI,
			0
		);

		scene.add( mesh );

	}

	// Center sphere

	const centerMaterial = new THREE.MeshStandardMaterial( { color: 0xffffff, roughness: 0.1, metalness: 0.9 } );
	const centerSphere = new THREE.Mesh( new THREE.SphereGeometry( 2, 128, 128 ), centerMaterial );
	centerSphere.position.y = 2;
	scene.add( centerSphere );

	// Ambient light

	scene.add( new THREE.AmbientLight( 0x404040, 0.5 ) );

	// Start with a couple point lights

	addLight();
	addLight();

	// Renderer

	createRenderer();

	// Inspector GUI

	window.addEventListener( 'resize', onWindowResize );

}

function createRenderer() {

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	if ( params.dynamic ) renderer.lighting = new DynamicLighting();

	// Inspector GUI

	const gui = renderer.inspector.createParameters( 'Dynamic Lights' );

	gui.add( params, 'dynamic' ).name( 'dynamic mode' ).onChange( () => {

		renderer.dispose();
		document.body.removeChild( renderer.domElement );
		clearInterval( autoAddInterval );
		autoAddInterval = null;
		params.autoAdd = false;
		createRenderer();

	} );

	gui.add( params, 'autoAdd' ).name( 'auto-add lights' ).onChange( ( value ) => {

		if ( value ) {

			autoAddInterval = setInterval( () => {

				addLight();

			}, 500 );

		} else {

			clearInterval( autoAddInterval );
			autoAddInterval = null;

		}

	} );

	gui.add( params, 'addLight' ).name( 'add light' );
	gui.add( params, 'removeLight' ).name( 'remove light' );
	gui.add( params, 'removeAll' ).name( 'remove all lights' );
	gui.add( params, 'lightCount' ).name( 'point lights' ).listen();

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.target.set( 0, 2, 0 );
	controls.update();

}

function addLight() {

	const color = new THREE.Color().setHSL( Math.random(), 0.8, 0.5 );
	const light = new THREE.PointLight( color, 1000 );

	const angle = Math.random() * Math.PI * 2;
	const radius = 5 + Math.random() * 20;
	light.position.set(
		Math.cos( angle ) * radius,
		1 + Math.random() * 6,
		Math.sin( angle ) * radius
	);

	light.userData.angle = angle;
	light.userData.radius = radius;
	light.userData.speed = 0.2 + Math.random() * 0.8;
	light.userData.baseY = light.position.y;

	// Visual indicator
	const sphere = new THREE.Mesh(
		new THREE.SphereGeometry( 0.15, 8, 8 ),
		new THREE.MeshBasicMaterial( { color: color } )
	);
	light.add( sphere );

	scene.add( light );
	pointLights.push( light );

	params.lightCount = pointLights.length;

}

function removeLight() {

	if ( pointLights.length === 0 ) return;

	const light = pointLights.pop();
	scene.remove( light );
	light.dispose();

	params.lightCount = pointLights.length;

}

function removeAllLights() {

	while ( pointLights.length > 0 ) {

		const light = pointLights.pop();
		scene.remove( light );
		light.dispose();

	}

	params.lightCount = 0;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	const time = timer.getElapsed();

	controls.update();

	// Animate lights

	for ( let i = 0; i < pointLights.length; i ++ ) {

		const light = pointLights[ i ];
		const d = light.userData;
		const t = time * d.speed + d.angle;

		light.position.x = Math.cos( t ) * d.radius;
		light.position.z = Math.sin( t ) * d.radius;
		light.position.y = d.baseY + Math.sin( t * 2 ) * 0.5;

	}

	renderer.render( scene, camera );

	stats.update();

}

