import { SkyMesh } from 'three/addons/objects/SkyMesh.js';
import { SunLight } from 'three/addons/lights/SunLight.js';
import { SunLightNode } from 'three/addons/lights/SunLightNode.js';

let renderer, scene, camera, controls, timer, sunLight, sky, sceneEnv, pmremGenerator, renderTarget;

const params = {
	showCascades: false,
	far: 1000,
	resolution: 2048,
	azimuth: 135,
	elevation: 10
};

const _sunDay = new THREE.Color( 0xfff2e3 ), _sunDusk = new THREE.Color( 0xff8a3d );
const _fogDay = new THREE.Color( 0xd8e2ea ), _fogDusk = new THREE.Color( 0xd9a273 );

// tints each fragment by its cascade, using the data of the built-in sun shadow node

function tintCascades() {

	const cascadeData = reference( '_cascadeData', 'vec4', sunLight.shadow );
	const viewDepth = positionView.z.negate();

	let cascade = float( 0 );

	for ( let i = 0; i < sunLight.shadow.getViewportCount(); i ++ ) {

		cascade = cascade.add( step( cascadeData.element( i ).y, viewDepth ) );

	}

	const tint = cos( cascade.mul( 1.2 ).add( vec3( 0, 4.2, 2.1 ) ) ).mul( 0.3 ).add( 0.7 );

	// tint before the fog by wrapping the scene fog

	const fogColor = reference( 'color', 'color', scene.fog );
	const fogFactor = rangeFogFactor( reference( 'near', 'float', scene.fog ), reference( 'far', 'float', scene.fog ) );

	return vec4( fogFactor.mix( output.rgb.mul( tint ), fogColor ), output.a );

}

init();

function updateSun() {

	sunLight.position.setFromSphericalCoords( 1, THREE.MathUtils.degToRad( 90 - params.elevation ), THREE.MathUtils.degToRad( params.azimuth ) );

	// the sun light warms up and fades towards the horizon

	const daylight = Math.min( 1, params.elevation / 30 );

	sunLight.color.lerpColors( _sunDusk, _sunDay, daylight );
	sunLight.intensity = 3 + daylight * 2;

	scene.fog.color.lerpColors( _fogDusk, _fogDay, daylight );

	sky.sunPosition.value.copy( sunLight.position );

	// light the scene with the sky itself

	if ( renderTarget !== undefined ) renderTarget.dispose();

	sceneEnv.add( sky );
	renderTarget = pmremGenerator.fromScene( sceneEnv );
	scene.add( sky );

	scene.environment = renderTarget.texture;

}

function init() {

	scene = new THREE.Scene();
	scene.fog = new THREE.Fog( 0x000000, 500, 4000 );
	scene.environmentIntensity = 0.5;

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.5, 5000 );
	camera.position.set( 60, 8, 0 );
	camera.lookAt( - 60, 8, 0 );

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	SunLight.registerNode( SunLightNode );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 0.6;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	controls = new FirstPersonControls( camera, renderer.domElement );
	controls.movementSpeed = 40;
	controls.lookSpeed = 0.2;

	timer = new THREE.Timer();
	pmremGenerator = new THREE.PMREMGenerator( renderer );
	sceneEnv = new THREE.Scene();

	// sky and sun

	sky = new SkyMesh();
	sky.scale.setScalar( 9000 );
	scene.add( sky );

	sky.turbidity.value = 3;
	sky.rayleigh.value = 2;
	sky.cloudSpeed.value = 0; // keep the clouds static, like the WebGL version
	sky.showSunDisc.value = false; // the sun is represented by the light

	sunLight = new SunLight();
	sunLight.castShadow = true;
	sunLight.shadow.camera.far = params.far; // maximum shadow distance
	sunLight.shadow.mapSize.setScalar( params.resolution );
	sunLight.shadow.normalBias = 0.05;
	scene.add( sunLight );

	renderer.init().then( updateSun );

	// ground

	const ground = new THREE.Mesh( new THREE.PlaneGeometry( 10000, 10000 ), new THREE.MeshStandardMaterial( { color: 0xa39f8e } ) );
	ground.rotation.x = - Math.PI / 2;
	ground.receiveShadow = true;
	scene.add( ground );

	const dummy = new THREE.Object3D();

	// an avenue of thin posts shows the shadow resolution from up close
	// all the way down to the shadow distance

	const posts = new THREE.InstancedMesh( new THREE.BoxGeometry( 1, 10, 1 ), new THREE.MeshStandardMaterial( { color: 0x475161 } ), 120 );
	posts.castShadow = true;
	posts.receiveShadow = true;
	scene.add( posts );

	for ( let i = 0; i < 60; i ++ ) {

		for ( const side of [ - 1, 1 ] ) {

			dummy.position.set( 30 - i * 17, 5, side * 13 );
			dummy.updateMatrix();
			posts.setMatrixAt( i * 2 + ( side + 1 ) / 2, dummy.matrix );

		}

	}

	// towers for large shadows in the distance

	const towers = new THREE.InstancedMesh( new THREE.BoxGeometry( 10, 1, 10 ), new THREE.MeshStandardMaterial(), 60 );
	towers.castShadow = true;
	towers.receiveShadow = true;
	scene.add( towers );

	const towerColors = [ new THREE.Color( 0x08d9d6 ), new THREE.Color( 0xff2e63 ) ];

	THREE.MathUtils.seededRandom( 6 );

	for ( let i = 0; i < 30; i ++ ) {

		for ( const side of [ - 1, 1 ] ) {

			const height = 20 + THREE.MathUtils.seededRandom() * 40;

			dummy.position.set( - 40 - i * 32 - THREE.MathUtils.seededRandom() * 10, height / 2, side * ( 38 + THREE.MathUtils.seededRandom() * 55 ) );
			dummy.scale.y = height;
			dummy.updateMatrix();

			const index = i * 2 + ( side + 1 ) / 2;
			towers.setMatrixAt( index, dummy.matrix );
			towers.setColorAt( index, towerColors[ ( i + ( side + 1 ) / 2 ) % 2 ] );

		}

	}

	// gui

	const gui = renderer.inspector.createParameters( 'Sun Light' );

	gui.add( params, 'showCascades' ).name( 'show cascades' ).onChange( function ( value ) {

		scene.fogNode = value ? tintCascades() : null;

	} );

	gui.add( params, 'far', 100, 3000 ).step( 1 ).name( 'shadow far' ).onChange( function ( value ) {

		sunLight.shadow.camera.far = value;

	} );

	gui.add( params, 'resolution', [ 256, 512, 1024, 2048, 4096 ] ).name( 'shadow resolution' ).onChange( function ( value ) {

		sunLight.shadow.mapSize.setScalar( value );

	} );

	gui.add( params, 'azimuth', 0, 360 ).onChange( updateSun );
	gui.add( params, 'elevation', 5, 80 ).onChange( updateSun );

	window.addEventListener( 'resize', function () {

		camera.aspect = window.innerWidth / window.innerHeight;
		camera.updateProjectionMatrix();

		renderer.setSize( window.innerWidth, window.innerHeight );
		controls.handleResize();

	} );

}

function animate() {

	timer.update();

	controls.update( timer.getDelta() );

	renderer.render( scene, camera );

}

import * as THREE from 'three/webgpu';
import { color } from 'three/tsl';

import Stats from 'three/addons/libs/stats.module.js';

import { GUI } from 'three/addons/libs/lil-gui.module.min.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { Line2 } from 'three/addons/lines/webgpu/Line2.js';
import { LineGeometry } from 'three/addons/lines/LineGeometry.js';
import * as GeometryUtils from 'three/addons/utils/GeometryUtils.js';

let line, renderer, scene, camera, camera2, controls, backgroundNode;
let line1;
let matLine, matLineBasic, matLineDashed;
let stats;
let gui;

// viewport
let insetWidth;
let insetHeight;

init();

function init() {

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setClearColor( 0x000000 );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( - 40, 0, 60 );

	camera2 = new THREE.PerspectiveCamera( 40, 1, 1, 1000 );
	camera2.position.copy( camera.position );

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.minDistance = 10;
	controls.maxDistance = 500;

	backgroundNode = color( 0x222222 );

	// Position and THREE.Color Data

	const positions = [];
	const colors = [];

	const points = GeometryUtils.hilbert3D( new THREE.Vector3( 0, 0, 0 ), 20.0, 1, 0, 1, 2, 3, 4, 5, 6, 7 );

	const spline = new THREE.CatmullRomCurve3( points );
	const divisions = Math.round( 12 * points.length );
	const point = new THREE.Vector3();
	const lineColor = new THREE.Color();

	for ( let i = 0, l = divisions; i < l; i ++ ) {

		const t = i / l;

		spline.getPoint( t, point );
		positions.push( point.x, point.y, point.z );

		lineColor.setHSL( t, 1.0, 0.5, THREE.SRGBColorSpace );
		colors.push( lineColor.r, lineColor.g, lineColor.b );

	}


	// Line2 ( LineGeometry, LineMaterial )

	const geometry = new LineGeometry();
	geometry.setPositions( positions );
	geometry.setColors( colors );

	matLine = new THREE.Line2NodeMaterial( {

		color: 0xffffff,
		linewidth: 5, // in world units with size attenuation, pixels otherwise
		vertexColors: true,
		dashed: false,
		alphaToCoverage: false,

	} );

	line = new Line2( geometry, matLine );
	line.computeLineDistances();
	line.scale.set( 1, 1, 1 );
	scene.add( line );


	// THREE.Line ( THREE.BufferGeometry, THREE.LineBasicNodeMaterial ) - rendered with gl.LINE_STRIP

	const geo = new THREE.BufferGeometry();
	geo.setAttribute( 'position', new THREE.Float32BufferAttribute( positions, 3 ) );
	geo.setAttribute( 'color', new THREE.Float32BufferAttribute( colors, 3 ) );

	matLineBasic = new THREE.LineBasicNodeMaterial( { vertexColors: true } );
	matLineDashed = new THREE.LineDashedNodeMaterial( { vertexColors: true, scale: 2, dashSize: 1, gapSize: 1 } );

	line1 = new THREE.Line( geo, matLineBasic );
	line1.computeLineDistances();
	line1.visible = false;
	scene.add( line1 );

	//

	window.addEventListener( 'resize', onWindowResize );
	onWindowResize();

	stats = new Stats();
	document.body.appendChild( stats.dom );

	initGui();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	insetWidth = window.innerHeight / 4; // square
	insetHeight = window.innerHeight / 4;

	camera2.aspect = insetWidth / insetHeight;
	camera2.updateProjectionMatrix();

}

function animate() {

	stats.update();

	// main scene

	renderer.setClearColor( 0x000000 );

	renderer.setViewport( 0, 0, window.innerWidth, window.innerHeight );

	controls.update();

	renderer.autoClear = true;

	scene.backgroundNode = null;
	renderer.render( scene, camera );

	// inset scene

	const posY = window.innerHeight - insetHeight - 20;

	renderer.clearDepth(); // important!

	renderer.setScissorTest( true );

	renderer.setScissor( 20, posY, insetWidth, insetHeight );

	renderer.setViewport( 20, posY, insetWidth, insetHeight );

	camera2.position.copy( camera.position );
	camera2.quaternion.copy( camera.quaternion );

	renderer.autoClear = false;

	scene.backgroundNode = backgroundNode;
	renderer.render( scene, camera2 );

	renderer.setScissorTest( false );

}

//

function initGui() {

	gui = new GUI();

	const param = {
		'line type': 0,
		'world units': false,
		'width': 10,
		'alphaToCoverage': false,
		'dashed': false,
		'dash offset': 0,
		'dash scale': 1,
		'dash / gap': 1
	};

	gui.add( param, 'line type', { 'LineGeometry': 0, '"line-strip"': 1 } ).onChange( function ( val ) {

		switch ( val ) {

			case 0:
				line.visible = true;

				line1.visible = false;

				break;

			case 1:
				line.visible = false;

				line1.visible = true;

				break;

		}

	} );

	gui.add( param, 'world units' ).onChange( function ( val ) {

		matLine.worldUnits = val;
		matLine.needsUpdate = true;

		if ( val ) {

			widthController.name( 'width (world units)' ).min( 0.1 ).max( 0.5 ).setValue( 0.5 );

		} else {

			widthController.name( 'width (pixels)' ).min( 1 ).max( 10 ).setValue( 10 );
		}

	} );

	const widthController = gui.add( param, 'width', 1, 10 ).name( 'width (pixels)' ).onChange( function ( val ) {

		matLine.linewidth = val;

	} );

	gui.add( param, 'alphaToCoverage' ).onChange( function ( val ) {

		matLine.alphaToCoverage = val;

	} );

	gui.add( param, 'dashed' ).onChange( function ( val ) {

		matLine.dashed = val;
		line1.material = val ? matLineDashed : matLineBasic;

	} );

	gui.add( param, 'dash scale', 0.5, 2, 0.1 ).onChange( function ( val ) {

		matLine.scale = val;
		matLineDashed.scale = val;

	} );

	gui.add( param, 'dash offset', 0, 5, 0.1 ).onChange( function ( val ) {

		matLine.dashOffset = val;
		matLineDashed.dashOffset = val;

	} );

	gui.add( param, 'dash / gap', { '2 : 1': 0, '1 : 1': 1, '1 : 2': 2 } ).onChange( function ( val ) {

		switch ( val ) {

			case 0:
				matLine.dashSize = 2;
				matLine.gapSize = 1;

				matLineDashed.dashSize = 2;
				matLineDashed.gapSize = 1;

				break;

			case 1:
				matLine.dashSize = 1;
				matLine.gapSize = 1;

				matLineDashed.dashSize = 1;
				matLineDashed.gapSize = 1;

				break;

			case 2:
				matLine.dashSize = 1;
				matLine.gapSize = 2;

				matLineDashed.dashSize = 1;
				matLineDashed.gapSize = 2;

				break;

		}

	} );

}

import * as THREE from 'three/webgpu';

import { Inspector } from 'three/addons/inspector/Inspector.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { LineSegments2 } from 'three/addons/lines/webgpu/LineSegments2.js';
import { LineSegmentsGeometry } from 'three/addons/lines/LineSegmentsGeometry.js';
import { Line2 } from 'three/addons/lines/webgpu/Line2.js';
import { LineGeometry } from 'three/addons/lines/LineGeometry.js';

//

let line, thresholdLine, segments, thresholdSegments;
let renderer, scene, camera, controls;
let sphereInter, sphereOnLine;
let gui;
let timer;

const color = new THREE.Color();

const pointer = new THREE.Vector2( Infinity, Infinity );

const raycaster = new THREE.Raycaster();

raycaster.params.Line2 = {};
raycaster.params.Line2.threshold = 0;

const matLine = new THREE.Line2NodeMaterial( {

	color: 0xffffff,
	linewidth: 1, // in world units with size attenuation, pixels otherwise
	worldUnits: true,
	vertexColors: true,

	alphaToCoverage: true,

} );

const matThresholdLine = new THREE.Line2NodeMaterial( {

	color: 0xffffff,
	linewidth: matLine.linewidth, // in world units with size attenuation, pixels otherwise
	worldUnits: true,
	// vertexColors: true,
	transparent: true,
	opacity: 0.2,
	depthTest: false,
	visible: false,

} );

const params = {

	'line type': 1,
	'world units': matLine.worldUnits,
	'visualize threshold': matThresholdLine.visible,
	'width': matLine.linewidth,
	'alphaToCoverage': matLine.alphaToCoverage,
	'threshold': raycaster.params.Line2.threshold,
	'translation': 0,
	'animate': true

};

init();

function init() {

	timer = new THREE.Timer();
	timer.connect( document );

	renderer = new THREE.WebGPURenderer( { antialias: true, alpha: true, trackTimestamp: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setClearColor( 0x000000 );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( - 40, 0, 60 );

	controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 10;
	controls.maxDistance = 500;

	const sphereGeometry = new THREE.SphereGeometry( 0.25, 8, 4 );
	const sphereInterMaterial = new THREE.MeshBasicMaterial( { color: 0xff0000, depthTest: false } );
	const sphereOnLineMaterial = new THREE.MeshBasicMaterial( { color: 0x00ff00, depthTest: false } );

	sphereInter = new THREE.Mesh( sphereGeometry, sphereInterMaterial );
	sphereOnLine = new THREE.Mesh( sphereGeometry, sphereOnLineMaterial );
	sphereInter.visible = false;
	sphereOnLine.visible = false;
	sphereInter.renderOrder = 10;
	sphereOnLine.renderOrder = 10;
	scene.add( sphereInter );
	scene.add( sphereOnLine );

	// Position and THREE.Color Data

	const positions = [];
	const colors = [];
	const points = [];
	for ( let i = - 50; i < 50; i ++ ) {

		const t = i / 3;
		points.push( new THREE.Vector3( t * Math.sin( 2 * t ), t, t * Math.cos( 2 * t ) ) );

	}

	const spline = new THREE.CatmullRomCurve3( points );
	const divisions = Math.round( 3 * points.length );
	const point = new THREE.Vector3();
	const color = new THREE.Color();

	for ( let i = 0, l = divisions; i < l; i ++ ) {

		const t = i / l;

		spline.getPoint( t, point );
		positions.push( point.x, point.y, point.z );

		color.setHSL( t, 1.0, 0.5, THREE.SRGBColorSpace );
		colors.push( color.r, color.g, color.b );

	}

	const lineGeometry = new LineGeometry();
	lineGeometry.setPositions( positions );
	lineGeometry.setColors( colors );

	const segmentsGeometry = new LineSegmentsGeometry();
	segmentsGeometry.setPositions( positions );
	segmentsGeometry.setColors( colors );

	segments = new LineSegments2( segmentsGeometry, matLine );
	segments.computeLineDistances();
	segments.scale.set( 1, 1, 1 );
	scene.add( segments );

	thresholdSegments = new LineSegments2( segmentsGeometry, matThresholdLine );
	thresholdSegments.computeLineDistances();
	thresholdSegments.scale.set( 1, 1, 1 );
	scene.add( thresholdSegments );

	line = new Line2( lineGeometry, matLine );
	line.computeLineDistances();
	line.scale.set( 1, 1, 1 );
	scene.add( line );

	thresholdLine = new Line2( lineGeometry, matThresholdLine );
	thresholdLine.computeLineDistances();
	thresholdLine.scale.set( 1, 1, 1 );
	scene.add( thresholdLine );

	const geo = new THREE.BufferGeometry();
	geo.setAttribute( 'position', new THREE.Float32BufferAttribute( positions, 3 ) );
	geo.setAttribute( 'color', new THREE.Float32BufferAttribute( colors, 3 ) );

	//

	switchLine( params[ 'line type' ] );

	//

	document.addEventListener( 'pointermove', onPointerMove );
	window.addEventListener( 'resize', onWindowResize );
	onWindowResize();

	initGui();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function onPointerMove( event ) {

	pointer.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	pointer.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

}

async function animate() {

	timer.update();

	const delta = timer.getDelta();

	const obj = line.visible ? line : segments;
	thresholdLine.position.copy( line.position );
	thresholdLine.quaternion.copy( line.quaternion );
	thresholdSegments.position.copy( segments.position );
	thresholdSegments.quaternion.copy( segments.quaternion );

	if ( params.animate ) {

		line.rotation.y += delta * 0.1;

		segments.rotation.y = line.rotation.y;

	}

	raycaster.setFromCamera( pointer, camera );

	const intersects = raycaster.intersectObject( obj );

	if ( intersects.length > 0 ) {

		sphereInter.visible = true;
		sphereOnLine.visible = true;

		sphereInter.position.copy( intersects[ 0 ].point );
		sphereOnLine.position.copy( intersects[ 0 ].pointOnLine );

		const index = intersects[ 0 ].faceIndex;
		const colors = obj.geometry.getAttribute( 'instanceColorStart' );

		color.fromBufferAttribute( colors, index );

		sphereInter.material.color.copy( color ).offsetHSL( 0.3, 0, 0 );
		sphereOnLine.material.color.copy( color ).offsetHSL( 0.7, 0, 0 );

		renderer.domElement.style.cursor = 'crosshair';

	} else {

		sphereInter.visible = false;
		sphereOnLine.visible = false;
		renderer.domElement.style.cursor = '';

	}

	renderer.render( scene, camera );

}

//

function switchLine( val ) {

	switch ( val ) {

		case 0:
			line.visible = true;
			thresholdLine.visible = true;

			segments.visible = false;
			thresholdSegments.visible = false;

			break;

		case 1:
			line.visible = false;
			thresholdLine.visible = false;

			segments.visible = true;
			thresholdSegments.visible = true;

			break;

	}

}

function initGui() {

	gui = renderer.inspector.createParameters( 'Settings' );

	gui.add( params, 'line type', { 'LineGeometry': 0, 'LineSegmentsGeometry': 1 } ).onChange( function ( val ) {

		switchLine( val );

	} );

	gui.add( params, 'world units' ).onChange( function ( val ) {

		matLine.worldUnits = val;
		matLine.needsUpdate = true;

		matThresholdLine.worldUnits = val;
		matThresholdLine.needsUpdate = true;

	} );

	gui.add( params, 'visualize threshold' ).onChange( function ( val ) {

		matThresholdLine.visible = val;

	} );

	gui.add( params, 'width', 1, 10 ).onChange( function ( val ) {

		matLine.linewidth = val;
		matThresholdLine.linewidth = matLine.linewidth + raycaster.params.Line2.threshold;

	} );

	gui.add( params, 'alphaToCoverage' ).onChange( function ( val ) {

		matLine.alphaToCoverage = val;

	} );

	gui.add( params, 'threshold', 0, 10 ).onChange( function ( val ) {

		raycaster.params.Line2.threshold = val;
		matThresholdLine.linewidth = matLine.linewidth + raycaster.params.Line2.threshold;

	} );

	gui.add( params, 'translation', 0, 10 ).onChange( function ( val ) {

		line.position.x = val;
		segments.position.x = val;

	} );

	gui.add( params, 'animate' );

}

import * as THREE from 'three/webgpu';
import { color } from 'three/tsl';

import { Inspector } from 'three/addons/inspector/Inspector.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { Wireframe } from 'three/addons/lines/webgpu/Wireframe.js';
import { WireframeGeometry2 } from 'three/addons/lines/WireframeGeometry2.js';

let wireframe, renderer, scene, camera, camera2, controls, backgroundNode;
let wireframe1;
let matLine, matLineBasic, matLineDashed;
let gui;

// viewport
let insetWidth;
let insetHeight;

init();

function init() {

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setClearColor( 0x000000 );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.set( - 50, 0, 50 );

	camera2 = new THREE.PerspectiveCamera( 40, 1, 1, 1000 );
	camera2.position.copy( camera.position );

	controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 10;
	controls.maxDistance = 500;

	backgroundNode = color( 0x222222 );

	// Wireframe ( WireframeGeometry2, Line2NodeMaterial )

	let geo = new THREE.IcosahedronGeometry( 20, 1 );

	const geometry = new WireframeGeometry2( geo );

	matLine = new THREE.Line2NodeMaterial( {

		color: 0x4080ff,
		linewidth: 5, // in world units with size attenuation, pixels otherwise
		dashed: false

	} );

	wireframe = new Wireframe( geometry, matLine );
	wireframe.computeLineDistances();
	wireframe.scale.set( 1, 1, 1 );
	scene.add( wireframe );

	// Line ( THREE.WireframeGeometry, THREE.LineBasicMaterial ) - rendered with gl.LINE

	geo = new THREE.WireframeGeometry( geo );

	matLineBasic = new THREE.LineBasicMaterial( { color: 0x4080ff } );
	matLineDashed = new THREE.LineDashedMaterial( { scale: 2, dashSize: 1, gapSize: 1 } );

	wireframe1 = new THREE.LineSegments( geo, matLineBasic );
	wireframe1.computeLineDistances();
	wireframe1.visible = false;
	scene.add( wireframe1 );

	//

	window.addEventListener( 'resize', onWindowResize );
	onWindowResize();

	initGui();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

	insetWidth = window.innerHeight / 4; // square
	insetHeight = window.innerHeight / 4;

	camera2.aspect = insetWidth / insetHeight;
	camera2.updateProjectionMatrix();

}

function animate() {

	// main scene

	renderer.setViewport( 0, 0, window.innerWidth, window.innerHeight );

	renderer.autoClear = true;

	scene.backgroundNode = null;

	scene.name = 'Scene';

	renderer.render( scene, camera );

	// inset scene

	const posY = window.innerHeight - insetHeight - 20;

	renderer.clearDepth(); // important!

	renderer.setScissorTest( true );

	renderer.setScissor( 20, posY, insetWidth, insetHeight );

	renderer.setViewport( 20, posY, insetWidth, insetHeight );

	camera2.position.copy( camera.position );
	camera2.quaternion.copy( camera.quaternion );

	renderer.autoClear = false;

	scene.backgroundNode = backgroundNode;

	scene.name = 'Scene [ Scissor ]';

	renderer.render( scene, camera2 );

	renderer.setScissorTest( false );

}

//

function initGui() {

	gui = renderer.inspector.createParameters( 'Settings' );

	const param = {
		'line type': 0,
		'width (px)': 5,
		'dashed': false,
		'dash scale': 1,
		'dash / gap': 1
	};


	gui.add( param, 'line type', { 'LineGeometry': 0, 'gl.LINE': 1 } ).onChange( function ( val ) {

		switch ( val ) {

			case 0:
				wireframe.visible = true;

				wireframe1.visible = false;

				break;

			case 1:
				wireframe.visible = false;

				wireframe1.visible = true;

				break;

		}

	} );

	gui.add( param, 'width (px)', 1, 10 ).onChange( function ( val ) {

		matLine.linewidth = val;

	} );

	gui.add( param, 'dashed' ).onChange( function ( val ) {

		matLine.dashed = val;
		wireframe1.material = val ? matLineDashed : matLineBasic;

	} );

	gui.add( param, 'dash scale', 0.5, 1, 0.1 ).onChange( function ( val ) {

		matLine.scale = val;
		matLineDashed.scale = val;

	} );

	gui.add( param, 'dash / gap', { '2 : 1': 0, '1 : 1': 1, '1 : 2': 2 } ).onChange( function ( val ) {

		switch ( val ) {

			case 0:
				matLine.dashSize = 2;
				matLine.gapSize = 1;

				matLineDashed.dashSize = 2;
				matLineDashed.gapSize = 1;

				break;

			case 1:
				matLine.dashSize = 1;
				matLine.gapSize = 1;

				matLineDashed.dashSize = 1;
				matLineDashed.gapSize = 1;

				break;

			case 2:
				matLine.dashSize = 1;
				matLine.gapSize = 2;

				matLineDashed.dashSize = 1;
				matLineDashed.gapSize = 2;

				break;

		}

	} );

}

import * as THREE from 'three/webgpu';

import { UltraHDRLoader } from 'three/addons/loaders/UltraHDRLoader.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, scene, renderer, controls;
let currentModel, mixer;
let currentLoadId = 0;

const timer = new THREE.Timer();

init().then( render );

async function init() {

	const container = document.createElement( 'div' );
	document.body.appendChild( container );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.25, 20 );
	camera.position.set( - 1.8, 0.6, 2.7 );

	scene = new THREE.Scene();

	new UltraHDRLoader()
		.setPath( 'textures/equirectangular/' )
		.load( 'royal_esplanade_2k.hdr.jpg', function ( texture ) {

			texture.mapping = THREE.EquirectangularReflectionMapping;
			//texture.minFilter = THREE.LinearMipmapLinearFilter;
			//texture.generateMipmaps = true;

			scene.background = texture;
			scene.environment = texture;

			// model

			fetch( 'https://raw.githubusercontent.com/KhronosGroup/glTF-Sample-Assets/main/Models/model-index.json' )
				.then( response => response.json() )
				.then( models => {

					const gui = renderer.inspector.createParameters( 'Model' );
					const modelNames = models.map( m => m.name );
					const params = { model: 'DamagedHelmet' };

					if ( ! modelNames.includes( params.model ) && modelNames.length > 0 ) {

						params.model = modelNames[ 0 ];

					}

					gui.add( params, 'model', modelNames ).onChange( name => {

						const modelInfo = models.find( m => m.name === name );
						loadModel( modelInfo );

					} );

					gui.add( scene, 'backgroundBlurriness', 0, 1 );

					const initialModel = models.find( m => m.name === params.model );
					if ( initialModel ) loadModel( initialModel );

				} );

		} );

	renderer = new THREE.WebGPURenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( render );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.inspector = new Inspector();
	container.appendChild( renderer.domElement );

	await renderer.init();

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.minDistance = 2;
	controls.maxDistance = 10;
	controls.target.set( 0, 0, - 0.2 );
	controls.update();

	window.addEventListener( 'resize', onWindowResize );

}

function loadModel( modelInfo ) {

	const variants = modelInfo.variants;
	const variant = variants[ 'glTF-Binary' ] || variants[ 'glTF' ];
	const url = `https://raw.githubusercontent.com/KhronosGroup/glTF-Sample-Assets/main/Models/${ modelInfo.name }/${ variant.endsWith( '.glb' ) ? 'glTF-Binary' : 'glTF' }/${ variant }`;

	if ( currentModel ) {

		currentModel.traverse( ( model ) => {

			if ( model.isMesh ) {

				model.geometry.dispose();
				model.material.dispose();

				for ( const value of Object.values( model.material ) ) {

					if ( value && value.isTexture ) {

						value.dispose();

					}

				}

			}

		} );

		scene.remove( currentModel );
		currentModel = null;

	}

	if ( mixer ) {

		mixer.stopAllAction();
		mixer = null;

	}

	const loadId = ++ currentLoadId;

	const loader = new GLTFLoader();
	loader.load( url, async function ( gltf ) {

		if ( loadId !== currentLoadId ) return;

		currentModel = gltf.scene;

		// wait until the model can be added to the scene without blocking due to shader compilation

		await renderer.compileAsync( currentModel, camera, scene );

		if ( loadId !== currentLoadId ) return;

		scene.add( currentModel );

		fitCameraToSelection( camera, controls, currentModel );

		// animations

		if ( gltf.animations.length > 0 ) {

			mixer = new THREE.AnimationMixer( currentModel );

			for ( const animation of gltf.animations ) {

				mixer.clipAction( animation ).play();

			}

		}

	} );

}

function fitCameraToSelection( camera, controls, selection, fitOffset = 1.3 ) {

	const box = new THREE.Box3();
	box.setFromObject( selection );

	const size = box.getSize( new THREE.Vector3() );
	const center = box.getCenter( new THREE.Vector3() );

	const maxSize = Math.max( size.x, size.y, size.z );
	const fitHeightDistance = maxSize / ( 2 * Math.tan( Math.PI * camera.fov / 360 ) );
	const distance = fitOffset * fitHeightDistance;

	const direction = controls.target.clone().sub( camera.position ).normalize().multiplyScalar( distance );

	controls.maxDistance = distance * 10;
	controls.minDistance = distance / 10;
	controls.target.copy( center );

	camera.near = distance / 100;
	camera.far = distance * 100;
	camera.updateProjectionMatrix();

	camera.position.copy( controls.target ).sub( direction );

	controls.update();

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function render() {

	timer.update();

	controls.update();

	if ( mixer ) mixer.update( timer.getDelta() );

	renderer.render( scene, camera );

}

