import * as THREE from 'three/webgpu';
import { pass } from 'three/tsl';
import { bloom } from 'three/addons/tsl/display/BloomNode.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { WaterMesh } from 'three/addons/objects/WaterMesh.js';
import { SkyMesh } from 'three/addons/objects/SkyMesh.js';

let container;
let camera, scene, renderer, renderPipeline;
let controls, water, sun, sky, mesh, bloomPass;

init();

function init() {

	container = document.getElementById( 'container' );

	//

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( render );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 0.1;
	renderer.inspector = new Inspector();
	container.appendChild( renderer.domElement );

	//

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 55, window.innerWidth / window.innerHeight, 1, 20000 );
	camera.position.set( 30, 30, 100 );

	// Post-processing

	renderPipeline = new THREE.RenderPipeline( renderer );

	const scenePass = pass( scene, camera );
	const scenePassColor = scenePass.getTextureNode( 'output' );

	bloomPass = bloom( scenePassColor );
	bloomPass.threshold.value = 0;
	bloomPass.strength.value = 0.1;
	bloomPass.radius.value = 0;

	renderPipeline.outputNode = scenePassColor.add( bloomPass );

	//

	sun = new THREE.Vector3();

	// Water

	const waterGeometry = new THREE.PlaneGeometry( 10000, 10000 );
	const loader = new THREE.TextureLoader();
	const waterNormals = loader.load( 'textures/waternormals.jpg' );
	waterNormals.wrapS = waterNormals.wrapT = THREE.RepeatWrapping;

	water = new WaterMesh(
		waterGeometry,
		{
			waterNormals: waterNormals,
			sunDirection: new THREE.Vector3(),
			sunColor: 0xffffff,
			waterColor: 0x001e0f,
			distortionScale: 3.7
		}
	);

	water.rotation.x = - Math.PI / 2;

	scene.add( water );

	// Skybox

	sky = new SkyMesh();
	sky.scale.setScalar( 10000 );
	scene.add( sky );

	sky.turbidity.value = 10;
	sky.rayleigh.value = 2;
	sky.mieCoefficient.value = 0.005;
	sky.mieDirectionalG.value = 0.8;
	sky.cloudCoverage.value = 0.4;
	sky.cloudDensity.value = 0.5;
	sky.cloudElevation.value = 0.5;

	const parameters = {
		elevation: 2,
		azimuth: 180,
		exposure: 0.1
	};

	const pmremGenerator = new THREE.PMREMGenerator( renderer );
	const sceneEnv = new THREE.Scene();

	let renderTarget;

	function updateSun() {

		const phi = THREE.MathUtils.degToRad( 90 - parameters.elevation );
		const theta = THREE.MathUtils.degToRad( parameters.azimuth );

		sun.setFromSphericalCoords( 1, phi, theta );

		sky.sunPosition.value.copy( sun );
		water.sunDirection.value.copy( sun ).normalize();

		if ( renderTarget !== undefined ) renderTarget.dispose();

		sceneEnv.add( sky );
		renderTarget = pmremGenerator.fromScene( sceneEnv );
		scene.add( sky );

		scene.environment = renderTarget.texture;

	}

	renderer.init().then( updateSun );

	//

	const geometry = new THREE.BoxGeometry( 30, 30, 30 );
	const material = new THREE.MeshStandardMaterial( { roughness: 0 } );

	mesh = new THREE.Mesh( geometry, material );
	scene.add( mesh );

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.maxPolarAngle = Math.PI * 0.495;
	controls.target.set( 0, 10, 0 );
	controls.minDistance = 40.0;
	controls.maxDistance = 200.0;
	controls.update();

	// GUI

	const gui = renderer.inspector.createParameters( 'Settings' );

	const folderSky = gui.addFolder( 'Sky' );
	folderSky.add( parameters, 'elevation', 0, 90, 0.1 ).onChange( updateSun );
	folderSky.add( parameters, 'azimuth', - 180, 180, 0.1 ).onChange( updateSun );
	folderSky.add( parameters, 'exposure', 0, 1, 0.0001 ).onChange( function ( value ) {

		renderer.toneMappingExposure = value;

	} );

	const folderWater = gui.addFolder( 'Water' );
	folderWater.add( water.distortionScale, 'value', 0, 8, 0.1 ).name( 'distortionScale' );
	folderWater.add( water.size, 'value', 0.1, 10, 0.1 ).name( 'size' );

	const folderBloom = gui.addFolder( 'Bloom' );
	folderBloom.add( bloomPass.strength, 'value', 0, 3, 0.01 ).name( 'strength' );
	folderBloom.add( bloomPass.radius, 'value', 0, 1, 0.01 ).name( 'radius' );

	const folderClouds = gui.addFolder( 'Clouds' );
	folderClouds.add( sky.cloudCoverage, 'value', 0, 1, 0.01 ).name( 'coverage' );
	folderClouds.add( sky.cloudDensity, 'value', 0, 1, 0.01 ).name( 'density' );
	folderClouds.add( sky.cloudElevation, 'value', 0, 1, 0.01 ).name( 'elevation' );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function render() {

	const time = performance.now() * 0.001;

	mesh.position.y = Math.sin( time ) * 20 + 5;
	mesh.rotation.x = time * 0.5;
	mesh.rotation.z = time * 0.51;

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass } from 'three/tsl';
import { oitPass } from 'three/addons/tsl/display/OITPassNode.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, scene, renderer;
let renderPipeline, scenePassOIT, scenePass;
let spheres, controls;

const transparentMaterials = [];

const params = {
	oit: true,
	opacity: 0.5
};

init();

function init() {

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 8, 4, 10 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x202020 );

	// lights

	const hemiLight = new THREE.HemisphereLight( 0xffffff, 0x444444, 1.5 );
	scene.add( hemiLight );

	const dirLight = new THREE.DirectionalLight( 0xffffff, 2.5 );
	dirLight.position.set( 4, 10, 6 );
	scene.add( dirLight );

	// opaque center object

	const torusKnot = new THREE.Mesh(
		new THREE.TorusKnotGeometry( 1, 0.4, 128, 32 ),
		new THREE.MeshStandardMaterial( { color: 0xffffff, roughness: 0.2 } )
	);
	scene.add( torusKnot );

	// intersecting transparent planes. no draw order can resolve them correctly
	// with sorting-based transparency

	const planeGeometry = new THREE.PlaneGeometry( 6, 6 );
	const planeColors = [ 0xff4030, 0x30d060, 0x3070ff ];

	for ( let i = 0; i < planeColors.length; i ++ ) {

		const material = new THREE.MeshStandardMaterial( {
			color: planeColors[ i ],
			roughness: 0.5,
			transparent: true,
			opacity: params.opacity,
			side: THREE.DoubleSide
		} );
		transparentMaterials.push( material );

		const plane = new THREE.Mesh( planeGeometry, material );
		plane.rotation.y = ( i / planeColors.length ) * Math.PI;
		scene.add( plane );

	}

	// orbiting transparent spheres. their sort order flips while they rotate
	// which results in popping with sorting-based transparency

	spheres = new THREE.Group();

	const sphereGeometry = new THREE.SphereGeometry( 0.8, 32, 16 );
	const sphereColors = [ 0xffc020, 0xd040d0, 0x40c0d0, 0xa0d040 ];

	for ( let i = 0; i < sphereColors.length; i ++ ) {

		const material = new THREE.MeshStandardMaterial( {
			color: sphereColors[ i ],
			roughness: 0.3,
			transparent: true,
			opacity: params.opacity
		} );
		transparentMaterials.push( material );

		const sphere = new THREE.Mesh( sphereGeometry, material );

		const angle = ( i / sphereColors.length ) * Math.PI * 2;
		sphere.position.set( Math.cos( angle ) * 2.5, 0, Math.sin( angle ) * 2.5 );

		spheres.add( sphere );

	}

	scene.add( spheres );

	//

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	//

	scenePassOIT = oitPass( scene, camera );
	scenePass = pass( scene, camera );

	renderPipeline = new THREE.RenderPipeline( renderer );
	renderPipeline.outputNode = scenePassOIT;

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.autoRotate = true;
	controls.enableDamping = true;
	controls.minDistance = 5;
	controls.maxDistance = 25;

	//

	const gui = renderer.inspector.createParameters( 'Settings' );

	gui.add( params, 'oit' ).onChange( ( value ) => {

		renderPipeline.outputNode = ( value === true ) ? scenePassOIT : scenePass;
		renderPipeline.needsUpdate = true;

	} );

	gui.add( params, 'opacity', 0, 1 ).onChange( ( value ) => {

		for ( const material of transparentMaterials ) {

			material.opacity = value;

		}

	} );

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { texture, parallaxUV, blendOverlay, uv, normalMap, uniform } from 'three/tsl';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
