}

function animate( time ) {

	particles.rotation.z = time * 0.001;

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, screenUV, uniform, uv, vec2, vec3, color, Fn, vec4, Loop, float, mix, luminance, smoothstep, rtt, time, viewportSize, instanceIndex, positionLocal } from 'three/tsl';
import { bloom } from 'three/addons/tsl/display/BloomNode.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, scene, renderer, instancedMesh, controls;
let renderPipeline;

const _dummy = new THREE.Object3D();

init();

async function init() {

	const container = document.createElement( 'div' );
	document.body.appendChild( container );

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.25, 250 );
	camera.position.set( 0, 0, 20 );

	scene = new THREE.Scene();
	scene.backgroundNode = Fn( () => {

		const dist = screenUV.distance( 0.5 ).mul( 2.0 );
		return mix( color( 0x111111 ), color( 0x000000 ), dist );

	} )();

	const timeScale = uniform( 0.5 );

	const material = new THREE.MeshBasicNodeMaterial( {
		color: 0xffffff,
		// Animate the spheres up and down continuously using TSL and their instanceIndex as a phase offset
		positionNode: positionLocal.add( vec3( 0, time.add( float( instanceIndex ).mul( 0.5 ) ).mul( timeScale ).sin().mul( 5.0 ), 0 ) )
	} );

	const maxCount = 200;

	instancedMesh = new THREE.InstancedMesh( new THREE.SphereGeometry( 0.1, 32, 32 ), material, maxCount );

	const _color = new THREE.Color();

	for ( let i = 0; i < maxCount; i ++ ) {

		_dummy.position.x = ( Math.random() - 0.5 ) * 20;
		_dummy.position.y = ( Math.random() - 0.5 ) * 20;
		_dummy.position.z = ( Math.random() - 0.5 ) * 20;
		_dummy.updateMatrix();
		instancedMesh.setMatrixAt( i, _dummy.matrix );

		_color.setHex( Math.random() * 0xffffff );
		instancedMesh.setColorAt( i, _color );

	}

	scene.add( instancedMesh );

	renderer = new THREE.WebGPURenderer( { antialias: true } );

	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );

	renderer.toneMapping = THREE.NeutralToneMapping;
	renderer.toneMappingExposure = 1;
	renderer.inspector = new Inspector();
	renderer.setAnimationLoop( render );
	container.appendChild( renderer.domElement );

	controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 2;
	controls.maxDistance = 25;

	// post-processing

	const scenePass = pass( scene, camera );

	const intensity = uniform( 5.0 );
	const tintColor = uniform( new THREE.Color( 0x7a8aff ) );
	const threshold = uniform( 0.3 );
	const radius = uniform( 0.0 );
	const samples = uniform( 80 );

	const bloomPass = bloom( scenePass.getTextureNode().toInspector( 'Color' ), intensity, radius, threshold );
	bloomPass.setResolutionScale( 0.25 );

	// Custom high pass for anamorphic bloom
	bloomPass.highPassFn = Fn( ( { input, threshold, smoothWidth } ) => {

		// Extract bright areas to a texture (computed once, sampled many times)
		const v = luminance( input.rgb );
		const alpha = smoothstep( threshold, threshold.add( smoothWidth ), v );
		const brightPass = rtt( mix( vec4( 0 ), input, alpha ), null, null, {
			wrapS: THREE.MirroredRepeatWrapping,
			wrapT: THREE.MirroredRepeatWrapping
		} );

		// Horizontal blur
		const total = vec4( 0 );
		const halfSamples = samples.div( 2 );

		const invSize = vec2( 1.0 ).div( viewportSize );

		Loop( { start: halfSamples.negate(), end: halfSamples }, ( { i } ) => {

			let softness = float( i ).abs().div( halfSamples ).oneMinus();
			softness = softness.pow( 2.0 );

			const shiftedUV = vec2( uv().x.add( invSize.x.mul( i ).mul( 4.0 ) ), uv().y );
			total.addAssign( brightPass.sample( shiftedUV ).mul( softness ) );

		} );

		return total.div( samples.div( 3.0 ) );

	} );

	const anamorphicPass = bloomPass.mul( tintColor ).toInspector( 'Anamorphic' );

	renderPipeline = new THREE.RenderPipeline( renderer );
	renderPipeline.outputNode = scenePass.add( anamorphicPass );

	// gui

	const gui = renderer.inspector.createParameters( 'Settings' );
	gui.add( intensity, 'value', 0, 10 ).name( 'intensity' );
	gui.add( threshold, 'value', 0, .9 ).name( 'threshold' );
	gui.add( samples, 'value', 2, 128, 1 ).name( 'samples' );
	gui.addColor( tintColor, 'value' ).name( 'tint color' );
	gui.add( radius, 'value', 0, 1, 0.01 ).name( 'bloom radius' );
	gui.add( timeScale, 'value', 0, 1 ).name( 'time scale' );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function render() {

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { sample, pass, mrt, screenUV, normalView, velocity, vec3, vec4, packNormalToRGB, unpackRGBToNormal, colorSpaceToWorking, builtinAOContext } from 'three/tsl';
import { ao } from 'three/addons/tsl/display/GTAONode.js';
import { ssao } from 'three/addons/tsl/display/SSAONode.js';
import { traa } from 'three/addons/tsl/display/TRAANode.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, scene, renderer, renderPipeline, controls;

let aoPass, traaPass, transparentMesh;

const params = {
	aoType: 'GTAO',
	samples: 16,
	radius: 0.4,
	resolutionScale: 0.5,
	scale: 0.8, // GTAO
	thickness: 1, // GTAO
	temporalFiltering: true, // GTAO
	intensity: 2, // SSAO
	bias: 0.025, // SSAO
	blurEnabled: true, // SSAO
	blurSharpness: 2, // SSAO
	aoOnly: false,
	transparentOpacity: 0.3
};

init();

async function init() {

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.1, 50 );
	camera.position.set( 1, 3, 7 );

	scene = new THREE.Scene();

	renderer = new THREE.WebGPURenderer();
	renderer.toneMapping = THREE.NeutralToneMapping;
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	// controls

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.minDistance = 2;
	controls.maxDistance = 16;
	controls.target.set( 0, 1.2, 0 );

	// environment

	const environment = new RoomEnvironment();
	const pmremGenerator = new THREE.PMREMGenerator( renderer );

	scene.background = new THREE.Color( 0x666666 );
	scene.environment = pmremGenerator.fromScene( environment, 0.04 ).texture;
	scene.environmentIntensity = 0.3;
	environment.dispose();
	pmremGenerator.dispose();

	// post-processing

	renderPipeline = new THREE.RenderPipeline( renderer );

	// pre-pass

	const prePass = pass( scene, camera ).toInspector( 'Normal', ( inspectNode ) => colorSpaceToWorking( inspectNode, THREE.SRGBColorSpace ) );
	prePass.name = 'Pre-Pass';
	prePass.transparent = false;

	prePass.setMRT( mrt( {
		output: packNormalToRGB( normalView ),
		velocity: velocity
	} ) );

	const prePassNormal = sample( ( uv ) => {

		return unpackRGBToNormal( prePass.getTextureNode().sample( uv ) );

	} );

	const prePassDepth = prePass.getTextureNode( 'depth' ).toInspector( 'Depth', () => prePass.getLinearDepthNode() );
	const prePassVelocity = prePass.getTextureNode( 'velocity' ).toInspector( 'Velocity' );

	// pre-pass - bandwidth optimization

	const normalTexture = prePass.getTexture( 'output' );
	normalTexture.type = THREE.UnsignedByteType;

	// scene pass

	const scenePass = pass( scene, camera ).toInspector( 'Color' );

	// traa ( resolves the temporal noise of GTAO )

	traaPass = traa( scenePass, prePassDepth, prePassVelocity, camera );
	traaPass.useSubpixelCorrection = false;

	// ao: the AO node feeds the scene's ambient term via `builtinAOContext`, and
	// can be switched between GTAO ( ground-truth, needs temporal denoise ) and the
	// cheaper SSAO ( self-denoised )

	function updateOutput() {

		// SSAO is self-denoised so it can skip TRAA and use MSAA for edge anti-aliasing instead

		const useTRAA = ( params.aoType === 'GTAO' );

		scenePass.options.samples = useTRAA ? 0 : 4;

		renderPipeline.outputNode = params.aoOnly ? vec4( vec3( aoPass.getTextureNode().sample( screenUV ).r ), 1 ) : ( useTRAA ? traaPass : scenePass );
		renderer.toneMapping = params.aoOnly ? THREE.NoToneMapping : THREE.NeutralToneMapping;
		renderPipeline.needsUpdate = true;

	}

	function createAO() {

		if ( aoPass ) aoPass.dispose();

		aoPass = ( params.aoType === 'SSAO' )
			? ssao( prePassDepth, prePassNormal, camera ).toInspector( 'SSAO', ( inspectNode ) => inspectNode.r )
			: ao( prePassDepth, prePassNormal, camera ).toInspector( 'GTAO', ( inspectNode ) => inspectNode.r );

		updateParameters();

		scenePass.contextNode = builtinAOContext( aoPass.getTextureNode().sample( screenUV ).r );
		scenePass.needsUpdate = true;

		updateOutput();

	}

	createAO();

	// models

	const dracoLoader = new DRACOLoader();
	const loader = new GLTFLoader();
	loader.setDRACOLoader( dracoLoader );
