	const cupBody = new THREE.Mesh( new THREE.CylinderGeometry( 0.1, 0.08, 0.2, 16 ), cupMat );
	cupBody.scale.setScalar( 1 / 2.2 );
	cupBody.position.set( 0.15, - 0.98, 0 );
	tableGroup.add( cupBody );

