		const cell = p.floor();
		const checker = cell.x.add( cell.y ).mod( 2.0 ).abs();
		const tileColor = checker.greaterThan( 0.5 ).select( color( 0x3b3e46 ), color( 0x33363d ) );

		// Anti-aliased grid coverage helper using screen-space derivatives (fwidth)
		const getGridCoverage = ( coord, lineWidthInPixels ) => {

			const deriv = fwidth( coord ).max( 0.0001 );
			const distFromEdge = float( 0.5 ).sub( coord.fract().sub( 0.5 ).abs() );
			const pixelDist = distFromEdge.div( deriv );

			const lineX = smoothstep( float( lineWidthInPixels ), float( 0.0 ), pixelDist.x );
			const lineY = smoothstep( float( lineWidthInPixels ), float( 0.0 ), pixelDist.y );

			return lineX.max( lineY );

