		const corner = p.sub( p.round() ).abs();
		const deriv = fwidth( p ).max( 0.0001 );
		const crossH = smoothstep( float( 0.08 ), float( 0.07 ), corner.x ).mul( smoothstep( deriv.y.mul( 1.5 ), float( 0.0 ), corner.y ) );
		const crossV = smoothstep( float( 0.08 ), float( 0.07 ), corner.y ).mul( smoothstep( deriv.x.mul( 1.5 ), float( 0.0 ), corner.x ) );
		const crossCoverage = crossH.max( crossV );

