	}

	const noise3DTexture = createNoise3DTexture( 96 );

	// Post-Processing RenderPipeline

	renderPipeline = new THREE.RenderPipeline( renderer );

	const scenePass = pass( scene, camera );
	const sceneColor = scenePass.getTextureNode( 'output' ).toInspector( 'scene' );
	const sceneDepth = scenePass.getTextureNode( 'depth' );

	// Camera Uniforms for Post-Processing (ensures perspective camera matrices are used instead of quad orthographic camera)

	const cameraWorldMatrixUniform = uniform( camera.matrixWorld );
	const cameraProjectionMatrixInverseUniform = uniform( camera.projectionMatrixInverse );
	const cameraPositionUniform = uniform( camera.position );

	// Volumetric Cloud Fog Uniforms

	const resolutionScale = uniform( 0.4 );
	const steps = uniform( 16 );
