		const cloud = noise3D.sub( cloudThreshold ).max( 0.0 ).mul( heightFactor );

		return cloud;

	} );

	// Post-Processing Volumetric Raymarching Pass using Scene Depth

	const volumetricFogPass = Fn( () => {

		const depth = sceneDepth.sample( screenUV ).r;
		const viewPos = getViewPosition( screenUV, depth, cameraProjectionMatrixInverseUniform );
		const targetWorldPos = cameraWorldMatrixUniform.mul( vec4( viewPos, 1.0 ) ).xyz;

		const rayVector = targetWorldPos.sub( cameraPositionUniform );
		const surfaceDist = rayVector.length();
		const rayDir = rayVector.normalize();

		// Ray-Slab: intersect ray with the physical fog layer [groundLevelY, groundLevelY + fogHeight]
		const fogBottomY = groundLevelY;
		const fogTopY = groundLevelY.add( fogHeight );

		const dirY = rayDir.y.greaterThanEqual( 0.0 ).select( rayDir.y.max( 0.00001 ), rayDir.y.min( - 0.00001 ) );
		const t0 = fogBottomY.sub( cameraPositionUniform.y ).div( dirY );
		const t1 = fogTopY.sub( cameraPositionUniform.y ).div( dirY );

