		const centerCoord = screenUV;

		// High-resolution guide: Full-resolution linear scene depth at the output pixel
		const centerDepth = getViewPosition( centerCoord, depthTexture.sample( centerCoord ).r, cameraProjectionMatrixInverseUniform ).z.negate().max( 0.001 );

		// Low-resolution texel footprint based on resolutionScale
		const lowResTexel = fwidth( centerCoord ).div( resolutionScale );

		// Precomputed Gaussian factors
		const spatialSigmaFactor = float( - 0.5 ).div( spatialSig.mul( spatialSig ).max( 0.01 ) );
		const depthSigmaFactor = depthSens.mul( depthSens ).mul( - 0.5 );

		const sumColor = float( 0.0 ).toVar();
		const sumWeight = float( 0.0 ).toVar();

		// 5x5 spatial support over the low-resolution grid
		for ( let y = - 2; y <= 2; y ++ ) {

			for ( let x = - 2; x <= 2; x ++ ) {

				const offset = vec2( float( x ), float( y ) );
				const spatialDistSq = offset.x.mul( offset.x ).add( offset.y.mul( offset.y ) );
				const spatialWeight = exp( spatialDistSq.mul( spatialSigmaFactor ) );

				const sampleUV = centerCoord.add( offset.mul( lowResTexel ) );
				const sampleFog = lowResTexture.sample( sampleUV );
				const sampleDepth = getViewPosition( sampleUV, depthTexture.sample( sampleUV ).r, cameraProjectionMatrixInverseUniform ).z.negate().max( 0.001 );

				// Range weight based on high-resolution depth similarity (preserves geometric edges)
				const depthDiff = sampleDepth.sub( centerDepth ).div( centerDepth.max( 0.1 ) );
				const rangeWeight = exp( depthDiff.mul( depthDiff ).mul( depthSigmaFactor ) );

				const totalWeight = spatialWeight.mul( rangeWeight );

				sumColor.addAssign( sampleFog.mul( totalWeight ) );
				sumWeight.addAssign( totalWeight );

			}

		}

		return sumColor.div( sumWeight.max( 0.0001 ) );

	} );

	// Low-Resolution Volumetric Fog Pass RTT

	const lowResFogPass = rtt( volumetricFogPass(), null, null, {
		type: THREE.UnsignedByteType,
		format: THREE.RedFormat,
		resolutionScale: resolutionScale.value
	} ).setName( 'lowResFogPass' ).toInspector( 'Volumetric Fog' );

	// Denoising Options: JBU, Gaussian Blur, Disabled (Raw)

	const jbuFog = jointBilateralUpsampling( lowResFogPass, sceneDepth, spatialSigma, depthSensitivity );
	const gaussianFog = gaussianBlur( lowResFogPass, blurRadius );
	const rawFog = lowResFogPass.sample( screenUV );

	const filterParams = {
		mode: 'JBU'
	};

	function updateFilterMode() {

		let selectedFog;

		if ( filterParams.mode === 'JBU' ) {

			selectedFog = jbuFog;

		} else if ( filterParams.mode === 'Gaussian Blur' ) {

			selectedFog = gaussianFog;

		} else {

			selectedFog = rawFog;

		}

		renderPipeline.outputNode = selectedFog.mix( sceneColor.rgb, color( 0xffffff ) );
		renderPipeline.needsUpdate = true;

		updateDenoiserControls();

	}

	function updateDenoiserControls() {

		const isJBU = filterParams.mode === 'JBU';
		const isGaussian = filterParams.mode === 'Gaussian Blur';

		isJBU ? ctrlSpatialSigma.show() : ctrlSpatialSigma.hide();
		isJBU ? ctrlDepthSensitivity.show() : ctrlDepthSensitivity.hide();
		isGaussian ? ctrlGaussianBlur.show() : ctrlGaussianBlur.hide();

	}

	const groundParams = {
		mode: 'Solid Color'
	};

	function updateGround() {

		if ( groundParams.mode === 'Grid' ) {

			groundMaterial.colorNode = gridNode;

		} else {

			groundMaterial.colorNode = solidColorNode;

		}

		groundMaterial.needsUpdate = true;

	}

	// Controls

	controls = new OrbitControls( camera, renderer.domElement );
	controls.minDistance = 2;
	controls.maxDistance = 20;
	controls.maxPolarAngle = Math.PI / 2;
	controls.target.set( 0, 1.0, 0 );
	controls.enableDamping = true;
	controls.update();

	// GUI

	const gui = renderer.inspector.createParameters( 'Volumetric Fog' );
	gui.add( filterParams, 'mode', [ 'JBU', 'Gaussian Blur', 'Disabled' ] ).name( 'denoiser' ).onChange( () => updateFilterMode() );
	gui.add( resolutionScale, 'value', 0.25, 0.75, 0.05 ).name( 'resolution scale' ).onChange( ( value ) => lowResFogPass.setResolutionScale( value ) );
	gui.add( steps, 'value', 4, 32, 1 ).name( 'steps' );
	gui.add( cloudThreshold, 'value', 0.0, 0.8, 0.02 ).name( 'cloud threshold' );
	gui.add( cloudScale, 'value', 0.001, 0.15, 0.001 ).name( 'cloud scale' );
	gui.add( maxRayDist, 'value', 10.0, 70.0, 1.0 ).name( 'max ray dist' );
	gui.add( fogDensity, 'value', 0.0, 3.0, 0.05 ).name( 'fog density' );
	gui.add( heightFalloff, 'value', 0.2, 4.0, 0.1 ).name( 'height falloff' );
	gui.add( fogHeight, 'value', 0.2, 8.0, 0.1 ).name( 'fog height (m)' );
	gui.add( cloudSpeed, 'value', 0.0, 0.2, 0.005 ).name( 'cloud speed' );
	gui.add( rangeFogNear, 'value', 0.0, 100.0, 0.5 ).name( 'range fog near' );
	gui.add( rangeFogFar, 'value', 5.0, 150.0, 0.5 ).name( 'range fog far' );

	const ctrlSpatialSigma = gui.add( spatialSigma, 'value', 0.5, 3.0, 0.1 ).name( 'spatial sigma' );
	const ctrlDepthSensitivity = gui.add( depthSensitivity, 'value', 1.0, 100.0, 1.0 ).name( 'depth sensitivity' );
	const ctrlGaussianBlur = gui.add( blurRadius, 'value', 0.0, 1.0, 0.01 ).name( 'gaussian blur' );

	gui.add( groundParams, 'mode', [ 'Solid Color', 'Grid' ] ).name( 'ground' ).onChange( () => updateGround() );

	updateFilterMode();

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	const delta = timer.getDelta();

	cloudTimeUniform.value += delta * cloudSpeed.value;

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, renderOutput } from 'three/tsl';
import { fxaa } from 'three/addons/tsl/display/FXAANode.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

const params = {
	enabled: true,
	animated: false
};

let camera, scene, renderer, timer, group;
let renderPipeline;

init();

async function init() {

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.1, 200 );
	camera.position.z = 50;

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xffffff );

	timer = new THREE.Timer();
	timer.connect( document );

	//

	const hemiLight = new THREE.HemisphereLight( 0xffffff, 0x8d8d8d );
	hemiLight.position.set( 0, 1000, 0 );
	scene.add( hemiLight );

	const dirLight = new THREE.DirectionalLight( 0xffffff, 3 );
	dirLight.position.set( - 3000, 1000, - 1000 );
	scene.add( dirLight );

	//

	group = new THREE.Group();

	const geometry = new THREE.TetrahedronGeometry();
	const material = new THREE.MeshStandardMaterial( { color: 0xf73232, flatShading: true } );

	const mesh = new THREE.InstancedMesh( geometry, material, 100 );
	const dummy = new THREE.Object3D();

	for ( let i = 0; i < 100; i ++ ) {

		dummy.position.x = Math.random() * 50 - 25;
		dummy.position.y = Math.random() * 50 - 25;
		dummy.position.z = Math.random() * 50 - 25;

		dummy.scale.setScalar( Math.random() * 2 + 1 );

		dummy.rotation.x = Math.random() * Math.PI;
		dummy.rotation.y = Math.random() * Math.PI;
		dummy.rotation.z = Math.random() * Math.PI;

		dummy.updateMatrix();
		mesh.setMatrixAt( i, dummy.matrix );

	}

	group.add( mesh );
	scene.add( group );

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	// post processing

	renderPipeline = new THREE.RenderPipeline( renderer );

	// ignore default output color transform ( toneMapping and outputColorSpace )
	// use renderOutput() for control the sequence

	renderPipeline.outputColorTransform = false;

	// scene pass

	const scenePass = pass( scene, camera ).toInspector( 'Color' );
	const outputPass = renderOutput( scenePass );

	// FXAA must be computed in sRGB color space (so after tone mapping and color space conversion)

	const fxaaPass = fxaa( outputPass );
	renderPipeline.outputNode = fxaaPass;

	//

	window.addEventListener( 'resize', onWindowResize );

	//

	const gui = renderer.inspector.createParameters( 'Settings' );
	gui.add( params, 'enabled' ).onChange( ( value ) => {

		if ( value === true ) {

			renderPipeline.outputNode = fxaaPass;

		} else {

			renderPipeline.outputNode = outputPass;

		}

		renderPipeline.needsUpdate = true;

	} );
	gui.add( params, 'animated' );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function animate() {

	timer.update();

	const delta = timer.getDelta();

	if ( params.animated === true ) {

		group.rotation.y += delta * 0.1;

	}

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, uniform, float, int, color } from 'three/tsl';
import { godrays } from 'three/addons/tsl/display/GodraysNode.js';
import { bilateralBlur } from 'three/addons/tsl/display/BilateralBlurNode.js';
import { depthAwareBlend } from 'three/addons/tsl/display/depthAwareBlend.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, controls, scene, renderer, renderPipeline;

const params = {
	enabledBlur: true,
};

init();

async function init() {

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 1000 );
	camera.position.set( - 175, 50, 0 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x000000 );

	// asset

	const loader = new GLTFLoader();
	const gltf = await loader.loadAsync( 'models/gltf/godrays_demo.glb' );
	scene.add( gltf.scene );

	const pillars = gltf.scene.getObjectByName( 'concrete' );
	pillars.material = new THREE.MeshStandardMaterial( {
		color: 0x333333,
	} );

	const base = gltf.scene.getObjectByName( 'base' );
	base.material = new THREE.MeshStandardMaterial( {
		color: 0x333333,
		side: THREE.DoubleSide,
	} );

	// lights

	const lightPos = new THREE.Vector3( 0, 50, 0 );
	const lightSphereMaterial = new THREE.MeshBasicMaterial( {
		color: 0xffffff,
	} );
	const lightSphere = new THREE.Mesh( new THREE.SphereGeometry( 0.5, 16, 16 ), lightSphereMaterial );
	lightSphere.position.copy( lightPos );
	scene.add( lightSphere );

	scene.add( new THREE.AmbientLight( 0xcccccc, 0.4 ) );

	const pointLight = new THREE.PointLight( 0xf6287d, 10000 );
	pointLight.castShadow = true;
	pointLight.shadow.bias = - 0.00001;
	pointLight.shadow.mapSize.width = 2048;
	pointLight.shadow.mapSize.height = 2048;
	pointLight.position.copy( lightPos );
	scene.add( pointLight );

	setupBackdrop();

	// shadow setup

	scene.traverse( obj => {

		if ( obj.isMesh === true ) {

			obj.castShadow = true;
			obj.receiveShadow = true;

		}

	} );

	lightSphere.castShadow = false;
	lightSphere.receiveShadow = false;

	// renderer

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	renderer.shadowMap.enabled = true;
	document.body.appendChild( renderer.domElement );

	// post processing

	renderPipeline = new THREE.RenderPipeline( renderer );

	// beauty

	const scenePass = pass( scene, camera );
	const scenePassColor = scenePass.getTextureNode( 'output' );
	const scenePassDepth = scenePass.getTextureNode( 'depth' );

	// godrays

	const godraysPass = godrays( scenePassDepth, camera, pointLight );
	const godraysPassColor = godraysPass.getTextureNode();

	// blur

	const blurPass = bilateralBlur( godraysPassColor );
	const blurPassColor = blurPass.getTextureNode();

	// composite

	const blendColor = uniform( color( 0xf6287d ) );
	const edgeRadius = uniform( int( 2 ) );
	const edgeStrength = uniform( float( 2 ) );

	const outputBlurred = depthAwareBlend( scenePassColor, blurPassColor, scenePassDepth, camera, { blendColor, edgeRadius, edgeStrength } );
	const outputRaw = depthAwareBlend( scenePassColor, godraysPassColor, scenePassDepth, camera, { blendColor, edgeRadius, edgeStrength } );

	renderPipeline.outputNode = outputBlurred;

	// GUI

	const gui = renderer.inspector.createParameters( 'Settings' );
	const godraysFolder = gui.addFolder( 'Godrays' );
	godraysFolder.add( godraysPass.raymarchSteps, 'value', 24, 120 ).step( 1 ).name( 'raymarch steps' );
	godraysFolder.add( godraysPass.density, 'value', 0, 1 ).name( 'density' );
	godraysFolder.add( godraysPass.maxDensity, 'value', 0, 1 ).name( 'max density' );
	godraysFolder.add( godraysPass.distanceAttenuation, 'value', 0, 5 ).name( 'distance attenuation' );

	const compositeFolder = gui.addFolder( 'composite' );
	compositeFolder.add( edgeRadius, 'value', 0, 5, 1 ).name( 'edge radius' );
	compositeFolder.add( edgeStrength, 'value', 0, 5 ).name( 'edge strength' );

	const blurFolder = gui.addFolder( 'blur' );
	blurFolder.add( params, 'enabledBlur' ).name( 'enabled' ).onChange( ( value ) => {

		if ( value === true ) {

			renderPipeline.outputNode = outputBlurred;

		} else {

			renderPipeline.outputNode = outputRaw;

		}

		renderPipeline.needsUpdate = true;

	} );

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.target.set( 0, 0.5, 0 );
	controls.enableDamping = true;
	controls.maxDistance = 200;
	controls.update();

	window.addEventListener( 'resize', onWindowResize );

}


function setupBackdrop() {

	 const backdropDistance = 200;
	// Add backdrop walls `backdropDistance` units away from the origin
	const backdropGeometry = new THREE.PlaneGeometry( 400, 200 );
	const backdropMaterial = new THREE.MeshBasicMaterial( {
		color: 0x000000,
		side: THREE.DoubleSide,
	} );
	const backdropLeft = new THREE.Mesh( backdropGeometry, backdropMaterial );
	backdropLeft.position.set( - backdropDistance, 100, 0 );
	backdropLeft.rotateY( Math.PI / 2 );
	scene.add( backdropLeft );

	const backdropRight = new THREE.Mesh( backdropGeometry, backdropMaterial );
	backdropRight.position.set( backdropDistance, 100, 0 );
	backdropRight.rotateY( Math.PI / 2 );
	scene.add( backdropRight );

	const backdropFront = new THREE.Mesh( backdropGeometry, backdropMaterial );
	backdropFront.position.set( 0, 100, - backdropDistance );
	scene.add( backdropFront );

	const backdropBack = new THREE.Mesh( backdropGeometry, backdropMaterial );
	backdropBack.position.set( 0, 100, backdropDistance );
	scene.add( backdropBack );

	const backdropTop = new THREE.Mesh( backdropGeometry, backdropMaterial );
	backdropTop.position.set( 0, 200, 0 );
	backdropTop.rotateX( Math.PI / 2 );
	backdropTop.scale.set( 3, 6, 1 );
	scene.add( backdropTop );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	controls.update();

	renderPipeline.render();


}

import * as THREE from 'three/webgpu';
import { pass, mrt, output, emissive, uniform, texture } from 'three/tsl';
import { bloom } from 'three/addons/tsl/display/BloomNode.js';
import { lensflare } from 'three/addons/tsl/display/LensflareNode.js';
import { gaussianBlur } from 'three/addons/tsl/display/GaussianBlurNode.js';
import { lensDirt } from 'three/addons/tsl/display/lensDirt.js';

import { UltraHDRLoader } from 'three/addons/loaders/UltraHDRLoader.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, scene, renderer, controls;
let renderPipeline;

init();

async function init() {

	//

	camera = new THREE.PerspectiveCamera( 45, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 0, 0.5, - 0.5 );

	scene = new THREE.Scene();

	const envMap = await new UltraHDRLoader().loadAsync( 'textures/equirectangular/ice_planet_close.jpg' );

	envMap.mapping = THREE.EquirectangularReflectionMapping;

	scene.background = envMap;
	scene.environment = envMap;

	scene.backgroundIntensity = 2;
	scene.environmentIntensity = 15;

	// model

	const loader = new GLTFLoader();
	const gltf = await loader.loadAsync( 'models/gltf/space_ship_hallway.glb' );

	const object = gltf.scene;

	const aabb = new THREE.Box3().setFromObject( object );
	const center = aabb.getCenter( new THREE.Vector3() );

	object.position.x += ( object.position.x - center.x );
	object.position.y += ( object.position.y - center.y );
	object.position.z += ( object.position.z - center.z );

	scene.add( object );

	//

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( render );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	//

	const scenePass = pass( scene, camera );
	scenePass.setMRT( mrt( {
		output,
		emissive
	} ) );

	const outputPass = scenePass.getTextureNode().toInspector( 'Color' );
	const emissivePass = scenePass.getTextureNode( 'emissive' ).toInspector( 'Emissive' );

	const bloomPass = bloom( emissivePass, 1, 1 ).toInspector( 'Bloom' );

	// flares

	const threshold = uniform( 0.5 );
	const ghostAttenuationFactor = uniform( 25 );
	const ghostSpacing = uniform( 0.25 );

	const flarePass = lensflare( bloomPass, {
		threshold,
		ghostAttenuationFactor,
		ghostSpacing
	} );

	const blurPass = gaussianBlur( flarePass, 8 ); // optional (blurring produces better flare quality but also adds some overhead)

	// dirt

	const lensDirtMap = new THREE.TextureLoader().load( 'textures/lensdirt.png' );
	const lensDirtIntensity = uniform( 3 );

	const dirtPass = lensDirt( bloomPass, texture( lensDirtMap ), lensDirtIntensity );

	//

	renderPipeline = new THREE.RenderPipeline( renderer );

	const params = {
		lensEffect: 'flares'
	};

	function updateOutput() {

		if ( params.lensEffect === 'flares' ) {

			renderPipeline.outputNode = outputPass.add( bloomPass ).add( blurPass );

			lensflareFolder.show();
			lensDirtFolder.hide();

		} else {

			renderPipeline.outputNode = outputPass.add( bloomPass ).add( dirtPass );

			lensflareFolder.hide();
			lensDirtFolder.show();

		}

		renderPipeline.needsUpdate = true;

	}

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.enablePan = false;
	controls.enableZoom = false;
	controls.target.copy( camera.position );
	controls.target.z -= 0.01;
	controls.update();

	window.addEventListener( 'resize', onWindowResize );

	//

	const gui = renderer.inspector.createParameters( 'Settings' );

	const bloomFolder = gui.addFolder( 'bloom' );
	bloomFolder.add( bloomPass.strength, 'value', 0.0, 2.0 ).name( 'strength' );
	bloomFolder.add( bloomPass.radius, 'value', 0.0, 1.0 ).name( 'radius' );

	gui.add( params, 'lensEffect', [ 'flares', 'dirt' ] ).name( 'lens effect' ).onChange( updateOutput );

	const lensflareFolder = gui.addFolder( 'lensflare' );
	lensflareFolder.add( threshold, 'value', 0.0, 1.0 ).name( 'threshold' );
	lensflareFolder.add( ghostAttenuationFactor, 'value', 10.0, 50.0 ).name( 'attenuation' );
	lensflareFolder.add( ghostSpacing, 'value', 0.0, 0.3 ).name( 'spacing' );

	const lensDirtFolder = gui.addFolder( 'lens dirt' );
	lensDirtFolder.add( lensDirtIntensity, 'value', 0.0, 10.0 ).name( 'intensity' );

	updateOutput();

	const toneMappingFolder = gui.addFolder( 'tone mapping' );
	toneMappingFolder.add( renderer, 'toneMappingExposure', 0.1, 2 ).name( 'exposure' );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function render() {

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, texture } from 'three/tsl';
import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, renderPipeline, renderer;
let box, torus;

init();

function init() {

	// scene

	const baseScene = new THREE.Scene();
	baseScene.background = new THREE.Color( 0xe0e0e0 );

	const maskScene1 = new THREE.Scene();
	box = new THREE.Mesh( new THREE.BoxGeometry( 4, 4, 4 ) );
	maskScene1.add( box );

	const maskScene2 = new THREE.Scene();
	torus = new THREE.Mesh( new THREE.TorusGeometry( 3, 1, 16, 32 ) );
	maskScene2.add( torus );

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 1, 1000 );
	camera.position.z = 10;

	// textures

	const texture1 = new THREE.TextureLoader().load( 'textures/758px-Canestra_di_frutta_(Caravaggio).jpg' );
	texture1.colorSpace = THREE.SRGBColorSpace;
	texture1.minFilter = THREE.LinearFilter;
	texture1.generateMipmaps = false;
	texture1.flipY = false;

	const texture2 = new THREE.TextureLoader().load( 'textures/2294472375_24a3b8ef46_o.jpg' );
	texture2.colorSpace = THREE.SRGBColorSpace;
	texture2.flipY = false;

	// renderer

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	window.addEventListener( 'resize', onWindowResize );

	// post processing

	const base = pass( baseScene, camera );
	const sceneMask1 = pass( maskScene1, camera ).a;
	const sceneMask2 = pass( maskScene2, camera ).a;

	let compose = base;
	compose = sceneMask1.mix( compose, texture( texture1 ) );
	compose = sceneMask2.mix( compose, texture( texture2 ) );

	renderPipeline = new THREE.RenderPipeline( renderer );
	renderPipeline.outputNode = compose;

}

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

function animate() {

	const time = performance.now() * 0.001 + 6000;

	box.position.x = Math.cos( time / 1.5 ) * 2;
	box.position.y = Math.sin( time ) * 2;
	box.rotation.x = time;
	box.rotation.y = time / 2;

	torus.position.x = Math.cos( time ) * 2;
	torus.position.y = Math.sin( time / 1.5 ) * 2;
	torus.rotation.x = time;
	torus.rotation.y = time / 2;

	renderPipeline.render();

}

