import * as THREE from 'three/webgpu';
import { ssaaPass } from 'three/addons/tsl/display/SSAAPassNode.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let scene, mesh, renderer, renderPipeline;
let camera, ssaaRenderPass;
let timer;

const params = {
	sampleLevel: 3,
	camera: 'perspective',
	clearColor: 'black',
	clearAlpha: 1.0,
	viewOffsetX: 0,
	autoRotate: true

};

init();

function init() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	renderer = new THREE.WebGPURenderer();
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	timer = new THREE.Timer();
	timer.connect( document );

	camera = new THREE.PerspectiveCamera( 65, width / height, 3, 10 );
	camera.position.z = 7;
	camera.setViewOffset( width, height, params.viewOffsetX, 0, width, height );

	scene = new THREE.Scene();

	const group = new THREE.Group();
	scene.add( group );

	const light = new THREE.PointLight( 0xefffef, 500 );
	light.position.z = 10;
	light.position.y = - 10;
	light.position.x = - 10;
	scene.add( light );

	const light2 = new THREE.PointLight( 0xffefef, 500 );
	light2.position.z = 10;
	light2.position.x = - 10;
	light2.position.y = 10;
	scene.add( light2 );

	const light3 = new THREE.PointLight( 0xefefff, 500 );
	light3.position.z = 10;
	light3.position.x = 10;
	light3.position.y = - 10;
	scene.add( light3 );

	const light4 = new THREE.AmbientLight( 0xffffff, 0.2 );
	scene.add( light4 );

	const geometry = new THREE.SphereGeometry( 3, 48, 24 );
	const material = new THREE.MeshStandardMaterial();

	mesh = new THREE.InstancedMesh( geometry, material, 120 );

	const dummy = new THREE.Mesh();
	const color = new THREE.Color();

	for ( let i = 0; i < mesh.count; i ++ ) {

		dummy.position.x = Math.random() * 4 - 2;
		dummy.position.y = Math.random() * 4 - 2;
		dummy.position.z = Math.random() * 4 - 2;
		dummy.rotation.x = Math.random();
		dummy.rotation.y = Math.random();
		dummy.rotation.z = Math.random();
		dummy.scale.setScalar( Math.random() * 0.2 + 0.05 );

		dummy.updateMatrix();

		color.setHSL( Math.random(), 1.0, 0.3 );

		mesh.setMatrixAt( i, dummy.matrix );
		mesh.setColorAt( i, color );

	}

	scene.add( mesh );

	// postprocessing

	renderPipeline = new THREE.RenderPipeline( renderer );

	ssaaRenderPass = ssaaPass( scene, camera );
	const scenePassColor = ssaaRenderPass.getTextureNode();

	renderPipeline.outputNode = scenePassColor;

	window.addEventListener( 'resize', onWindowResize );

	// GUI

	const gui = renderer.inspector.createParameters( 'Settings' );

	gui.add( params, 'sampleLevel', {
		'Level 0: 1 Sample': 0,
		'Level 1: 2 Samples': 1,
		'Level 2: 4 Samples': 2,
		'Level 3: 8 Samples': 3,
		'Level 4: 16 Samples': 4,
		'Level 5: 32 Samples': 5
	} );
	gui.add( params, 'clearColor', [ 'black', 'white', 'blue', 'green', 'red' ] );
	gui.add( params, 'clearAlpha', 0, 1 );
	gui.add( params, 'viewOffsetX', - 100, 100 );
	gui.add( params, 'autoRotate' );

}

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.setViewOffset( width, height, params.viewOffsetX, 0, width, height );
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

function animate() {

	timer.update();

	if ( params.autoRotate ) {

		const delta = timer.getDelta();

		mesh.rotation.x += delta * 0.25;
		mesh.rotation.y += delta * 0.5;

	}

	let newColor;

	switch ( params.clearColor ) {

		case 'blue': newColor = 0x0000ff; break;
		case 'red': newColor = 0xff0000; break;
		case 'green': newColor = 0x00ff00; break;
		case 'white': newColor = 0xffffff; break;
		case 'black': newColor = 0x000000; break;

	}

	renderer.setClearColor( newColor, params.clearAlpha );

	ssaaRenderPass.sampleLevel = params.sampleLevel;

	camera.view.offsetX = params.viewOffsetX;

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, mrt, output, normalView, diffuseColor, velocity, add, vec3, vec4, packNormalToRGB, unpackRGBToNormal, sample } from 'three/tsl';
import { ssgi } from 'three/addons/tsl/display/SSGINode.js';
import { traa } from 'three/addons/tsl/display/TRAANode.js';

import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

import { Inspector } from 'three/addons/inspector/Inspector.js';

let camera, scene, renderer, renderPipeline, controls;

init();

async function init() {

	camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 0.1, 100 );
	camera.position.set( 0, 10, 30 );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0xaaaaaa );

	renderer = new THREE.WebGPURenderer();
	//renderer.setPixelRatio( window.devicePixelRatio ); // probably too costly for most hardware
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.target.set( 0, 7, 0 );
	controls.enablePan = true;
	controls.minDistance = 1;
	controls.maxDistance = 100;
	controls.update();

	//

	renderPipeline = new THREE.RenderPipeline( renderer );

	const scenePass = pass( scene, camera );
	scenePass.setMRT( mrt( {
		output: output,
		diffuseColor: diffuseColor,
		normal: packNormalToRGB( normalView ),
		velocity: velocity
	} ) );

	const scenePassColor = scenePass.getTextureNode( 'output' );
	const scenePassDiffuse = scenePass.getTextureNode( 'diffuseColor' ).toInspector( 'Diffuse Color' );
	const scenePassDepth = scenePass.getTextureNode( 'depth' ).toInspector( 'Depth', () => {

		return scenePass.getLinearDepthNode();

	} );

	const scenePassNormal = scenePass.getTextureNode( 'normal' ).toInspector( 'Normal' );
	const scenePassVelocity = scenePass.getTextureNode( 'velocity' ).toInspector( 'Velocity' );

	// bandwidth optimization

	const diffuseTexture = scenePass.getTexture( 'diffuseColor' );
	diffuseTexture.type = THREE.UnsignedByteType;

	const normalTexture = scenePass.getTexture( 'normal' );
	normalTexture.type = THREE.UnsignedByteType;

	const sceneNormal = sample( ( uv ) => {

		return unpackRGBToNormal( scenePassNormal.sample( uv ) );

	} );

	// gi

	const giPass = ssgi( scenePassColor, scenePassDepth, sceneNormal, camera );
	giPass.sliceCount.value = 2;
	giPass.stepCount.value = 8;

	// composite

	const ao = giPass.getAONode().toInspector( 'SSGI.AO' );
	const gi = giPass.getGINode().toInspector( 'SSGI.GI' );

	const compositePass = vec4( add( scenePassColor.rgb.mul( ao ), ( scenePassDiffuse.rgb.mul( gi.rgb ) ) ), scenePassColor.a );
	compositePass.name = 'Composite';

	// traa

	const traaPass = traa( compositePass, scenePassDepth, scenePassVelocity, camera );
	renderPipeline.outputNode = traaPass;

	// Cornell Box inspired scene

	// Walls
	const wallGeometry = new THREE.PlaneGeometry( 1, 1 );

	// Left wall - red
	const redWallMaterial = new THREE.MeshPhysicalMaterial( { color: '#ff0000' } );
	const leftWall = new THREE.Mesh( wallGeometry, redWallMaterial );
	leftWall.scale.set( 20, 15, 1 );
	leftWall.rotation.y = Math.PI * 0.5;
	leftWall.position.set( - 10, 7.5, 0 );
	leftWall.receiveShadow = true;
	scene.add( leftWall );

	// Right wall - green
	const greenWallMaterial = new THREE.MeshPhysicalMaterial( { color: '#00ff00' } );
	const rightWall = new THREE.Mesh( wallGeometry, greenWallMaterial );
	rightWall.scale.set( 20, 15, 1 );
	rightWall.rotation.y = Math.PI * - 0.5;
	rightWall.position.set( 10, 7.5, 0 );
	rightWall.receiveShadow = true;
	scene.add( rightWall );

	// White walls and boxes
	const whiteMaterial = new THREE.MeshPhysicalMaterial( { color: '#fff' } );

	// Floor
	const floor = new THREE.Mesh( wallGeometry, whiteMaterial );
	floor.scale.set( 20, 20, 1 );
	floor.rotation.x = Math.PI * - .5;
	floor.receiveShadow = true;
	scene.add( floor );

	// Back wall
	const backWall = new THREE.Mesh( wallGeometry, whiteMaterial );
	backWall.scale.set( 15, 20, 1 );
	backWall.rotation.z = Math.PI * - 0.5;
	backWall.position.set( 0, 7.5, - 10 );
	backWall.receiveShadow = true;
	scene.add( backWall );

	// Ceiling
	const ceiling = new THREE.Mesh( wallGeometry, whiteMaterial );
	ceiling.scale.set( 20, 20, 1 );
	ceiling.rotation.x = Math.PI * 0.5;
	ceiling.position.set( 0, 15, 0 );
	ceiling.receiveShadow = true;
	scene.add( ceiling );

	// Boxes
	const tallBoxGeometry = new THREE.BoxGeometry( 5, 7, 5 );
	const tallBox = new THREE.Mesh( tallBoxGeometry, whiteMaterial );
	tallBox.rotation.y = Math.PI * 0.25;
	tallBox.position.set( - 3, 3.5, - 2 );
	tallBox.castShadow = true;
	tallBox.receiveShadow = true;
	scene.add( tallBox );

	const shortBoxGeometry = new THREE.BoxGeometry( 4, 4, 4 );
	const shortBox = new THREE.Mesh( shortBoxGeometry, whiteMaterial );
	shortBox.rotation.y = Math.PI * - 0.1;
	shortBox.position.set( 4, 2, 4 );
	shortBox.castShadow = true;
	shortBox.receiveShadow = true;
	scene.add( shortBox );

	// Light source geometry
	const lightSourceGeometry = new THREE.CylinderGeometry( 2.5, 2.5, 1, 64 );
	const lightSourceMaterial = new THREE.MeshBasicMaterial();
	const lightSource = new THREE.Mesh( lightSourceGeometry, lightSourceMaterial );
	lightSource.position.y = 15;
	scene.add( lightSource );

	// Point light
	const pointLight = new THREE.PointLight( '#ffffff', 100 );
	pointLight.position.set( 0, 13, 0 );
	pointLight.distance = 100;
	pointLight.castShadow = true;
	pointLight.shadow.mapSize.width = 1024;
	pointLight.shadow.mapSize.height = 1024;
	scene.add( pointLight );

	// Ambient light
	const ambientLight = new THREE.AmbientLight( '#0c0c0c' );
	scene.add( ambientLight );

	window.addEventListener( 'resize', onWindowResize );

	//

	const params = {
		output: 0
	};

	const types = { Combined: 0, Direct: 3, AO: 1, GI: 2 };

	const gui = renderer.inspector.createParameters( 'SSGI settings' );
	gui.add( params, 'output', types ).onChange( updatePostprocessing );
	gui.add( giPass.sliceCount, 'value', 1, 4, 1 ).name( 'slice count' );
	gui.add( giPass.stepCount, 'value', 1, 32, 1 ).name( 'step count' );
	gui.add( giPass.radius, 'value', 1, 25 ).name( 'radius' );
	gui.add( giPass.expFactor, 'value', 1, 3 ).name( 'exp factor' );
	gui.add( giPass.thickness, 'value', 0.01, 10 ).name( 'thickness' );
	gui.add( giPass.backfaceLighting, 'value', 0, 1 ).name( 'backface lighting' );
	gui.add( giPass.aoIntensity, 'value', 0, 4 ).name( 'AO intensity' );
	gui.add( giPass.giIntensity, 'value', 0, 100 ).name( 'GI intensity' );
	gui.add( giPass.useLinearThickness, 'value' ).name( 'use linear thickness' );
	gui.add( giPass.useScreenSpaceSampling, 'value' ).name( 'screen-space sampling' );
	gui.add( giPass, 'useTemporalFiltering' ).name( 'temporal filtering' ).onChange( updatePostprocessing );

	function updatePostprocessing( value ) {

		if ( value === 1 ) {

			renderPipeline.outputNode = vec4( vec3( ao ), 1 );

		} else if ( value === 2 ) {

			renderPipeline.outputNode = vec4( gi, 1 );

		} else if ( value === 3 ) {

			renderPipeline.outputNode = scenePassColor;

		} else {

			renderPipeline.outputNode = giPass.useTemporalFiltering ? traaPass : compositePass;

		}

		renderPipeline.needsUpdate = true;


	}


}

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

function animate() {

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, mrt, output, normalView, diffuseColor, velocity, add, vec4, packNormalToRGB, unpackRGBToNormal, sample } from 'three/tsl';
import { ssgi } from 'three/addons/tsl/display/SSGINode.js';
import { traa } from 'three/addons/tsl/display/TRAANode.js';
import { World } from '@perplexdotgg/bounce';

import { Inspector } from 'three/addons/inspector/Inspector.js';

const BALL_RADIUS = 0.4;
const FILL_RATIO = 0.4;
const PACKING = 0.6;
const BOX_HEIGHT = 6;
const BOX_DEPTH = 8;
const WALL_THICKNESS = 0.5;
const CAM_FOV = 45;
const EASE_SPEED = 8;

let camera, scene, renderer, renderPipeline;
let raycaster, pointer;
let mouseLight;

let world;
let ballCount = 0;
let bodies = [];
let ballsMesh = null;
let wallMeshes = [];
const boxSize = { w: 8, h: BOX_HEIGHT, d: BOX_DEPTH };

const mouseRayOrigin = new THREE.Vector3();
const mouseRayDir = new THREE.Vector3();
let mouseMoving = false;
let mouseStopTimer = 0;
let pointerDown = false;
const activePointers = new Set();
const mouseLightTarget = new THREE.Vector3( 0, BOX_HEIGHT / 2, BOX_DEPTH / 2 );
const mouseRayOriginTarget = new THREE.Vector3();
const mouseRayDirTarget = new THREE.Vector3();

init();

async function init() {

	camera = new THREE.PerspectiveCamera( CAM_FOV, window.innerWidth / window.innerHeight, 0.1, 100 );

	scene = new THREE.Scene();

	renderer = new THREE.WebGPURenderer( { antialias: false } );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 0.5;
	renderer.shadowMap.enabled = true;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	//

	renderPipeline = new THREE.RenderPipeline( renderer );

	const scenePass = pass( scene, camera );
	scenePass.setMRT( mrt( {
		output: output,
		diffuseColor: diffuseColor,
		normal: packNormalToRGB( normalView ),
		velocity: velocity
	} ) );

	const scenePassColor = scenePass.getTextureNode( 'output' );
	const scenePassDiffuse = scenePass.getTextureNode( 'diffuseColor' );
	const scenePassDepth = scenePass.getTextureNode( 'depth' );
	const scenePassNormal = scenePass.getTextureNode( 'normal' );
	const scenePassVelocity = scenePass.getTextureNode( 'velocity' );

	// bandwidth optimization

	const diffuseTexture = scenePass.getTexture( 'diffuseColor' );
	diffuseTexture.type = THREE.UnsignedByteType;

	const normalTexture = scenePass.getTexture( 'normal' );
	normalTexture.type = THREE.UnsignedByteType;

	const sceneNormal = sample( ( uv ) => {

		return unpackRGBToNormal( scenePassNormal.sample( uv ) );

	} );

	// gi

	const giPass = ssgi( scenePassColor, scenePassDepth, sceneNormal, camera );
	giPass.sliceCount.value = 2;
	giPass.stepCount.value = 8;

	// composite

	const ao = giPass.getAONode().toInspector( 'SSGI.AO' );
	const gi = giPass.getGINode().toInspector( 'SSGI.GI' );

	const compositePass = vec4(
		add( scenePassColor.rgb.mul( ao ), scenePassDiffuse.rgb.mul( gi.rgb ) ),
		scenePassColor.a
	);

	// traa

	const traaPass = traa( compositePass, scenePassDepth, scenePassVelocity, camera );
	renderPipeline.outputNode = traaPass;

	// light

	mouseLight = new THREE.PointLight( 0xffffff, 80 );
	mouseLight.position.set( 0, BOX_HEIGHT / 2, BOX_DEPTH / 2 );
	mouseLight.castShadow = true;
	mouseLight.shadow.mapSize.set( 1024, 1024 );
	mouseLight.shadow.radius = 20;
	scene.add( mouseLight );

	//

	raycaster = new THREE.Raycaster();
	pointer = new THREE.Vector2();

	rebuildScene();

	//

	renderer.domElement.addEventListener( 'pointerdown', onPointerDown );
	renderer.domElement.addEventListener( 'pointermove', onPointerMove );
	renderer.domElement.addEventListener( 'pointerup', onPointerUp );
	renderer.domElement.addEventListener( 'pointercancel', onPointerUp );
	window.addEventListener( 'resize', onWindowResize );

}

function getBoxWidth() {

	const aspect = window.innerWidth / window.innerHeight;
	const vFov = THREE.MathUtils.degToRad( CAM_FOV / 2 );
	const dist = ( BOX_HEIGHT / 2 ) / Math.tan( vFov );
	return Math.tan( vFov ) * aspect * dist * 2;

}

function getBallCount() {

	const roomVolume = boxSize.w * boxSize.h * boxSize.d;
	const ballVolume = ( 4 / 3 ) * Math.PI * Math.pow( BALL_RADIUS, 3 );
	return Math.floor( roomVolume * FILL_RATIO * PACKING / ballVolume );

}

function rebuildScene() {

	for ( const mesh of wallMeshes ) {

		scene.remove( mesh );
		mesh.geometry.dispose();

	}

	wallMeshes = [];

	if ( ballsMesh ) {

		scene.remove( ballsMesh );
		ballsMesh.dispose();
		ballsMesh = null;

	}

	bodies = [];

	boxSize.w = getBoxWidth();
	ballCount = getBallCount();

	world = new World( {
		gravity: [ 0, - 9.81, 0 ],
		solveVelocityIterations: 6,
		solvePositionIterations: 2,
		linearDamping: 0.1,
		angularDamping: 0.1,
		restitution: 0.4,
		friction: 0.5
	} );

	fitCameraToBox();
	createBox();
	createBalls();

}

function createBox() {

	const hw = boxSize.w / 2;
	const hh = boxSize.h / 2;
	const hd = boxSize.d / 2;
	const t = WALL_THICKNESS;

	const whiteMaterial = new THREE.MeshPhysicalMaterial( {
		color: 0xeeeeee,
		roughness: 0.7,
		metalness: 0.0
	} );

	const redMaterial = new THREE.MeshPhysicalMaterial( {
		color: 0xff2222,
		roughness: 0.7,
		metalness: 0.0
	} );

	const greenMaterial = new THREE.MeshPhysicalMaterial( {
		color: 0x22ff22,
		roughness: 0.7,
		metalness: 0.0
	} );

	const walls = [
		{ size: [ boxSize.w, t, boxSize.d ], pos: [ 0, - t / 2, 0 ], mat: whiteMaterial },
		{ size: [ boxSize.w, t, boxSize.d ], pos: [ 0, boxSize.h + t / 2, 0 ], mat: whiteMaterial },
		{ size: [ boxSize.w, boxSize.h, t ], pos: [ 0, hh, - hd - t / 2 ], mat: whiteMaterial },
		{ size: [ boxSize.w, boxSize.h, t ], pos: [ 0, hh, hd + t / 2 ], noMesh: true },
		{ size: [ t, boxSize.h, boxSize.d ], pos: [ - hw - t / 2, hh, 0 ], mat: redMaterial },
		{ size: [ t, boxSize.h, boxSize.d ], pos: [ hw + t / 2, hh, 0 ], mat: greenMaterial }
	];

	for ( const w of walls ) {

		const shape = world.createBox( { width: w.size[ 0 ], height: w.size[ 1 ], depth: w.size[ 2 ] } );
		world.createStaticBody( { shape, position: w.pos } );

		if ( ! w.noMesh ) {

			const geo = new THREE.BoxGeometry( w.size[ 0 ], w.size[ 1 ], w.size[ 2 ] );
			const mesh = new THREE.Mesh( geo, w.mat );
			mesh.position.set( ...w.pos );
			mesh.receiveShadow = true;
			scene.add( mesh );
			wallMeshes.push( mesh );

		}

	}

}

function createBalls() {

	const sphereGeo = new THREE.SphereGeometry( BALL_RADIUS, 32, 16 );
	const sphereShape = world.createSphere( { radius: BALL_RADIUS } );

	const material = new THREE.MeshPhysicalMaterial( {
		roughness: 0.3,
		metalness: 0.1
	} );

	ballsMesh = new THREE.InstancedMesh( sphereGeo, material, ballCount );
	ballsMesh.castShadow = true;
	ballsMesh.receiveShadow = true;
	scene.add( ballsMesh );

	const colors = [
		0xff4444, 0x44ff44, 0x4488ff, 0xffaa00, 0xff44ff,
		0x44ffff, 0xffff44, 0xff8844, 0x8844ff, 0x44ff88
	];

	const color = new THREE.Color();
	const hw = boxSize.w / 2 - BALL_RADIUS - 0.1;
	const hd = boxSize.d / 2 - BALL_RADIUS - 0.1;

	for ( let i = 0; i < ballCount; i ++ ) {

		color.set( colors[ i % colors.length ] );
		ballsMesh.setColorAt( i, color );

		const x = ( Math.random() - 0.5 ) * 2 * hw;
		const y = BALL_RADIUS + Math.random() * ( boxSize.h - BALL_RADIUS * 2 );
		const z = ( Math.random() - 0.5 ) * 2 * hd;

		const body = world.createDynamicBody( {
			shape: sphereShape,
			position: [ x, y, z ],
			mass: 1,
			restitution: 0.5,
			friction: 0.4
		} );

		bodies.push( body );

	}

}

function onPointerDown( event ) {

	activePointers.add( event.pointerId );

	if ( event.pointerType === 'touch' ) {

		pointerDown = activePointers.size >= 2;

	} else {

		pointerDown = true;

	}

}

function onPointerUp( event ) {

	activePointers.delete( event.pointerId );

	if ( event.pointerType === 'touch' ) {

		pointerDown = activePointers.size >= 2;

	} else {

		pointerDown = false;

	}

}

function onPointerMove( event ) {

	pointer.x = ( event.clientX / window.innerWidth ) * 2 - 1;
	pointer.y = - ( event.clientY / window.innerHeight ) * 2 + 1;

	raycaster.setFromCamera( pointer, camera );

	mouseRayOriginTarget.copy( raycaster.ray.origin );
	mouseRayDirTarget.copy( raycaster.ray.direction );
	mouseMoving = true;
	clearTimeout( mouseStopTimer );
	mouseStopTimer = setTimeout( () => mouseMoving = false, 50 );

	const frontPlane = new THREE.Plane( new THREE.Vector3( 0, 0, 1 ), - boxSize.d / 2 );
	const hit = new THREE.Vector3();
	if ( raycaster.ray.intersectPlane( frontPlane, hit ) ) {

		mouseLightTarget.copy( hit );

	}

}

function respawnBalls() {

	const hw = boxSize.w / 2 - BALL_RADIUS - 0.1;
	const hd = boxSize.d / 2 - BALL_RADIUS - 0.1;
	const count = 5;

	for ( let i = 0; i < count; i ++ ) {

		const body = bodies[ Math.floor( Math.random() * bodies.length ) ];

		body.position.set( [
			( Math.random() - 0.5 ) * 2 * hw,
			boxSize.h - BALL_RADIUS - Math.random() * 1,
			( Math.random() - 0.5 ) * 2 * hd
		] );
		body.linearVelocity.set( [ 0, 0, 0 ] );
		body.angularVelocity.set( [ 0, 0, 0 ] );
		body.commitChanges();

	}

}

function fitCameraToBox() {

	const vFov = THREE.MathUtils.degToRad( CAM_FOV / 2 );
	const dist = ( boxSize.h / 2 ) / Math.tan( vFov );

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.position.set( 0, boxSize.h / 2, dist + boxSize.d / 2 );
	camera.lookAt( 0, boxSize.h / 2, 0 );
	camera.updateProjectionMatrix();

}

function onWindowResize() {

	renderer.setSize( window.innerWidth, window.innerHeight );
	rebuildScene();

}

const timer = new THREE.Timer();
const _dummy = new THREE.Object3D();

function animate() {

	timer.update();
	const dt = Math.min( timer.getDelta(), 1 / 30 );

	const easeFactor = 1 - Math.exp( - EASE_SPEED * dt );
	mouseRayOrigin.lerp( mouseRayOriginTarget, easeFactor );
	mouseRayDir.lerp( mouseRayDirTarget, easeFactor );
	mouseLight.position.lerp( mouseLightTarget, easeFactor );

	if ( pointerDown ) {

		respawnBalls();

	}

	if ( mouseMoving ) {

		const pushRadius = 1.5;
		const pushStrength = 15;
		const _closest = new THREE.Vector3();
		const _ballPos = new THREE.Vector3();
		const _pushDir = new THREE.Vector3();

		for ( const body of bodies ) {

			const bp = body.position;
			_ballPos.set( bp.x, bp.y, bp.z );

			const ray = new THREE.Ray( mouseRayOrigin, mouseRayDir );
			ray.closestPointToPoint( _ballPos, _closest );

			const dist = _closest.distanceTo( _ballPos );

			if ( dist < pushRadius ) {

				_pushDir.subVectors( _ballPos, _closest );
				if ( _pushDir.lengthSq() < 0.001 ) _pushDir.set( 0, 1, 0 );
				_pushDir.normalize();

				const strength = pushStrength * ( 1 - dist / pushRadius );
				body.applyLinearImpulse( {
					x: _pushDir.x * strength,
					y: _pushDir.y * strength,
					z: _pushDir.z * strength
				} );

			}

		}

	}

	if ( world ) {

		world.advanceTime( 1 / 60, dt );

	}

	for ( let i = 0; i < bodies.length; i ++ ) {

		const body = bodies[ i ];
		const p = body.position;
		const q = body.orientation;

		_dummy.position.set( p.x, p.y, p.z );
		_dummy.quaternion.set( q.x, q.y, q.z, q.w );
		_dummy.updateMatrix();

		ballsMesh.setMatrixAt( i, _dummy.matrix );

	}

	ballsMesh.instanceMatrix.needsUpdate = true;

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, mrt, output, normalView, metalness, roughness, screenUV, color, sample, packNormalToRGB, unpackRGBToNormal, vec2, colorSpaceToWorking } from 'three/tsl';
import { ssr } from 'three/addons/tsl/display/SSRNode.js';
import { smaa } from 'three/addons/tsl/display/SMAANode.js';

import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { Inspector } from 'three/addons/inspector/Inspector.js';

const params = {
	quality: 0.5,
	blurQuality: 1,
	maxDistance: 1,
	intensity: 1,
	thickness: 0.03,
	binaryRefine: false,
	roughness: 1,
	enabled: true
};

let camera, scene, model, renderer, renderPipeline, ssrPass;
let controls;

init();

async function init() {

	camera = new THREE.PerspectiveCamera( 35, window.innerWidth / window.innerHeight, 0.1, 50 );
	camera.position.set( 3, 2, 3 );

	scene = new THREE.Scene();
	scene.backgroundNode = screenUV.distance( .5 ).remap( 0, 0.5 ).mix( color( 0x888877 ), color( 0x776666 ) );

	const dracoLoader = new DRACOLoader();

	const loader = new GLTFLoader();
	loader.setDRACOLoader( dracoLoader );
	loader.load( 'models/gltf/steampunk_camera.glb', function ( gltf ) {

		model = gltf.scene;

		model.traverse( function ( object ) {

			if ( object.material ) {

				if ( object.material.name === 'Lense_Casing' ) {

					object.material.transparent = true;

				}

				// Avoid overdrawing
				object.material.side = THREE.FrontSide;

			}

		} );

		model.position.y = 0.1;
		scene.add( model );

	} );

	// Add a reflective plane under the camera

	const floorGeometry = new THREE.CircleGeometry( 2, 64 );
	const floorMaterial = new THREE.MeshStandardMaterial( {
		color: 0xffffff,
		metalness: 1,
		roughness: 0.5
	} );
	const floor = new THREE.Mesh( floorGeometry, floorMaterial );
	floor.rotation.x = - Math.PI / 2;
	floor.position.y = - 0.8;
	scene.add( floor );

	//

	renderer = new THREE.WebGPURenderer();
	// renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	const environment = new RoomEnvironment();
	const pmremGenerator = new THREE.PMREMGenerator( renderer );

	scene.environment = pmremGenerator.fromScene( environment, 0.04 ).texture;
	scene.environmentIntensity = 1.25;
	pmremGenerator.dispose();

	//

	renderPipeline = new THREE.RenderPipeline( renderer );

	const scenePass = pass( scene, camera );
	scenePass.setMRT( mrt( {
		output: output,
		normal: packNormalToRGB( normalView ),
		metalrough: vec2( metalness, roughness ) // pack metalness and roughness into a single attachment
	} ) );

	const scenePassColor = scenePass.getTextureNode( 'output' ).toInspector( 'Color' );
	const scenePassNormal = scenePass.getTextureNode( 'normal' ).toInspector( 'Normal', ( node ) => {

		return colorSpaceToWorking( node, THREE.SRGBColorSpace );

	} );
	const scenePassDepth = scenePass.getTextureNode( 'depth' ).toInspector( 'Depth', () => {

		return scenePass.getLinearDepthNode();

	} );
	const scenePassMetalRough = scenePass.getTextureNode( 'metalrough' ).toInspector( 'Metalness-Roughness' );

	// optional: optimize bandwidth by reducing the texture precision for normals and metal/roughness

	const normalTexture = scenePass.getTexture( 'normal' );
	normalTexture.type = THREE.UnsignedByteType;

	const metalRoughTexture = scenePass.getTexture( 'metalrough' );
	metalRoughTexture.type = THREE.UnsignedByteType;

	const sceneNormal = sample( ( uv ) => {

		return unpackRGBToNormal( scenePassNormal.sample( uv ) );

	} );

	//

	ssrPass = ssr( scenePassColor, scenePassDepth, sceneNormal, {
		metalnessNode: scenePassMetalRough.r,
		roughnessNode: scenePassMetalRough.g
	} ).toInspector( 'SSR' );

	// blend SSR over beauty (SSR outputs premultiplied color, so use additive blending)

	const outputNode = smaa( scenePassColor.add( ssrPass.rgb ) );

	renderPipeline.outputNode = outputNode;

	//

	controls = new OrbitControls( camera, renderer.domElement );
	controls.enableDamping = true;
	controls.update();

	window.addEventListener( 'resize', onWindowResize );

	// GUI

	const gui = renderer.inspector.createParameters( 'Settings' );
	const ssrFolder = gui.addFolder( 'SSR' );
	ssrFolder.add( params, 'quality', 0, 1 ).onChange( updateParameters );
	ssrFolder.add( params, 'blurQuality', 1, 3, 1 ).onChange( updateParameters );
	ssrFolder.add( params, 'maxDistance', 0, 1 ).onChange( updateParameters );
	ssrFolder.add( params, 'intensity', 0, 1 ).onChange( updateParameters );
	ssrFolder.add( params, 'thickness', 0, 0.05 ).onChange( updateParameters );
	ssrFolder.add( params, 'binaryRefine' ).name( 'binary refine' ).onChange( updateParameters );
	ssrFolder.add( params, 'enabled' ).onChange( () => {

		if ( params.enabled === true ) {

			renderPipeline.outputNode = outputNode;

		} else {

			renderPipeline.outputNode = scenePass;

		}

		renderPipeline.needsUpdate = true;

	} );
	const modelFolder = gui.addFolder( 'Model' );
	modelFolder.add( params, 'roughness', 0, 1 ).onChange( ( value ) => {

		model.traverse( function ( object ) {

			if ( object.material ) {

				object.material.roughness = value;

			}

		} );

	} );

	updateParameters();

}

function updateParameters() {

	ssrPass.quality.value = params.quality;
	// blurQuality is a build-time constant: assigning it recompiles the blur material
	// (the setter no-ops when the value is unchanged).
	ssrPass.blurQuality = params.blurQuality;
