		return mx_fractal_noise_vec3( positionWorld.mul( 2 ) ).saturate().zzz.mul( 0.2 ).add( .5 );

	} )();

	const ground = new THREE.Mesh( planeGeometry, planeMaterial );
	ground.rotation.x = - Math.PI / 2;
