	gradientMap.minFilter = THREE.NearestFilter;
	gradientMap.magFilter = THREE.NearestFilter;
	gradientMap.generateMipmaps = false;

	const wallParameters = {
		gradientMap,
		maskNode: threshold.greaterThanEqual( occlusionCut ),
		maskShadowNode: bool( true ) // keep full shadows
	};

	const wallMaterials = [ '#9fb2c6', '#8aa0b8', '#b3c2d2' ].map( ( color ) => new THREE.MeshToonNodeMaterial( { ...wallParameters, color } ) );
	const pillarMaterial = new THREE.MeshToonNodeMaterial( { ...wallParameters, color: '#5f7690' } );

