	const loader = new GLTFLoader();
	loader.setDRACOLoader( dracoLoader );

	loader.load( 'models/gltf/LittlestTokyo.glb', function ( gltf ) {

		const model = gltf.scene;
		model.scale.set( 0.01, 0.01, 0.01 );
		scene.add( model );

