	backWall.position.set( 0, 7.5, - 10 );
	backWall.receiveShadow = true;
	scene.add( backWall );

	// Ceiling
	const ceiling = new THREE.Mesh( wallGeometry, whiteMaterial );
	ceiling.scale.set( 20, 20, 1 );
	ceiling.rotation.x = Math.PI * 0.5;
	ceiling.position.set( 0, 14.999, 0 );
	ceiling.receiveShadow = true;
	scene.add( ceiling );

	// Boxes
	const tallBoxGeometry = new THREE.BoxGeometry( 5, 7, 5 );
	const tallBox = new THREE.Mesh( tallBoxGeometry, whiteMaterial );
	tallBox.rotation.y = Math.PI * 0.25;
	tallBox.position.set( - 3, 3.5, - 2 );
	tallBox.castShadow = true;
	tallBox.receiveShadow = true;
	scene.add( tallBox );

	const shortBoxGeometry = new THREE.BoxGeometry( 4, 4, 4 );
	const shortBox = new THREE.Mesh( shortBoxGeometry, whiteMaterial );
	shortBox.rotation.y = Math.PI * - 0.1;
	shortBox.position.set( 4, 2, 4 );
	shortBox.castShadow = true;
	shortBox.receiveShadow = true;
	scene.add( shortBox );

	// Light source geometry (unlit materials are injected as emitters)
	const lightSourceGeometry = new THREE.CylinderGeometry( 2.5, 2.5, 1, 64 );
	const lightSourceMaterial = new THREE.MeshBasicMaterial();
	const lightSource = new THREE.Mesh( lightSourceGeometry, lightSourceMaterial );
	lightSource.position.y = 15;
	scene.add( lightSource );

	// Point light
	const pointLight = new THREE.PointLight( '#ffffff', 100 );
	pointLight.position.set( 0, 13, 0 );
	pointLight.distance = 100;
	pointLight.castShadow = true;
	pointLight.shadow.mapSize.width = 1024;
	pointLight.shadow.mapSize.height = 1024;
	scene.add( pointLight );

	// Ambient light
	const ambientLight = new THREE.AmbientLight( '#0c0c0c' );
	scene.add( ambientLight );

	window.addEventListener( 'resize', onWindowResize );

	//

	const params = {
		output: 0,
		debug: 0,
		lightX: 0,
		lightZ: 0
	};

	const types = { Combined: 0, Direct: 3, AO: 1, GI: 2 };
	const debugTypes = { Off: 0, Radiance: 1, Opacity: 2 };

	const gui = renderer.inspector.createParameters( 'VXGI Settings' );
	gui.add( params, 'output', types ).onChange( updatePostprocessing );
	gui.add( params, 'debug', debugTypes ).name( 'voxel view' ).onChange( updatePostprocessing );
	gui.add( giPass.debugLevel, 'value', 0, 4, 1 ).name( 'voxel view level' );
	gui.add( giPass.coneCount, 'value', 2, 8, 1 ).name( 'cone count' );
	gui.add( giPass.coneAngle, 'value', 10, 90 ).name( 'cone angle' );
	gui.add( giPass.volume.stepScale, 'value', 0.25, 2 ).name( 'step scale' );
	gui.add( giPass.volume.maxDistance, 'value', 0, 50 ).name( 'max distance' );
	gui.add( giPass.normalOffset, 'value', 0, 4 ).name( 'normal offset' );
	gui.add( giPass.giIntensity, 'value', 0, 4 ).name( 'GI intensity' );
	gui.add( giPass, 'bounces', 0, 2, 1 ).name( 'bounces' );
	gui.add( giPass, 'directionalRadiance' ).name( 'directional radiance' );
	gui.add( giPass, 'useTemporalFiltering' ).name( 'temporal filtering' ).onChange( updatePostprocessing );

	function updatePostprocessing() {

		giPass.debug.value = params.debug;

		if ( params.debug !== 0 ) {

			renderPipeline.outputNode = vec4( gi.rgb, 1 );

		} else if ( params.output === 1 ) {

			renderPipeline.outputNode = vec4( vec3( ao ), 1 );

		} else if ( params.output === 2 ) {

			renderPipeline.outputNode = vec4( gi.rgb, 1 );

		} else if ( params.output === 3 ) {

			renderPipeline.outputNode = scenePass;

		} else {

			renderPipeline.outputNode = giPass.useTemporalFiltering ? traaPass : scenePass;

		}

		// direct lighting only: render the scene without the GI context

		scenePass.contextNode = ( params.output === 3 ) ? null : giContext;
		scenePass.needsUpdate = true;

		renderPipeline.needsUpdate = true;

	}

}

function onWindowResize() {

	const width = window.innerWidth;
	const height = window.innerHeight;

	camera.aspect = width / height;
	camera.updateProjectionMatrix();

	renderer.setSize( width, height );

}

function animate() {

	controls.update();

	renderPipeline.render();

}

import * as THREE from 'three/webgpu';
import { pass, mrt, normalView, velocity, vec3, vec4, packNormalToRGB, unpackRGBToNormal, sample, screenUV, builtinGIContext } from 'three/tsl';
import { vxgi } from 'three/addons/lighting/vxgi/VXGINode.js';
import { traa } from 'three/addons/tsl/display/TRAANode.js';

import { FirstPersonControls } from 'three/addons/controls/FirstPersonControls.js';
import { Inspector } from 'three/addons/inspector/Inspector.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { SkyMesh } from 'three/addons/objects/SkyMesh.js';
import WebGPU from 'three/addons/capabilities/WebGPU.js';

const MODEL_INDEX_URL = 'https://raw.githubusercontent.com/KhronosGroup/glTF-Sample-Assets/main/Models/model-index.json';
const SAMPLE_ASSETS_BASE_URL = 'https://raw.githubusercontent.com/KhronosGroup/glTF-Sample-Assets/main/Models/';

let camera, scene, renderer, renderPipeline, controls, timer;
let dirLight = null, sky = null;

const sun = new THREE.Vector3();

const _box = new THREE.Box3();
const _size = new THREE.Vector3();
const _center = new THREE.Vector3();

if ( WebGPU.isAvailable() === false ) {

	document.body.appendChild( WebGPU.getErrorMessage() );

	throw new Error( 'No WebGPU support' );

}

init();

async function init() {

	timer = new THREE.Timer();

	camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 0.1, 1000 );
	camera.position.set( - 10.25, 4.99, 0.40 );
	camera.rotation.set( 1.6505, - 1.5008, 1.6507 );

	scene = new THREE.Scene();

	sky = new SkyMesh();
	sky.scale.setScalar( 450000 );
	sky.turbidity.value = 10;
	sky.rayleigh.value = 2;
	sky.mieCoefficient.value = 0.005;
	sky.mieDirectionalG.value = 0.8;
	scene.add( sky );

	renderer = new THREE.WebGPURenderer();
	// renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 1.0;
	renderer.inspector = new Inspector();
	document.body.appendChild( renderer.domElement );

	await renderer.init();

	controls = new FirstPersonControls( camera, renderer.domElement );
	controls.movementSpeed = 2.0;
	controls.lookSpeed = 0.2;

	const progressBar = document.getElementById( 'progressBar' );

	const manager = new THREE.LoadingManager();
	manager.onProgress = function ( url, loaded, total ) {

		progressBar.value = loaded / total * 100;

	};

	manager.onLoad = function () {

		progressBar.remove();

	};

	const loader = new GLTFLoader( manager );
	const modelURL = await getSponzaModelURL();
	const gltf = await loader.loadAsync( modelURL );
	const model = gltf.scene;
	const embeddedLights = [];

	model.traverse( ( child ) => {

		if ( child.isMesh ) {

			child.castShadow = true;
			child.receiveShadow = true;

		} else if ( child.isLight ) {

			embeddedLights.push( child );

		}

	} );

	for ( const light of embeddedLights ) {

		if ( light.parent ) light.parent.remove( light );

	}

	scene.add( model );

	_box.setFromObject( model );
	const modelSize = _box.getSize( _size ).clone();
	const modelCenter = _box.getCenter( _center ).clone();
	const targetY = modelCenter.y + modelSize.y * 0.2;
	const lightBaseDistance = Math.max( modelSize.x, modelSize.z );

	dirLight = new THREE.DirectionalLight( 0xfff2dc, 100.0 );
	dirLight.target.position.set( modelCenter.x, targetY, modelCenter.z );
	scene.add( dirLight.target );
	dirLight.castShadow = true;
	dirLight.shadow.mapSize.setScalar( 2048 );
	const shadowExtent = Math.max( modelSize.x, modelSize.z ) * 0.7;
	dirLight.shadow.camera.left = - shadowExtent;
	dirLight.shadow.camera.right = shadowExtent;
	dirLight.shadow.camera.top = shadowExtent;
	dirLight.shadow.camera.bottom = - shadowExtent;
	dirLight.shadow.camera.near = 0.1;
	dirLight.shadow.camera.far = modelSize.y * 4.0;
	scene.add( dirLight );

	// A subtle ambient light fills areas that end up too dark.
	// The respective irradiance is modulated by the AO of the GI pass.

	const ambientLight = new THREE.AmbientLight( 0xffffff, 0.5 );
	scene.add( ambientLight );


	// post processing

	renderPipeline = new THREE.RenderPipeline( renderer );

	// pre-pass

	const prePass = pass( scene, camera );
	prePass.name = 'Pre-Pass';
	prePass.transparent = false;

	prePass.setMRT( mrt( {
		output: packNormalToRGB( normalView ),
		velocity: velocity
	} ) );

	const prePassNormal = sample( ( uv ) => {

		return unpackRGBToNormal( prePass.getTextureNode().sample( uv ) );

	} );

	const prePassDepth = prePass.getTextureNode( 'depth' ).toInspector( 'Depth', () => prePass.getLinearDepthNode() );
	const prePassVelocity = prePass.getTextureNode( 'velocity' ).toInspector( 'Velocity' );

	// pre-pass - bandwidth optimization

	const normalTexture = prePass.getTexture( 'output' );
	normalTexture.type = THREE.UnsignedByteType;

	// gi

	const giPass = vxgi( prePassDepth, prePassNormal, scene, camera );
	giPass.giIntensity.value = 1.5;

	const ao = giPass.getAONode().toInspector( 'VXGI.AO' );
	const gi = giPass.getGINode().toInspector( 'VXGI.GI' );

	// scene pass: AO and indirect irradiance are injected into the materials' lighting

	const scenePass = pass( scene, camera ).toInspector( 'Color' );
	const giContext = builtinGIContext( ao.sample( screenUV ).r, gi.sample( screenUV ).rgb );
	scenePass.contextNode = giContext;

	// traa ( resolves the temporal noise of the cone tracing )

	const traaPass = traa( scenePass, prePassDepth, prePassVelocity, camera );
	renderPipeline.outputNode = traaPass;

	//

	const params = {
		output: 0,
		debug: 0,
		lightAzimuth: 135,
		lightElevation: 55,
		lightIntensity: 100.0
	};

	function updateLightPosition() {

		const elevation = THREE.MathUtils.degToRad( params.lightElevation );
		const azimuth = THREE.MathUtils.degToRad( params.lightAzimuth );

		sun.setFromSphericalCoords( 1, Math.PI / 2 - elevation, azimuth );
		sky.sunPosition.value.copy( sun );

		dirLight.target.position.set( modelCenter.x, targetY, modelCenter.z );
		dirLight.position.copy( dirLight.target.position ).addScaledVector( sun, lightBaseDistance );
		dirLight.target.updateMatrixWorld();

	}

	updateLightPosition();

	const types = { Combined: 0, Direct: 3, AO: 1, GI: 2 };
	const debugTypes = { Off: 0, Radiance: 1, Opacity: 2 };

	const gui = renderer.inspector.createParameters( 'VXGI Settings' );

	const effectFolder = gui.addFolder( 'Effect Settings' );
	effectFolder.add( params, 'output', types ).onChange( updatePostprocessing );
	effectFolder.add( params, 'debug', debugTypes ).name( 'voxel view' ).onChange( updatePostprocessing );
	effectFolder.add( giPass.debugLevel, 'value', 0, 4, 1 ).name( 'voxel view level' );
	effectFolder.add( giPass.coneCount, 'value', 2, 8, 1 ).name( 'cone count' );
	effectFolder.add( giPass.coneAngle, 'value', 10, 90 ).name( 'cone angle' );
	effectFolder.add( giPass.volume.stepScale, 'value', 0.25, 2 ).name( 'step scale' );
	effectFolder.add( giPass.volume.maxDistance, 'value', 0, 50 ).name( 'max distance' );
	effectFolder.add( giPass.normalOffset, 'value', 0, 4 ).name( 'normal offset' );
	effectFolder.add( giPass.aoDistance, 'value', 0.1, 10 ).name( 'AO distance' );
	effectFolder.add( giPass.aoIntensity, 'value', 0, 4 ).name( 'AO intensity' );
	effectFolder.add( giPass.aoMinVisibility, 'value', 0, 1 ).name( 'AO min visibility' );
	effectFolder.add( giPass.giIntensity, 'value', 0, 4 ).name( 'GI intensity' );
	effectFolder.add( giPass, 'bounces', 0, 2, 1 ).name( 'bounces' );
	effectFolder.add( giPass, 'directionalRadiance' ).name( 'directional radiance' );
	effectFolder.add( giPass, 'useTemporalFiltering' ).name( 'temporal filtering' ).onChange( updatePostprocessing );

	const lightingFolder = gui.addFolder( 'Light Settings' );
	lightingFolder.add( params, 'lightAzimuth', - 180, 180, 1 ).name( 'Light Azimuth' ).onChange( updateLightPosition );
	lightingFolder.add( params, 'lightElevation', 5, 85, 1 ).name( 'Light Elevation' ).onChange( updateLightPosition );
	lightingFolder.add( params, 'lightIntensity', 0, 100, 0.1 ).name( 'Light Intensity' ).onChange( ( value ) => {

		dirLight.intensity = value;

	} );
	lightingFolder.add( ambientLight, 'intensity', 0, 1, 0.01 ).name( 'Ambient Intensity' );

	function updatePostprocessing() {

		giPass.debug.value = params.debug;

		if ( params.debug !== 0 ) {

			renderPipeline.outputNode = vec4( gi.rgb, 1 );

		} else if ( params.output === 1 ) {

			renderPipeline.outputNode = vec4( vec3( ao ), 1 );

		} else if ( params.output === 2 ) {

			renderPipeline.outputNode = vec4( gi.rgb, 1 );

		} else if ( params.output === 3 ) {

			renderPipeline.outputNode = scenePass;

		} else {

			renderPipeline.outputNode = giPass.useTemporalFiltering ? traaPass : scenePass;

		}

		// direct lighting only: render the scene without the GI context

		scenePass.contextNode = ( params.output === 3 ) ? null : giContext;
		scenePass.needsUpdate = true;

		renderPipeline.needsUpdate = true;

	}

	window.addEventListener( 'resize', onWindowResize );

}

async function getSponzaModelURL() {

	const response = await fetch( MODEL_INDEX_URL );
	const models = await response.json();
	const sponzaInfo = models.find( ( model ) => model.name === 'Sponza' );

	if ( ! sponzaInfo ) {

		throw new Error( 'Sponza entry was not found in the glTF sample model index.' );

	}

	const variants = sponzaInfo.variants || {};
	const variantName = variants[ 'glTF-Binary' ] || variants[ 'glTF' ] || variants[ 'glTF-Embedded' ] || Object.values( variants )[ 0 ];

	if ( ! variantName ) {

		throw new Error( 'Sponza has no supported glTF variant in the model index.' );

	}

	const variantFolder = variantName.endsWith( '.glb' ) ? 'glTF-Binary' : 'glTF';
	return `${ SAMPLE_ASSETS_BASE_URL }${ sponzaInfo.name }/${ variantFolder }/${ variantName }`;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate( timestamp ) {

	timer.update( timestamp );
	controls.update( timer.getDelta() );

	if ( renderPipeline ) renderPipeline.render();

}

import * as THREE from 'three/webgpu';

import { pass, mrt, output, emissive, renderOutput } from 'three/tsl';
import { bloom } from 'three/addons/tsl/display/BloomNode.js';
