import {
	RollerCoasterGeometry,
	RollerCoasterShadowGeometry,
	RollerCoasterLiftersGeometry,
	TreesGeometry,
	SkyGeometry
} from 'three/addons/misc/RollerCoaster.js';
import { VRButton } from 'three/addons/webxr/VRButton.js';
import { setupWebGLXRFallback } from 'three/addons/webxr/WebGLXRFallback.js';

let mesh, material, geometry;
let renderer, renderPipeline;

const rendererParameters = { antialias: true, outputBufferType: THREE.UnsignedByteType, multiview: false };

renderer = createRenderer();
setRenderer( renderer );
setupWebGLXRFallback( renderer, () => createRenderer( true ), setRenderer );

document.body.appendChild( VRButton.createButton( renderer, { optionalFeatures: [ 'webgpu' ] } ) );

//

function createRenderer( forceWebGL = false ) {

	const parameters = { ...rendererParameters };

	if ( forceWebGL === true ) parameters.forceWebGL = true;

	const renderer = new THREE.WebGPURenderer( parameters );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.xr.enabled = true;
	renderer.xr.setReferenceSpaceType( 'local' );

	return renderer;

}

function setRenderer( newRenderer, oldRenderer = null ) {

	if ( oldRenderer === null ) {

		document.body.appendChild( newRenderer.domElement );

	} else {

		document.body.replaceChild( newRenderer.domElement, oldRenderer.domElement );
		oldRenderer.dispose();

	}

	renderer = newRenderer;
	renderPipeline = new THREE.DirectRenderPipeline( renderer );

}

const scene = new THREE.Scene();
scene.background = new THREE.Color( 0xf0f0ff );

const light = new THREE.HemisphereLight( 0xfff0f0, 0x60606, 3 );
light.position.set( 1, 1, 1 );
scene.add( light );

const train = new THREE.Object3D();
scene.add( train );

const camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.1, 500 );
train.add( camera );

// environment

geometry = new THREE.PlaneGeometry( 500, 500, 15, 15 );
geometry.rotateX( - Math.PI / 2 );

const positions = geometry.attributes.position.array;
const vertex = new THREE.Vector3();

for ( let i = 0; i < positions.length; i += 3 ) {

	vertex.fromArray( positions, i );

	vertex.x += Math.random() * 10 - 5;
	vertex.z += Math.random() * 10 - 5;

	const distance = ( vertex.distanceTo( scene.position ) / 5 ) - 25;
	vertex.y = Math.random() * Math.max( 0, distance );

	vertex.toArray( positions, i );

}

geometry.computeVertexNormals();

material = new THREE.MeshLambertMaterial( {
	color: 0x407000
} );

mesh = new THREE.Mesh( geometry, material );
scene.add( mesh );

geometry = new TreesGeometry( mesh );
material = new THREE.MeshBasicMaterial( {
	side: THREE.DoubleSide, vertexColors: true
} );
mesh = new THREE.Mesh( geometry, material );
scene.add( mesh );

geometry = new SkyGeometry();
material = new THREE.MeshBasicMaterial( { color: 0xffffff } );
mesh = new THREE.Mesh( geometry, material );
scene.add( mesh );

//

const PI2 = Math.PI * 2;

const curve = ( function () {

	const vector = new THREE.Vector3();
	const vector2 = new THREE.Vector3();

	return {

		getPointAt: function ( t ) {

			t = t * PI2;

			const x = Math.sin( t * 3 ) * Math.cos( t * 4 ) * 50;
			const y = Math.sin( t * 10 ) * 2 + Math.cos( t * 17 ) * 2 + 5;
			const z = Math.sin( t ) * Math.sin( t * 4 ) * 50;

			return vector.set( x, y, z ).multiplyScalar( 2 );

		},

		getTangentAt: function ( t ) {

			const delta = 0.0001;
			const t1 = Math.max( 0, t - delta );
			const t2 = Math.min( 1, t + delta );

			return vector2.copy( this.getPointAt( t2 ) )
				.sub( this.getPointAt( t1 ) ).normalize();

		}

	};

} )();

geometry = new RollerCoasterGeometry( curve, 1500 );
material = new THREE.MeshPhongMaterial( {
	vertexColors: true
} );
mesh = new THREE.Mesh( geometry, material );
scene.add( mesh );

geometry = new RollerCoasterLiftersGeometry( curve, 100 );
material = new THREE.MeshPhongMaterial();
mesh = new THREE.Mesh( geometry, material );
mesh.position.y = 0.1;
scene.add( mesh );

geometry = new RollerCoasterShadowGeometry( curve, 500 );
material = new THREE.MeshBasicMaterial( {
	color: 0x305000, depthWrite: false, transparent: true
} );
mesh = new THREE.Mesh( geometry, material );
mesh.position.y = 0.1;
scene.add( mesh );

const funfairs = [];

//

geometry = new THREE.CylinderGeometry( 10, 10, 5, 15 );
material = new THREE.MeshLambertMaterial( {
	color: 0xff8080
} );
mesh = new THREE.Mesh( geometry, material );
mesh.position.set( - 80, 10, - 70 );
mesh.rotation.x = Math.PI / 2;
scene.add( mesh );

funfairs.push( mesh );

geometry = new THREE.CylinderGeometry( 5, 6, 4, 10 );
material = new THREE.MeshLambertMaterial( {
	color: 0x8080ff
} );
mesh = new THREE.Mesh( geometry, material );
mesh.position.set( 50, 2, 30 );
scene.add( mesh );

funfairs.push( mesh );

//

window.addEventListener( 'resize', onWindowResize );

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

const position = new THREE.Vector3();
const tangent = new THREE.Vector3();

const lookAt = new THREE.Vector3();

const tangent1 = new THREE.Vector3();
const tangent2 = new THREE.Vector3();
const bankQuaternion = new THREE.Quaternion();

let velocity = 0;
let progress = 0;

let prevTime = performance.now();

function animate() {

	const time = performance.now();
	const delta = time - prevTime;

	for ( let i = 0; i < funfairs.length; i ++ ) {

		funfairs[ i ].rotation.y = time * 0.0004;

	}

	//

	progress += velocity;
	progress = progress % 1;

	position.copy( curve.getPointAt( progress ) );
	position.y += 0.3;

	train.position.copy( position );

	tangent.copy( curve.getTangentAt( progress ) );

	velocity -= tangent.y * 0.0000001 * delta;
	velocity = Math.max( 0.00004, Math.min( 0.0002, velocity ) );

	// banking

	const bankDelta = 0.01;
	const t1 = ( ( progress - bankDelta ) % 1 + 1 ) % 1;
	const t2 = ( progress + bankDelta ) % 1;

	tangent1.copy( curve.getTangentAt( t1 ) );
	tangent2.copy( curve.getTangentAt( t2 ) );

	let headingChange = Math.atan2( tangent2.x, tangent2.z ) - Math.atan2( tangent1.x, tangent1.z );
	if ( headingChange > Math.PI ) headingChange -= Math.PI * 2;
	if ( headingChange < - Math.PI ) headingChange += Math.PI * 2;

	train.up.set( 0, 1, 0 );
	bankQuaternion.setFromAxisAngle( tangent, - Math.atan( headingChange * 8 ) * 0.5 );
	train.up.applyQuaternion( bankQuaternion );

	train.lookAt( lookAt.copy( position ).sub( tangent ) );

	//

	renderPipeline.render( scene, camera );

	prevTime = time;

}

import * as THREE from 'three/webgpu';

import { VRButton } from 'three/addons/webxr/VRButton.js';
import { setupWebGLXRFallback } from 'three/addons/webxr/WebGLXRFallback.js';

const rendererParameters = { antialias: true, outputBufferType: THREE.UnsignedByteType, multiview: false };
const timer = new THREE.Timer();
timer.connect( document );

let camera, cameraRig, scene, renderer;
let directionalLight, torusKnot, box, icosahedron, cone, glass;

init();

function init() {

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x24282f );
	scene.fog = new THREE.Fog( 0x24282f, 8, 16 );

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.1, 30 );
	camera.position.y = 1.6;

	cameraRig = new THREE.Group();
	cameraRig.position.z = 4;
	cameraRig.add( camera );
	scene.add( cameraRig );

	// lights

	scene.add( new THREE.HemisphereLight( 0xb8c5df, 0x3c3028, 1.5 ) );

	directionalLight = new THREE.DirectionalLight( 0xfff1d6, 4 );
	directionalLight.position.set( - 4, 6, 2 );
	directionalLight.castShadow = true;
	directionalLight.shadow.camera.near = 0.1;
	directionalLight.shadow.camera.far = 15;
	directionalLight.shadow.camera.left = - 5;
	directionalLight.shadow.camera.right = 5;
	directionalLight.shadow.camera.top = 5;
	directionalLight.shadow.camera.bottom = - 5;
	directionalLight.shadow.mapSize.set( 2048, 2048 );
	directionalLight.shadow.bias = - 0.0005;
	scene.add( directionalLight );
	scene.add( directionalLight.target );

	// environment

	const floor = new THREE.Mesh(
		new THREE.PlaneGeometry( 14, 14 ),
		new THREE.MeshStandardMaterial( { color: 0x73786f, roughness: 0.9 } )
	);
	floor.rotation.x = - Math.PI / 2;
	floor.receiveShadow = true;
	scene.add( floor );

	const platform = new THREE.Mesh(
		new THREE.CylinderGeometry( 1.25, 1.4, 0.3, 64 ),
		new THREE.MeshStandardMaterial( { color: 0x40464d, roughness: 0.6, metalness: 0.2 } )
	);
	platform.position.y = 0.15;
	platform.castShadow = true;
	platform.receiveShadow = true;
	scene.add( platform );

	// shadow casters

	torusKnot = new THREE.Mesh(
		new THREE.TorusKnotGeometry( 0.55, 0.18, 128, 24 ),
		new THREE.MeshStandardMaterial( { color: 0xe7ad52, roughness: 0.25, metalness: 0.35 } )
	);
	torusKnot.position.y = 1.35;
	torusKnot.castShadow = true;
	torusKnot.receiveShadow = true;
	scene.add( torusKnot );

	box = new THREE.Mesh(
		new THREE.BoxGeometry( 0.7, 0.7, 0.7 ),
		new THREE.MeshStandardMaterial( { color: 0xd85f50, roughness: 0.5 } )
	);
	box.position.set( - 1.8, 0.6, 0.25 );
	box.rotation.set( 0.2, 0.4, 0.1 );
	box.castShadow = true;
	box.receiveShadow = true;
	scene.add( box );

	icosahedron = new THREE.Mesh(
		new THREE.IcosahedronGeometry( 0.5, 2 ),
		new THREE.MeshStandardMaterial( { color: 0x4f91b8, roughness: 0.35, metalness: 0.15 } )
	);
	icosahedron.position.set( 1.8, 0.7, 0.1 );
	icosahedron.castShadow = true;
	icosahedron.receiveShadow = true;
	scene.add( icosahedron );

	cone = new THREE.Mesh(
		new THREE.ConeGeometry( 0.5, 1.1, 48 ),
		new THREE.MeshStandardMaterial( { color: 0x68a66b, roughness: 0.65 } )
	);
	cone.position.set( 0, 0.55, - 2 );
	cone.castShadow = true;
	cone.receiveShadow = true;
	scene.add( cone );

	// transmission

	glass = new THREE.Mesh(
		new THREE.IcosahedronGeometry( 0.65, 4 ),
		new THREE.MeshPhysicalMaterial( {
			color: 0xb9e7ff,
			roughness: 0.05,
			metalness: 0,
			transmission: 1,
			thickness: 0.9,
			ior: 1.45,
			attenuationColor: 0x72b5d4,
			attenuationDistance: 3,
			specularIntensity: 1,
			side: THREE.DoubleSide
		} )
	);
	glass.position.set( 0.9, 1.15, 1.2 );
	glass.castShadow = true;
	glass.receiveShadow = true;
	scene.add( glass );

	// renderer

	renderer = createRenderer();
	setRenderer( renderer );
	setupWebGLXRFallback( renderer, () => createRenderer( true ), setRenderer );

	document.body.appendChild( VRButton.createButton( renderer, { optionalFeatures: [ 'webgpu' ] } ) );

	window.addEventListener( 'resize', onWindowResize );

}

function createRenderer( forceWebGL = false ) {

	const parameters = { ...rendererParameters };

	if ( forceWebGL === true ) parameters.forceWebGL = true;

	const renderer = new THREE.WebGPURenderer( parameters );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.shadowMap.type = THREE.PCFShadowMap;
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.toneMappingExposure = 1.2;
	renderer.xr.enabled = true;

	return renderer;

}

function setRenderer( newRenderer, oldRenderer = null ) {

	if ( oldRenderer === null ) {

		document.body.appendChild( newRenderer.domElement );

	} else {

		document.body.replaceChild( newRenderer.domElement, oldRenderer.domElement );
		oldRenderer.dispose();

	}

	renderer = newRenderer;

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

function animate() {

	timer.update();

	const elapsed = timer.getElapsed();
	const delta = timer.getDelta();

	torusKnot.position.y = 1.35 + Math.sin( elapsed * 1.5 ) * 0.15;
	torusKnot.rotation.x += delta * 0.35;
	torusKnot.rotation.y += delta * 0.7;

	box.rotation.y += delta * 0.4;
	icosahedron.rotation.x += delta * 0.3;
	icosahedron.rotation.y -= delta * 0.5;
	cone.rotation.y -= delta * 0.35;
	glass.position.y = 1.15 + Math.sin( elapsed * 1.1 ) * 0.08;
	glass.rotation.x -= delta * 0.2;
	glass.rotation.y += delta * 0.3;

	directionalLight.position.x = Math.cos( elapsed * 0.25 ) * 4;
	directionalLight.position.z = Math.sin( elapsed * 0.25 ) * 4;

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import { ARButton } from 'three/addons/webxr/ARButton.js';

const timer = new THREE.Timer();
timer.connect( document );

let camera, scene, renderer;
let cube;

init();

async function init() {

	const container = document.createElement( 'div' );
	document.body.appendChild( container );

	scene = new THREE.Scene();

	camera = new THREE.PerspectiveCamera( 70, window.innerWidth / window.innerHeight, 0.01, 20 );

	const defaultLight = new THREE.HemisphereLight( 0xffffff, 0xbbbbff, 3 );
	defaultLight.position.set( 0.5, 1, 0.25 );
	scene.add( defaultLight );

	//

	renderer = new THREE.WebGLRenderer( { antialias: true, alpha: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.xr.enabled = true;
	container.appendChild( renderer.domElement );

	//

	document.body.appendChild( ARButton.createButton( renderer, { requiredFeatures: [ 'camera-access' ] } ) );

	//

	const boxGeometry = new THREE.BoxGeometry( 1, 1, 1 );
	const boxMaterial = new THREE.MeshStandardMaterial();
	cube = new THREE.Mesh( boxGeometry, boxMaterial );
	cube.position.z = - 3;

	scene.add( cube );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function setCameraTexture() {

	if ( ! renderer.xr.getSession() ) {

		if ( cube.material.map ) {

			cube.material.map = null;
			cube.material.needsUpdate = true;

		}

		return;

	}

	const frame = renderer.xr.getFrame();
	const referenceSpace = renderer.xr.getReferenceSpace();

	if ( ! frame || ! referenceSpace ) return;

	const viewerPose = frame.getViewerPose( referenceSpace );

	if ( ! viewerPose ) return;

	const view = viewerPose.views.find( view => view.camera );

	const cameraTexture = renderer.xr.getCameraTexture( view.camera );

	if ( cube.material.map === cameraTexture ) return;

	cube.material.map = cameraTexture;
	cube.material.needsUpdate = true;

}

function animate() {

	timer.update();

	const delta = timer.getDelta();

	setCameraTexture();

	cube.rotation.x += delta;
	cube.rotation.y += delta;

	renderer.render( scene, camera );

}

