	document.body.appendChild( container );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x808080 );

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.1, 10 );
	camera.position.set( 0, 1.6, 0 );

	const floorGeometry = new THREE.PlaneGeometry( 6, 6 );
	const floorMaterial = new THREE.ShadowMaterial( { opacity: 0.25, blending: THREE.CustomBlending, transparent: false } );
	const floor = new THREE.Mesh( floorGeometry, floorMaterial );
	floor.rotation.x = - Math.PI / 2;
	floor.receiveShadow = true;
	scene.add( floor );

	scene.add( new THREE.HemisphereLight( 0xbcbcbc, 0xa5a5a5, 3 ) );

	const light = new THREE.DirectionalLight( 0xffffff, 3 );
	light.position.set( 0, 6, 0 );
	light.castShadow = true;
	light.shadow.camera.top = 3;
	light.shadow.camera.bottom = - 3;
	light.shadow.camera.right = 3;
	light.shadow.camera.left = - 3;
	light.shadow.mapSize.set( 4096, 4096 );
	scene.add( light );

	group = new THREE.Group();
	scene.add( group );

	const geometries = [
		new THREE.BoxGeometry( 0.2, 0.2, 0.2 ),
		new THREE.ConeGeometry( 0.2, 0.4, 64 ),
		new THREE.CylinderGeometry( 0.2, 0.2, 0.2, 64 ),
		new THREE.IcosahedronGeometry( 0.2, 8 ),
		new THREE.TorusGeometry( 0.2, 0.04, 64, 32 )
	];

	for ( let i = 0; i < 16; i ++ ) {

		const geometry = geometries[ Math.floor( Math.random() * geometries.length ) ];
		const material = new THREE.MeshStandardMaterial( {
			color: Math.random() * 0xffffff,
			roughness: 0.7,
			metalness: 0.0
		} );

		const object = new THREE.Mesh( geometry, material );

		object.position.x = Math.random() - 0.5;
		object.position.y = Math.random() * 2 + 0.5;
		object.position.z = Math.random() - 2.5;

		object.rotation.x = Math.random() * 2 * Math.PI;
		object.rotation.y = Math.random() * 2 * Math.PI;
		object.rotation.z = Math.random() * 2 * Math.PI;

		object.scale.setScalar( Math.random() + 0.5 );

		object.castShadow = true;
		object.receiveShadow = true;

		group.add( object );

	}

	//

	renderer = new THREE.WebGLRenderer( { antialias: true, outputBufferType: THREE.HalfFloatType } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.shadowMap.enabled = true;
	renderer.toneMapping = THREE.ACESFilmicToneMapping;
	renderer.xr.enabled = true;
	container.appendChild( renderer.domElement );

	// post-processing

	bloomPass = new UnrealBloomPass( new THREE.Vector2( window.innerWidth, window.innerHeight ), 1.5, 0.4, 0.85 );
	renderer.setEffects( [ bloomPass ] );

	document.body.appendChild( XRButton.createButton( renderer ) );

	// controllers

	controller1 = renderer.xr.getController( 0 );
	controller1.addEventListener( 'select', onSelect );
	controller1.addEventListener( 'selectstart', onControllerEvent );
	controller1.addEventListener( 'selectend', onControllerEvent );
	controller1.addEventListener( 'move', onControllerEvent );
	controller1.userData.active = false;
	scene.add( controller1 );

	controller2 = renderer.xr.getController( 1 );
	controller2.addEventListener( 'select', onSelect );
	controller2.addEventListener( 'selectstart', onControllerEvent );
	controller2.addEventListener( 'selectend', onControllerEvent );
	controller2.addEventListener( 'move', onControllerEvent );
	controller2.userData.active = true;
	scene.add( controller2 );

	const controllerModelFactory = new XRControllerModelFactory();

	controllerGrip1 = renderer.xr.getControllerGrip( 0 );
	controllerGrip1.add( controllerModelFactory.createControllerModel( controllerGrip1 ) );
	scene.add( controllerGrip1 );

	controllerGrip2 = renderer.xr.getControllerGrip( 1 );
	controllerGrip2.add( controllerModelFactory.createControllerModel( controllerGrip2 ) );
	scene.add( controllerGrip2 );

	//

	const geometry = new THREE.BufferGeometry().setFromPoints( [ new THREE.Vector3( 0, 0, 0 ), new THREE.Vector3( 0, 0, - 1 ) ] );

	line = new THREE.Line( geometry );
	line.name = 'line';
	line.scale.z = 5;

	raycaster = new THREE.Raycaster();

	// controls

	controls = new TransformControls( camera, renderer.domElement );
	controls.attach( group.children[ 0 ] );
	scene.add( controls.getHelper() );

	//

	window.addEventListener( 'resize', onWindowResize );

}

function onSelect( event ) {

	const controller = event.target;

	controller1.userData.active = false;
	controller2.userData.active = false;

	if ( controller === controller1 ) {

		controller1.userData.active = true;
		controller1.add( line );

	}

	if ( controller === controller2 ) {

		controller2.userData.active = true;
		controller2.add( line );

	}

	raycaster.setFromXRController( controller );

	const intersects = raycaster.intersectObjects( group.children );

	if ( intersects.length > 0 ) {

		controls.attach( intersects[ 0 ].object );

	}

}

function onControllerEvent( event ) {

	const controller = event.target;

	if ( controller.userData.active === false ) return;

	controls.getRaycaster().setFromXRController( controller );

	switch ( event.type ) {

		case 'selectstart':
			controls.pointerDown( null );
			break;

		case 'selectend':
			controls.pointerUp( null );
			break;

		case 'move':
			controls.pointerHover( null );
			controls.pointerMove( null );
			break;

	}

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function animate() {

	renderer.render( scene, camera );

}

import * as THREE from 'three';

import { BoxLineGeometry } from 'three/addons/geometries/BoxLineGeometry.js';
import { XRButton } from 'three/addons/webxr/XRButton.js';
import { XRControllerModelFactory } from 'three/addons/webxr/XRControllerModelFactory.js';

const timer = new THREE.Timer();
timer.connect( document );

let container;
let camera, scene, raycaster, renderer;

let room;

let controller, controllerGrip;
let INTERSECTED;

init();

function init() {

	container = document.createElement( 'div' );
	document.body.appendChild( container );

	scene = new THREE.Scene();
	scene.background = new THREE.Color( 0x505050 );

	camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 0.1, 10 );
	camera.position.set( 0, 1.6, 3 );
	scene.add( camera );

	room = new THREE.LineSegments(
		new BoxLineGeometry( 6, 6, 6, 10, 10, 10 ).translate( 0, 3, 0 ),
		new THREE.LineBasicMaterial( { color: 0xbcbcbc } )
	);
	scene.add( room );

	scene.add( new THREE.HemisphereLight( 0xa5a5a5, 0x898989, 3 ) );

	const light = new THREE.DirectionalLight( 0xffffff, 3 );
	light.position.set( 1, 1, 1 ).normalize();
	scene.add( light );

	const geometry = new THREE.BoxGeometry( 0.15, 0.15, 0.15 );

	for ( let i = 0; i < 200; i ++ ) {

		const object = new THREE.Mesh( geometry, new THREE.MeshLambertMaterial( { color: Math.random() * 0xffffff } ) );

		object.position.x = Math.random() * 4 - 2;
		object.position.y = Math.random() * 4;
		object.position.z = Math.random() * 4 - 2;

		object.rotation.x = Math.random() * 2 * Math.PI;
		object.rotation.y = Math.random() * 2 * Math.PI;
		object.rotation.z = Math.random() * 2 * Math.PI;

		object.scale.x = Math.random() + 0.5;
		object.scale.y = Math.random() + 0.5;
		object.scale.z = Math.random() + 0.5;

		object.userData.velocity = new THREE.Vector3();
		object.userData.velocity.x = Math.random() * 0.01 - 0.005;
		object.userData.velocity.y = Math.random() * 0.01 - 0.005;
		object.userData.velocity.z = Math.random() * 0.01 - 0.005;

		room.add( object );

	}

	raycaster = new THREE.Raycaster();

	renderer = new THREE.WebGLRenderer( { antialias: true } );
	renderer.setPixelRatio( window.devicePixelRatio );
	renderer.setSize( window.innerWidth, window.innerHeight );
	renderer.setAnimationLoop( animate );
	renderer.xr.enabled = true;
	container.appendChild( renderer.domElement );

	//

	function onSelectStart() {

		this.userData.isSelecting = true;

	}

	function onSelectEnd() {

		this.userData.isSelecting = false;

	}

	controller = renderer.xr.getController( 0 );
	controller.addEventListener( 'selectstart', onSelectStart );
	controller.addEventListener( 'selectend', onSelectEnd );
	controller.addEventListener( 'connected', function ( event ) {

		this.add( buildController( event.data ) );

	} );
	controller.addEventListener( 'disconnected', function () {

		this.remove( this.children[ 0 ] );

	} );
	scene.add( controller );

	const controllerModelFactory = new XRControllerModelFactory();

	controllerGrip = renderer.xr.getControllerGrip( 0 );
	controllerGrip.add( controllerModelFactory.createControllerModel( controllerGrip ) );
	scene.add( controllerGrip );

	window.addEventListener( 'resize', onWindowResize );

	//

	document.body.appendChild( XRButton.createButton( renderer, {
		'optionalFeatures': [ 'depth-sensing' ],
		'depthSensing': { 'usagePreference': [ 'gpu-optimized' ], 'dataFormatPreference': [] }
	} ) );

}

function buildController( data ) {

	let geometry, material;

	switch ( data.targetRayMode ) {

		case 'tracked-pointer':

			geometry = new THREE.BufferGeometry();
			geometry.setAttribute( 'position', new THREE.Float32BufferAttribute( [ 0, 0, 0, 0, 0, - 1 ], 3 ) );
			geometry.setAttribute( 'color', new THREE.Float32BufferAttribute( [ 0.5, 0.5, 0.5, 0, 0, 0 ], 3 ) );

			material = new THREE.LineBasicMaterial( { vertexColors: true, blending: THREE.AdditiveBlending } );

			return new THREE.Line( geometry, material );

		case 'gaze':

			geometry = new THREE.RingGeometry( 0.02, 0.04, 32 ).translate( 0, 0, - 1 );
			material = new THREE.MeshBasicMaterial( { opacity: 0.5, transparent: true } );
			return new THREE.Mesh( geometry, material );

	}

}

function onWindowResize() {

	camera.aspect = window.innerWidth / window.innerHeight;
	camera.updateProjectionMatrix();

	renderer.setSize( window.innerWidth, window.innerHeight );

}

//

function animate() {

	timer.update();

	const delta = timer.getDelta() * 60;

	if ( controller.userData.isSelecting === true ) {

		const cube = room.children[ 0 ];
		room.remove( cube );

		cube.position.copy( controller.position );
		cube.userData.velocity.x = ( Math.random() - 0.5 ) * 0.02 * delta;
		cube.userData.velocity.y = ( Math.random() - 0.5 ) * 0.02 * delta;
		cube.userData.velocity.z = ( Math.random() * 0.01 - 0.05 ) * delta;
		cube.userData.velocity.applyQuaternion( controller.quaternion );
		room.add( cube );

	}

	// find intersections

	raycaster.setFromXRController( controller );

	const intersects = raycaster.intersectObjects( room.children, false );

	if ( intersects.length > 0 ) {

		if ( INTERSECTED != intersects[ 0 ].object ) {

			if ( INTERSECTED ) INTERSECTED.material.emissive.setHex( INTERSECTED.currentHex );

			INTERSECTED = intersects[ 0 ].object;
			INTERSECTED.currentHex = INTERSECTED.material.emissive.getHex();
			INTERSECTED.material.emissive.setHex( 0xff0000 );

		}

	} else {

		if ( INTERSECTED ) INTERSECTED.material.emissive.setHex( INTERSECTED.currentHex );

		INTERSECTED = undefined;

	}

	// Keep cubes inside room

	for ( let i = 0; i < room.children.length; i ++ ) {

		const cube = room.children[ i ];

		cube.userData.velocity.multiplyScalar( 1 - ( 0.001 * delta ) );

		cube.position.add( cube.userData.velocity );

		if ( cube.position.x < - 3 || cube.position.x > 3 ) {

			cube.position.x = THREE.MathUtils.clamp( cube.position.x, - 3, 3 );
			cube.userData.velocity.x = - cube.userData.velocity.x;

		}

		if ( cube.position.y < 0 || cube.position.y > 6 ) {

			cube.position.y = THREE.MathUtils.clamp( cube.position.y, 0, 6 );
			cube.userData.velocity.y = - cube.userData.velocity.y;

		}

		if ( cube.position.z < - 3 || cube.position.z > 3 ) {

			cube.position.z = THREE.MathUtils.clamp( cube.position.z, - 3, 3 );
			cube.userData.velocity.z = - cube.userData.velocity.z;

		}

		cube.rotation.x += cube.userData.velocity.x * 2 * delta;
		cube.rotation.y += cube.userData.velocity.y * 2 * delta;
		cube.rotation.z += cube.userData.velocity.z * 2 * delta;

	}

	renderer.render( scene, camera );

}

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
